/* serviceMember help. Loaded the first time ? opens. Not a first-paint script. */
(function (global) {
  "use strict";
  const entries = [{"id":"help-search-settings-appearance","title":"Settings on Search","body":"On the Home Search screen, tap Settings to open Profile & Settings on the Appearance tab — Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green) lives there. The Settings tile uses the same chrome icon pack as the other Search marks.","steps":[],"links":[{"label":"Open Appearance","href":"./patron-portal.html?from=search&tab=appearance"}],"searchPhrases":["settings","appearance","site chrome","search settings","theme settings","change chrome","Settings on Search","Open Appearance"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"index.html#settingsBtnCard","kind":"help"},{"id":"help-botdee-memory","title":"BOT DEE saved chats","body":"Open Feature & Orders → My BOT DEE to save chats after the pause, export, or delete history. The five-minute pause ends the live BOT DEE session. If you opt in, BOT DEE keeps that chat so you can come back later. Guests are not saved. Mingl conversations stay in Mingl.","steps":[],"links":[{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"},{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["saved chat","bot dee memory","opt in history","export bot dee","delete bot dee history","pause vs save","five minute pause","300 seconds","my bot dee","feature and orders","memory settings","BOT DEE saved chats","My BOT DEE","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#foBotDeePane","kind":"help"},{"id":"help-botdee-knows-of-me","title":"What BOT DEE knows of me","body":"Facts BOT DEE stored with your approval live in Feature & Orders → My BOT DEE. The list is empty if memory is off or nothing is stored. Export or delete facts here. BOT DEE never stores your IP address. Mingl chats are not copied.","steps":[],"links":[{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["what bot dee knows","bot dee facts","approved facts","delete fact","personalize","dsar","my bot dee","What BOT DEE knows of me","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#foBotDeePane","kind":"help"},{"id":"help-botdee-version-smartview","title":"Version SMARTview","body":"Type Ver, Vers, or Version — capitals do not matter. BOT DEE shows the version card. A longer question like “what is your version?” still shows that card.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["version smartview","ver command","vers command","version command","bot dee version","floqr version","what version is bot dee","Version SMARTview","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-version-smartview-status","title":"Version SMARTview status is a live probe","body":"Service status is probed on this Version request: Functions and package reachable with Gemini configured → Operational; Functions and package up but Gemini not configured → Degraded; Functions not in this request → Unavailable. It is never a static Not checked label. AI model shows the configured Gemini model id for this deployment even when this turn did not generate. Frontend and backend package stamps can differ; both are labeled. Master Admin may see extra diagnostics after Technical Details — patrons do not.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["version operational","not checked","bot dee health","service status smartview","gemini version card","Version SMARTview status is a live probe","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-version-smartview-tabs","title":"Version SMARTview tabs","body":"Overview describes BOT DEE and opens Technical Details without leaving chat. What's New lists verified BOT DEE and Gemini changes only — not Master Admin, beta tester tools, or other FLOQR product notes. Help repeats the Ver / Vers / Version command. Switching tabs or expanding details keeps your unsent draft and scroll. The card uses your Site Chrome — there is no second theme.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["version what's new","version overview","technical details bot dee","version smartview tabs","bot dee what's new","gemini what's new","Version SMARTview tabs","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview","title":"Room SMARTview","body":"In BOT DEE chat, say Open Room SMARTview, Start a group chat, or plan a Cancun trip in plain words. Confirm shows Join Now or Set a schedule. Join Now opens a Mingl-friends session now and does not paint Search. Set a schedule is when the BOT DEE room starts — not Shared Itinerary — and turns on Search SMARTnotification for you and invited Mingl friends. Invite Mingl friends only — host plus 7 guests. Guests can invite too. Joining is not a payment and does not open a shared tab. BOT DEE never takes card numbers. Private BOT DEE messages stay private. Site Chrome follows your Appearance theme. A live room stays open until the host taps End Room, about four hours after it opens, or everyone has been gone about 15 minutes. Pausing private BOT DEE chat is separate.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["room smartview","start a group chat","open room smartview","create a room","group chat bot dee","talk to bot dee together","invite mingl friends","let's plan our cancun trip","let's plan a trip to cancun","plan a cancun trip","cancun trip with friends","schedule a room","join now or set a schedule","when does the room expire","last person logs out","one-time live session","Room SMARTview","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-smartvisuals-notification","title":"Mingl Room SMARTnotification","body":"A compact Mingl Room Invitation can appear on Search when a Mingl friend scheduled a BOT DEE room you were invited to. View Invitation opens Room SMARTview. Join Now goes to BOT DEE, not Mingl chat. Not Now hides the card this tab; Inbox still has Review BOT DEE invite. The Cancun demo query is Studio-only. Art is illustration, not a photo. Join Now rooms without a schedule do not paint Search.","steps":[],"links":[{"label":"Open Search","href":"./?start=search"}],"searchPhrases":["smartnotification","smart notification","mingl room invitation","view invitation","join at scheduled time","cancun trip","smartvisuals","smartstencils","smartbackgrounds","travel partner","fly to cancun","labeled ad","Mingl Room SMARTnotification","Open Search"],"audiences":["patron","serviceMember","venueAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"index.html#categoryPage","kind":"help"},{"id":"help-smartvisuals-room","title":"Room SMARTview with SMARTvisuals","body":"Room SMARTview shows the Mingl invitation: schedule, RSVP or live status, and Join Now. Join Now on Search opens BOT DEE (not Mingl chat) with room= and t=. SMARTstencils and SMARTbackgrounds follow the authorized room title — Cancun Trip uses travel art, not a real Cancun photo. Private BOT DEE chat is never used to pick art. A labeled Ad below is a sample from those tags. It stays empty for private chat or injection and is not a live advertiser.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["room smartview invitation","join now mingl","join at scheduled time","smartstencils","smartbackgrounds","cancun trip room","bot-dee itinerary","travel partner","exclusive mingl room deals","Room SMARTview with SMARTvisuals","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"index.html#categoryPage","kind":"help"},{"id":"help-botdee-room-smartview-schedule","title":"Join Now or set a schedule","body":"After Room SMARTview setup, choose Join Now or Set a schedule. Join Now opens the BOT DEE session now and does not put a card on Search. Set a schedule is when the BOT DEE room starts — not Shared Itinerary. Saving a future time turns on Search SMARTnotification for you and invited Mingl friends only. Guests RSVP until the room is live, then Join Now opens BOT DEE (not Mingl chat).","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["join now or set a schedule","set a schedule","schedule a room","join at scheduled time","smartnotification search","when does the room start","Join Now or set a schedule","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview-invite","title":"Invite Mingl friends","body":"After you confirm Room SMARTview, Invite shows your Mingl friends only. Tap a friend to send an Inbox invite (Review BOT DEE invite). If a chip is you or someone already in the session, it stays marked That's you or Already in this session and does not send another invite. Not a public join link. Cap is host plus 7. Guests can invite more Mingl friends unless the host turns that off. Joining is not a payment.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["invite others to this chat","invite friends bot dee","bring my friends into this conversation","invite mingl friends","review bot dee invite","that's you","already in this session","cannot invite myself","Invite Mingl friends","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview-join","title":"Join a BOT DEE session","body":"Open the Inbox invite while signed in as the Mingl friend it was sent to. Wrong account, expired, or revoked invites refuse. Joining the room is not joining a shared tab and does not approve a payment. BOT DEE never takes card numbers.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["join room smartview","join this bot dee chat","can my friends join us","Join a BOT DEE session","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview-end","title":"End Room SMARTview","body":"Only the host can end a room. Ending does not charge anyone or erase other people’s private chats. An unpaid shared tab must be paid or voided first. A live room stays open until End Room, about four hours after it opens, or everyone has been gone about 15 minutes. Pausing private BOT DEE chat is not room logout. A guest leaving does not end the room while the host is still present.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["end this room","close room smartview","end group chat bot dee","when does the room expire","last person logs out","End Room SMARTview","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview-tab","title":"Room SMARTview shared tab","body":"Opt in first. Then add a line. Close as one payer or split. Only confirming uids are charged, via FloqR Stripe. Joining the room does not join a tab. BOT DEE never takes card numbers. Club POS is later.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["shared tab","split the bill","who is paying room","pay together bot dee","Room SMARTview shared tab","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview-who-pays","title":"Who is paying","body":"Ask Who’s paying in a Room SMARTview to see opt-in status. Nobody is charged because someone said buy. Card last four stay on the payer’s own receipt.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["who's paying","who is paying","who pays in the room","Who is paying","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview-kick","title":"Remove someone from Room SMARTview","body":"Only the host can remove a guest. A kicked friend cannot read further room messages. A model reply cannot kick anyone.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["remove from room","kick from room smartview","remove jalen","Remove someone from Room SMARTview","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview-share","title":"Share into Room SMARTview","body":"Share this conversation never copies your private BOT DEE thread. BOT DEE shows a preview of selected shareable facts from this message, marked tentative. You can edit or drop facts. Private profiles and SMARTsummary stay out.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["share this conversation","share our plans","share with my friends bot dee","Share into Room SMARTview","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-collab","title":"Share a headless booking in Room SMARTview","body":"When you are in a Room SMARTview, the host's VIP reserV or ShoutOut picks appear for everyone in the session. Members vote Yes or No. Hold it and pay stay with the host — joining and voting are not a payment. BOT DEE never takes card numbers. Stripe still opens in a pop-out.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["vote the table","share vip reserv","vote host pick","headless booking vote","shared picks room smartview","Share a headless booking in Room SMARTview","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-elect-host","title":"Elect a Room SMARTview host","body":"Anyone in the session can be host. Nominate yourself or another joined member. A candidate becomes host at 60 percent of currently joined members (rounded up). If the host leaves, remaining members elect a new host — the room stays open. Kick and End stay with the elected host.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["make me host","elect host","vote for host","60 percent host","change room host","Elect a Room SMARTview host","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-smartview","title":"View my SMARTview","body":"View my SMARTview shows your People card from public-within-FLOQR fields, using the same Profile Media as your FLOQR public page — not venue or restaurant mocks. Edit my SMARTsummary changes the text in your default profile language. Save translates it to every other FLOQR language, including English. Master Admin → Features → BOT DEE → SMARTviews is where labeled mock venue and restaurant cards live. There is no live Places or Yelp.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"},{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"},{"label":"SMARTviews (Master Admin)","href":"./master-admin.html#featuresBotDee-smartviews"}],"searchPhrases":["smartview","smart view","view my smartview","venue card","restaurant card","public page","mock smartview","people smartview","person card","edit my smart summary","smartsummary","edit my smartsummary","View my SMARTview","Open BOT DEE","My BOT DEE","SMARTviews (Master Admin)"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"master-admin.html#featuresBotDee","kind":"help"},{"id":"help-botdee-smartview-edit","title":"Edit your SMARTsummary","body":"Only you can edit your SMARTsummary, in your default profile language. That language is the source — English is the source only when your default is English. Save is immediate. FLOQR then translates SMARTsummary into every other supported language, including English. Gemini will not overwrite text you edited unless you ask it to regenerate. If your public profile changes, FLOQR asks you to review the summary instead of replacing it.","steps":[],"links":[{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["edit smart summary","edit my smartview","owner authored summary","regenerate summary","smartsummary","edit smartsummary","Edit your SMARTsummary","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#foBotDeePane","kind":"help"},{"id":"help-botdee-smartview-translation","title":"How SMARTview translation works","body":"Your SMARTsummary is stored in your default profile language — that language is the source, even when it is not English. After you save, FLOQR queues a translation to every other supported language, including English. An English viewer sees the English SMARTsummary once that job finishes. While a translation is pending or failed, viewers see the source language with a clear label — never a stale translation presented as current.","steps":[],"links":[{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["smartview translation","translation pending","source language summary","stale translation","english translation","smartsummary translation","How SMARTview translation works","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#foBotDeePane","kind":"help"},{"id":"help-botdee-smartview-privacy","title":"SMARTview privacy and visibility","body":"SMARTview shows only fields you already made public within FLOQR. It is not open-web search. Dating appears only with explicit opt-in. Hide a field in My Profile and it leaves SMARTview. Blocked people cannot see your card. Report an incorrect summary from the summary overlay.","steps":[],"links":[{"label":"Profile visibility","href":"./patron-portal.html?tab=profile"},{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["smartview privacy","who can see smartview","dating opt in","hide smartview field","SMARTview privacy and visibility","Profile visibility","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html","kind":"help"},{"id":"help-botdee-smartview-media","title":"SMARTview photos and videos","body":"The compact card uses the same hero as your FLOQR public profile — the first Profile Media item (8 photos + 2 videos). Tap it for Photos and Videos from those public slots. Swipe or use arrows, then X (or Escape) to return to the same chat scroll and unsent draft.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["smartview photos","smartview videos","close overlay","escape smartview","SMARTview photos and videos","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-smartview-categories","title":"SMARTview categories","body":"Four tabs: Social, Dating, Dining, and Future Travels. Social opens on Music, then Nightlife, Sports, and Events. Tags are only what you shared — no duplicate headings and no invented trips, ratings, or relationships. Future travel shows only destinations you marked public.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["smartview categories","social music tab","dating dining travels","future travels smartview","SMARTview categories","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-smartview-chrome","title":"SMARTview and Site Chrome","body":"People SMARTview uses the viewing patron’s existing FLOQR Site Chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). There is no second theme setting. Changing chrome updates the card in place without losing your chat draft.","steps":[],"links":[{"label":"Appearance","href":"./patron-portal.html?tab=profile"}],"searchPhrases":["smartview chrome","black tiffany smartview","site chrome smartview","theme smartview","SMARTview and Site Chrome","Appearance"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-smartview-review","title":"Review and correct a SMARTsummary","body":"Gemini drafts the SMARTsummary in your default profile language from public-within-FLOQR fields only — never on each view. If a fact is wrong, hide the source field in Profile visibility or edit the SMARTsummary yourself. Owner-authored text is not overwritten. Profile changes that conflict with your summary ask for a review. Report an incorrect card from the summary overlay.","steps":[],"links":[{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["correct smart summary","wrong smartview","gemini overwrite","review smart summary","smartsummary","Review and correct a SMARTsummary","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#foBotDeePane","kind":"help"},{"id":"help-botdee-smartcard","title":"People SMARTcards","body":"When more than one public FLOQR profile matches, BOT DEE shows compact People SMARTcards in the chat: full-width photo first, then name and handle, then a compact SMARTsummary with no padded box. Tap a card to open that person’s full SMARTview — same stacked layout. Cards use the same public profile and SMARTsummary as SMARTview — not a second stored summary. Opening a card does not call Gemini.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"},{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["smartcard","smart card","people smartcard","who is","who am i","compact people card","select person smartview","People SMARTcards","Open BOT DEE","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-smartcard-search","title":"Ask BOT DEE who someone is","body":"Ask “Who am I?” to open your own SMARTview. Ask “Who is …”, “What do you know of …”, or “What about …” plus a first name, last name, display name, Mingl or FloqR handle, or a social handle (Instagram, TikTok, X). Matches use those identity fields only — not bios, likes, drinks, or genres. One match opens a People SMARTview card in the chat — not a markdown list or photo dump. Several matches show compact SMARTcards to pick from. Private, blocked, or unpublished profiles are not listed — BOT DEE will not confirm whether that account exists.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["who am i","who is","what do you know of","what about","tell me about","display name","find person on floqr","do you know this person","people search bot dee","lookup public profile","identity only","not bio","Ask BOT DEE who someone is","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-smartcard-sync","title":"SMARTsummary stays in sync","body":"Edit your SMARTsummary in your default profile language. Save is immediate. Cards and SMARTview already showing you update from the same record. Translations to other FLOQR languages run in the background and never overwrite a newer edit. If you hide your public profile, block someone, or delete the account, those cards disappear. Gemini does not overwrite text you wrote.","steps":[],"links":[{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["smartsummary sync","card update live","edit summary translations","hide profile smartcard","gemini overwrite summary","SMARTsummary stays in sync","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#foBotDeePane","kind":"help"},{"id":"help-botdee-smartview-troubleshoot","title":"SMARTview troubleshooting","body":"Empty card: the patron hid those fields or you are blocked. Save failed: sign in and retry — translations queue on the server, not this browser. Pending or failed translation shows the source language with a label. Edit is owner-only. Master Admin SMARTviews is still the mock catalog; live Places and Yelp stay off until counsel. Theme follows Site Chrome — there is no second SMARTview theme.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"},{"label":"SMARTviews (Master Admin)","href":"./master-admin.html#featuresBotDee-smartviews"}],"searchPhrases":["smartview not showing","smartview save failed","empty smartview","places yelp smartview","SMARTview troubleshooting","Open BOT DEE","SMARTviews (Master Admin)"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"master-admin.html#featuresBotDee","kind":"help"},{"id":"help-botdee-research-library","title":"BOT DEE Research Library","body":"Save places and cards you asked BOT DEE about. A Google Place ID is not a copy of Google’s photos or reviews. You can refresh or delete a saved item. Licensed caches stay off until the provider is approved.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["research library","saved places","google place id","refresh research","BOT DEE Research Library","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"master-admin.html#featuresBotDee","kind":"help"},{"id":"help-botdee-explain","title":"Explain My Recommendation","body":"Each recommendation can show evidence, the date it was checked, whether personalization was on, and if a placement is sponsored. You can ask BOT DEE not to personalize this search.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["explain my recommendation","why this result","sponsored","don't personalize","nonpersonalized","Explain My Recommendation","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"master-admin.html#featuresBotDee","kind":"help"},{"id":"help-botdee-privacy-assistant","title":"BOT DEE Privacy Assistant","body":"Change what other FLOQR users see in My Profile visibility — BOT DEE does not add a second public switch. If web research attached the wrong person, you can dispute it here without changing your profile. BOT DEE cannot promise that a third-party site will delete the original page.","steps":[],"links":[{"label":"Profile visibility","href":"./patron-portal.html?tab=profile"},{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["privacy assistant","profile visibility","wrong person","dispute match","not a second public toggle","BOT DEE Privacy Assistant","Profile visibility","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html","kind":"help"},{"id":"help-botdee-place-search","title":"Ask BOT DEE for FLOQR venues","body":"Ask in plain words — sushi restaurants in Washington DC, clubs in DC, or a named club. BOT DEE searches onboarded FLOQR venues only, not Google or Yelp. Matching clubs open a compact Place SMARTview (name, short blurb, ratings, public-page link) with a SMARTbackground — not a photo well. Patron photos and ShoutOut / VIP pitches stay off unless you asked for those. If nothing is onboarded yet, BOT DEE says so.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["sushi restaurants","sushi in washington dc","restaurants in dc","clubs in washington dc","dining search","find a club","japanese restaurant","bot dee venues","bot dee restaurants","Ask BOT DEE for FLOQR venues","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-page","title":"BOT DEE","body":"Chat with BOT DEE on the BOT DEE page in plain words: events and clubs, ShoutOut, Mingl, RydR, BartR, FloqCAST, your profile, staff schedules, or Club Admin tools. Press Enter to send a message; Shift+Enter starts a new line. Type help (like version) and BOT DEE explains itself and asks what you want help with. BOT DEE chats like a person (try How are you?) and only looks things up when you ask how to do something in FLOQR. If you are signed in, BOT DEE keeps this chat when you refresh or open another phone. After the pause timer, BOT DEE can recap where you left off — pause does not delete the chat, memories, or workflows. BOT DEE asks how it can help at the start of a conversation (and again if you come back after a pause). Mid-chat replies stay short. Answers use classification for your account. Signed-in BOT DEE uses the same public volunteered profile datapoints you can see (music, food, travel, hobbies, and the rest of Privacy datapoint sharing) — never email, phone, card numbers, or GPS. The + at the top right opens saved chats. Collapse and New chat only hide the canvas — BOT DEE still keeps that history and uses it on Send. Export or delete stays in My BOT DEE. Saved chats, memories, and approved facts live in My Profile → Feature & Orders → My BOT DEE. Tap a photo in the chat to pop it out into a separate window. Close with X or Close to see the chat again.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"},{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["bot dee","botdee","ask bot dee","bot dee page","chat with bot dee","help","bot dee help","what can you do","resume chat","refresh bot dee","other phone","general search","search everything","what can i search","enter to send","shift enter","how are you bot dee","floqai","floqai page","ask floqai","public profile","enlarge photo","tap photo","pop out photo","photo window","my bot dee","saved chats","plus button","new chat","collapse chats","rename chat","rename chats","privacy","session pause","keyboard","BOT DEE","Open BOT DEE","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-privacy-session","title":"BOT DEE privacy and session","body":"The five-minute pause ends this live BOT DEE session. It does not delete this signed-in chat, memories, or workflows. Opt-in copies in My Profile → Feature & Orders → My BOT DEE stay too. Guests stay ephemeral. Mingl chats are never copied here. Press Enter to send a message; Shift+Enter starts a new line. Type help or privacy on the BOT DEE page. The + control lists saved chats without deleting them. Collapse is visual only — Send still uses stored history. Name, tone, and recap live in My Profile → Feature & Orders → My BOT DEE — not as a button on the chat.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"},{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["privacy","session","pause","five minute pause","5 minute pause","keyboard","enter sends","shift enter","bot dee settings","call me","demeanor","socially cool","remind me where we left off","BOT DEE privacy and session","Open BOT DEE","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#foBotDeePane","kind":"help"},{"id":"help-vip-door-pass","title":"VIP reserV door pass","body":"After your deposit confirms, open My Profile → Guest List & reserV (or ?tab=passes) and tap Show pass for a one-time QR. Open full pass opens pass.html. Bring ID 21+. Door staff use VIP reserV Door to check you in.","steps":[],"links":[{"label":"My door passes","href":"./patron-portal.html?from=botdee&tab=passes"},{"label":"Open VIP reserV","href":"./vip.html?from=botdee"}],"searchPhrases":["vip pass","door pass","qr table","vip qr","show pass","table check in","passes","VIP reserV door pass","My door passes","Open VIP reserV"],"audiences":["patron","serviceMember","venueAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-vip-door-ops","title":"VIP reserV door check-in","body":"VIP Managers open VIP reserV Door for tonight’s list. Scan or paste a pass token, confirm ID 21+, then check in. Mark no-show only after grace. Opening a notify link never changes reservation status. Club Admin → Feature Mgmt → Passes issues guest/promoter QR passes, lists tonight’s passes, reveals QR, and check-in (ID 21+). VIP table Show pass on My Profile still uses the same pass.html viewer.","steps":[],"links":[{"label":"VIP reserV Door","href":"./vip-door.html?from=botdee"}],"searchPhrases":["vip door","door check in","vip manager","mark no show","table door","club admin passes","issue pass","qr door pass","passes tab","VIP reserV door check-in","VIP reserV Door"],"audiences":["serviceMember","venueAdmin","masterAdmin"],"helpPartition":"serviceMemberHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-become-dj","title":"Become a DJ","body":"Elect DJ as your service role and associate with clubs.","steps":[],"links":[{"label":"Request DJ access","href":"./role-request.html?from=botdee&type=dj"}],"searchPhrases":["become a dj","dj access","I want to be a dj","disc jockey","Become a DJ","Request DJ access"],"audiences":["serviceMember"],"helpPartition":"serviceMemberHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-become-promoter","title":"Become a Promoter","body":"Request Promoter access for guest lists and campaigns.","steps":[],"links":[{"label":"Request Promoter access","href":"./role-request.html?from=botdee&type=promoter"}],"searchPhrases":["become a promoter","promoter access","promotion company","Become a Promoter","Request Promoter access"],"audiences":["serviceMember"],"helpPartition":"serviceMemberHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-floqr-inbox-rules","title":"FloqR Inbox","body":"FloqR Inbox holds System Messages and internal support messages. The list loads first so your messages appear quickly. Tap the floating New Message button to compose — type a name or @username to find an allowed recipient (Club Admin, CSR, or approved staff). Patron-to-patron chat stays in Mingl after both patrons Mingl back. Opening a schedule invite does not confirm a shift — review and Approve selected on Work Calendar.","steps":[],"links":[{"label":"FloqR Inbox","href":"./patron-portal.html?tab=inbox&from=botdee"}],"searchPhrases":["floqr inbox","inbox","new message","send message","recipient","@username","compose message","inbox empty","floating new message","system message","club admin message","FloqR Inbox"],"audiences":["patron","serviceMember","venueAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#portalMessages","kind":"help"},{"id":"help-staff-marketing-consent","title":"Staff marketing consent","body":"When you join a venue or event team, you must tick the marketing consent box. It lets that venue or event organizer, and its admins and managers, use your FLOQR name, role, and published photos and videos on their websites, flyers, and social media (Instagram, Facebook, TikTok, YouTube and similar) without asking you again for each use. They may not publish your phone number or email. You can withdraw at any time in My Profile on the Services & Service Members tab. This stops new marketing; materials already printed or posted do not have to be recalled. Club Admins see each staff member's consent status in Employee / Worker Network and Featured service staff.","steps":[],"links":[{"label":"Services & Service Members","href":"./patron-portal.html?from=botdee&tab=service-members"},{"label":"Club Admin Employee/Workers","href":"./admin.html?from=botdee&tab=employees"}],"searchPhrases":["marketing consent","staff marketing consent","use my photos","club can use my photos","withdraw marketing consent","photo consent staff","instagram consent","flyer photo consent","Staff marketing consent","Services & Service Members","Club Admin Employee/Workers"],"audiences":["patron","serviceMember","venueAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html","kind":"help"},{"id":"help-template-tags","title":"Template tags","body":"Under each template patrons see Description, How it works (for the venue LED size), and Tag chips. Club Admin and Template Administrators/Managers edit Tag chips only on club-owned templates (your tags replace catalog tags). Shared FloqR templates stay read-only — FLOQR / Master Admin owns those tags. Description and How it works are always Master Admin–owned. Add words patrons might type, such as game night or birthday. Template Managers can add tags; Administrators and Club Admins can also remove them. Assign roles under Role Activity & Permission.","steps":[],"links":[{"label":"Club Admin","href":"./admin.html?from=botdee"}],"searchPhrases":["template tags","add tags","tag templates","administer templates","manage templates","template administrator","template manager","club owned template tags","shared floqr tags","Template tags","Club Admin"],"audiences":["venueAdmin","serviceMember"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"template-tags.html","kind":"help"},{"id":"help-scheduling-schedule-for","title":"Staff Scheduling","body":"Plan shifts and bookings, then notify each person by Inbox, Email, SMS or WhatsApp. Under Schedule for, choose whose calendar you are working on: My DJ schedule is your own calendar, Club lists the clubs you manage, and Promoting company lists the companies you promote for. Each calendar has its own $20/month subscription. Shifts sent to you appear under My assignments, where you confirm or decline them.","steps":[],"links":[{"label":"Open Staff Scheduling","href":"./scheduling.html?from=botdee"}],"searchPhrases":["staff scheduling","schedule for","owner id","whose schedule","scheduling page","create shift","dj schedule","club schedule","promoting company schedule","plan shifts","Staff Scheduling","Open Staff Scheduling"],"audiences":["venueAdmin","serviceMember"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"scheduling.html","kind":"help"}];
  const packs = {"ru":{"help-smartvisuals-notification":{"title":"SMARTnotification Mingl Room","body":"Компактное приглашение Mingl Room может появиться в Search, когда друг Mingl запланировал room BOT DEE, куда вас пригласили. Смотреть приглашение открывает Room SMARTview. Join Now ведёт в BOT DEE, не в Mingl chat. Не сейчас скрывает карточку в этой вкладке; Inbox сохраняет Review BOT DEE invite. Демо-запрос Cancun — только Studio. Картинка — иллюстрация, не фото. Rooms Join Now без расписания не появляются в Search."},"help-smartvisuals-room":{"title":"Room SMARTview и SMARTvisuals","body":"Room SMARTview показывает приглашение Mingl: расписание, RSVP или эфир и Join Now. Join Now в Search открывает BOT DEE (не Mingl chat) с room= и t=. SMARTstencils и SMARTbackgrounds следуют разрешённому названию — Cancun Trip даёт travel-иллюстрацию, не настоящее фото Cancun. Личный чат BOT DEE не выбирает картинку. Подписанный Ad снизу — образец из этих тегов. Пусто для личного чата или инъекции; это не живой рекламодатель."},"help-scheduling-schedule-for":{"title":"Расписание персонала","body":"Планируйте смены и букинги и уведомляйте каждого через Inbox, Email, SMS или WhatsApp. В разделе «Расписание для» выберите, с чьим календарём вы работаете: «Моё расписание DJ» — ваш собственный календарь, «Клуб» — клубы, которыми вы управляете, «Промо-компания» — компании, для которых вы промоутер. У каждого календаря своя подписка за 20 $ в месяц. Смены, назначенные вам, появляются в разделе «Мои назначения», где их можно подтвердить или отклонить."},"help-staff-marketing-consent":{"title":"Согласие персонала на маркетинг","body":"Присоединяясь к команде заведения или мероприятия, вы должны отметить согласие на маркетинг. Оно позволяет этому заведению или организатору, а также его администраторам и менеджерам, использовать ваше имя в FLOQR, роль и опубликованные фото и видео на своих сайтах, флаерах и в соцсетях (Instagram, Facebook, TikTok, YouTube и похожих) без повторного запроса для каждого использования. Публиковать ваш телефон или email они не могут. Отозвать согласие можно в любой момент в разделе «Мой профиль», вкладка «Сервисы и участники сервиса». Это прекращает новый маркетинг; уже напечатанные или опубликованные материалы изымать не обязательно. Club Admins видят статус согласия каждого сотрудника в «Сети сотрудников и персонала» и в «Избранном персонале»."},"help-botdee-privacy-session":{"title":"Конфиденциальность и сессия BOT DEE","body":"Пауза в пять минут завершает живую сессию BOT DEE. Она не удаляет этот чат для вошедшего пользователя, воспоминания или рабочие процессы. Копии в «Мой профиль» → «Функции и заказы» → My BOT DEE тоже остаются. Гости остаются эфемерными. Чаты Mingl сюда не копируются. Enter отправляет сообщение; Shift+Enter начинает новую строку. Имя и тон задаются в «Мой профиль» → My BOT DEE, не кнопкой в чате."},"help-botdee-place-search":{"title":"Спросить BOT DEE про площадки FLOQR","body":"Спросите простыми словами — суши-рестораны в Washington DC, клубы в DC или конкретный клуб. BOT DEE ищет только onboarded площадки FLOQR, не Google и не Yelp. Совпадения открывают компактный Place SMARTview (название, краткий текст, рейтинги, ссылка на публичную страницу) с SMARTbackground — не фото-лунку. Фото посетителей и питчи ShoutOut / VIP не показываются, если вы об этом не просили. Если площадки ещё нет — BOT DEE так и скажет."},"help-botdee-page":{"title":"BOT DEE","body":"Общайтесь с BOT DEE на странице BOT DEE простыми словами: события и клубы, ShoutOut, Mingl, RydR, BartR, FloqCAST, ваш профиль, расписания персонала или инструменты Club Admin. Нажмите Enter, чтобы отправить сообщение; Shift+Enter начинает новую строку. BOT DEE общается как человек (попробуйте How are you?) и ищет только когда вы спрашиваете, как сделать что-то в FLOQR. Если вы вошли в аккаунт, BOT DEE сохраняет этот чат при обновлении страницы или на другом телефоне, а после паузы может продолжить сохранённую историю. Пауза не удаляет чат. Ответы учитывают классификацию вашего аккаунта. После входа BOT DEE видит те же публичные добровольные данные профиля, что и вы (музыка, еда, путешествия, хобби и остальные пункты Privacy datapoint sharing) — никогда email, телефон, данные карты или GPS. Нажмите «Настройки» под полем чата для сохранённых чатов и воспоминаний. Нажмите фото в чате, чтобы открыть его в отдельном окне. Закройте крестиком или «Закрыть», чтобы снова увидеть чат. Знак + справа вверху открывает сохранённые чаты и не удаляет их."},"help-botdee-smartview-troubleshoot":{"title":"Устранение неполадок SMARTview","body":"Пустая карточка: поля скрыты или вы в блоке. Ошибка сохранения: войдите — переводы на сервере. Ожидание или сбой: исходный язык с меткой. Правит только владелец. SMARTviews Master Admin — mock; Places и Yelp выключены. Тема следует Site Chrome."},"help-botdee-smartcard-sync":{"title":"SMARTsummary остаётся синхронным","body":"Правите SMARTsummary на языке профиля. Сохранение сразу. Открытые карточки и SMARTview обновляются из той же записи. Переводы идут в фоне и не затирают более новую правку. Если скрыть профиль, заблокировать человека или удалить аккаунт, карточки исчезают. Gemini не перезаписывает ваш текст."},"help-botdee-smartcard-search":{"title":"Спросить BOT DEE, кто это","body":"«Who am I?» открывает ваш SMARTview. «Who is …», «What do you know of …» или «What about …» плюс имя, фамилия, display name, хендл Mingl или FloqR либо соцсеть (Instagram, TikTok, X). Совпадение только по этим полям личности — не по био, лайкам, напиткам или жанрам. Один результат — карточка People SMARTview в чате, не markdown и не сетка фото. Несколько — компактные SMARTcard. Приватные, заблокированные и неопубликованные не показываются — BOT DEE не подтверждает, что аккаунт существует."},"help-botdee-smartcard":{"title":"SMARTcard людей","body":"Если подходит несколько публичных профилей FLOQR, BOT DEE показывает компактные карточки в чате: сначала фото на всю ширину, затем имя и хендл, затем сжатый SMARTsummary без пустой рамки. Нажмите карточку, чтобы открыть полный SMARTview — та же укладка. Это тот же публичный профиль и SMARTsummary. Открытие не вызывает Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Введите Ver, Vers или Version — регистр не важен. BOT DEE показывает карточку версии. Более длинный вопрос вроде «какая у тебя версия?» тоже показывает эту карточку."},"help-botdee-version-smartview-status":{"title":"Статус Version SMARTview — живая проверка","body":"Состояние службы проверяется на этом запросе Version: Functions и пакет доступны и Gemini настроен → Работает; Functions и пакет есть, Gemini не настроен → Ограничено; Functions нет в этом запросе → Недоступно. Никогда не статическая метка Не проверено. Модель ИИ показывает настроенный id Gemini этого развёртывания, даже если этот ход не генерировал. Штампы фронтенда и бэкенда могут различаться; оба подписаны. Master Admin видит доп. диагностику в технических сведениях — гости нет."},"help-botdee-version-smartview-tabs":{"title":"Вкладки Version SMARTview","body":"Обзор описывает BOT DEE и открывает технические сведения, не покидая чат. Что нового показывает только проверенные изменения BOT DEE и Gemini — не Master Admin, не инструменты бета-тестеров и не другие заметки продуктов FLOQR. Справка повторяет команду Ver / Vers / Version. Смена вкладки или раскрытие сохраняет неотправленный черновик и прокрутку. Карточка берёт ваш Site Chrome — второй темы нет."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"В чате BOT DEE скажите Open Room SMARTview, Start a group chat или простыми словами запланируйте поездку в Cancun. Дальше: Войти сейчас или Задать расписание. Войти сейчас открывает сессию друзей Mingl сразу и не ставит карточку на Search. Задать расписание — старт room BOT DEE, не Shared Itinerary, и включает Search SMARTnotification для вас и приглашённых друзей Mingl. Приглашайте только друзей Mingl — хост плюс 7 гостей. Гости тоже могут приглашать. Вход — не платёж и не общий счёт. BOT DEE никогда не берёт номера карт. Личные сообщения остаются личными. Site Chrome следует Appearance. Живая room открыта, пока хост не нажмёт End Room, около четырёх часов после открытия, или если все отсутствуют около 15 минут. Пауза личного чата BOT DEE отдельно."},"help-botdee-room-smartview-invite":{"title":"Пригласить друзей Mingl","body":"После Confirm кнопка Invite показывает только друзей Mingl. Каждое приглашение привязано к другу и приходит в Inbox как Review BOT DEE invite. Это не публичная ссылка. Лимит: хост плюс 7. Гости могут приглашать, пока хост не отключит это. Вход не списывает деньги. Если фишка — это вы или человек уже в сессии, она помечена «Это вы» или «Уже в этой сессии» и не шлёт второе приглашение."},"help-botdee-room-smartview-join":{"title":"Войти в сессию BOT DEE","body":"Откройте приглашение Inbox, войдя как друг Mingl, которому оно отправлено. Чужой аккаунт, срок и отзыв отказывают. Вход в room — не вход в общий счёт и не согласие на оплату. BOT DEE никогда не берёт номера карт."},"help-botdee-room-smartview-end":{"title":"Завершить Room SMARTview","body":"Только хост может завершить room. Завершение никого не списывает и не стирает чужие личные чаты. Неоплаченный общий счёт нужно оплатить или аннулировать сначала. Живая room открыта до End Room, около четырёх часов после открытия, или если все отсутствуют около 15 минут. Пауза личного чата BOT DEE — не выход из room. Гость, который уходит, не завершает room, пока хост на месте."},"help-botdee-room-smartview-tab":{"title":"Общий счёт Room SMARTview","body":"Сначала opt-in. Затем добавьте строку. Закройте одним плательщиком или раздельно. Списывают только подтвердившие uid через FloqR Stripe. Вход в room — не вход в счёт. BOT DEE никогда не берёт номера карт. Club POS позже."},"help-botdee-room-smartview-who-pays":{"title":"Кто платит","body":"Спросите Who’s paying в Room SMARTview, чтобы увидеть opt-in. Никого не списывают потому, что кто-то сказал купить. Последние четыре карты остаются на квитанции плательщика."},"help-botdee-room-smartview-kick":{"title":"Удалить из Room SMARTview","body":"Только хост может удалить гостя. Удалённый друг не читает дальнейшие сообщения room. Ответ модели никого не исключает."},"help-botdee-room-smartview-share":{"title":"Поделиться в Room SMARTview","body":"Share this conversation никогда не копирует ваш личный тред BOT DEE. BOT DEE показывает предпросмотр выбранных фактов из этого сообщения, помеченных как предварительные. Можно править или убрать факты. Профили и SMARTsummary остаются вне room."},"help-botdee-room-smartview-schedule":{"title":"Войти сейчас или задать расписание","body":"После настройки Room SMARTview выберите Войти сейчас или Задать расписание. Войти сейчас открывает сессию BOT DEE сразу и не ставит карточку на Search. Задать расписание — старт room BOT DEE, не Shared Itinerary. Будущее время включает Search SMARTnotification только для вас и приглашённых друзей Mingl. Гости RSVP, пока room не в эфире; затем Join Now открывает BOT DEE (не Mingl chat)."},"help-botdee-room-collab":{"title":"Общий headless-заказ в Room SMARTview","body":"В Room SMARTview выбор хоста по VIP reserV или ShoutOut виден всем в сессии. Участники голосуют Да или Нет. Hold it и оплата остаются у хоста — вход и голос не платёж. BOT DEE никогда не берёт номера карт. Stripe открывается во всплывающем окне."},"help-botdee-room-elect-host":{"title":"Выбор хоста Room SMARTview","body":"Любой в сессии может быть хостом. Номинируйте себя или другого участника. Кандидат становится хостом при 60% текущих участников (округление вверх). Если хост уходит, остальные выбирают нового — room остаётся открытым. Kick и End остаются у избранного хоста."},"help-botdee-smartview-review":{"title":"Проверить и исправить SMARTsummary","body":"Gemini составляет черновик только из публичных полей FLOQR — не при каждом просмотре. Неверный факт: скройте поле или правьте описание. Ваш текст не перезаписывается. Конфликт профиля просит проверку. Сообщите о неверной карточке в оверлее."},"help-botdee-smartview-chrome":{"title":"SMARTview и Site Chrome","body":"People SMARTview берёт Site Chrome FLOQR зрителя (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Второго темы нет. Смена chrome обновляет карточку, черновик чата сохраняется."},"help-botdee-smartview-categories":{"title":"Категории SMARTview","body":"Четыре вкладки: Социальное, Знакомства, Еда, Будущие поездки. Социальное открывается на Музыке, затем Nightlife, Спорт, События. Теги только из того, чем вы поделились — без повторных заголовков и выдуманных поездок или оценок."},"help-botdee-smartview-media":{"title":"Фото и видео SMARTview","body":"Компактная карточка использует то же главное фото, что и публичная страница FLOQR — первый элемент Profile Media (8 фото + 2 видео). Нажмите, чтобы открыть эти публичные фото и видео. Смахните или стрелки, затем X (или Escape) — тот же чат и черновик."},"help-botdee-smartview-privacy":{"title":"Конфиденциальность SMARTview","body":"SMARTview показывает только уже публичные в FLOQR поля. Это не веб-поиск. Знакомства только с явным согласием. Скройте поле в профиле — оно уйдёт. Заблокированные не видят карточку. Сообщите о неверном описании в оверлее."},"help-botdee-smartview-translation":{"title":"Перевод SMARTview","body":"SMARTsummary хранится на языке профиля — это источник, даже если это не английский. После сохранения FLOQR ставит перевод на каждый другой язык, включая английский. Англоязычный зритель видит английский SMARTsummary, когда работа завершена. Пока перевод ждёт или сбой, зрители видят исходный язык с пометкой — не устаревший перевод как актуальный."},"help-botdee-smartview-edit":{"title":"Изменить SMARTsummary","body":"Только вы правите SMARTsummary на языке профиля. Сохранение сразу. Переводы идут в фоне. Gemini не перезаписывает ваш текст. Если публичный профиль изменился, FLOQR просит проверить, а не подменяет."},"help-botdee-privacy-assistant":{"title":"Помощник конфиденциальности BOT DEE","body":"Меняйте видимость в «Моём профиле» — BOT DEE не добавляет второй публичный переключатель. Неверную веб-привязку можно оспорить, не меняя профиль. BOT DEE не обещает удаление на стороннем сайте."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Каждая рекомендация может показать доказательства, дату проверки, персонализацию и спонсорство. Можно попросить BOT DEE не персонализировать этот поиск."},"help-botdee-research-library":{"title":"Библиотека исследований BOT DEE","body":"Сохраняйте места и карточки, о которых вы спрашивали BOT DEE. Place ID Google — не копия фото или отзывов. Можно обновить или удалить. Лицензионные кэши выключены, пока провайдер не одобрен."},"help-botdee-smartview":{"title":"Мой SMARTview","body":"«Мой SMARTview» показывает вашу карточку человека из публичных полей FLOQR, с теми же Profile Media, что и публичная страница, — не макеты клубов или ресторанов. «Изменить мой SMART Summary» меняет текст на языке профиля. Макеты клубов и ресторанов живут в Master Admin → Features → BOT DEE → SMARTviews. Нет живых Places или Yelp."},"help-botdee-memory":{"title":"Сохранённые чаты BOT DEE","body":"Откройте Функции и заказы → Мой BOT DEE, чтобы сохранять чаты после паузы, экспортировать или удалять историю. Пятиминутная пауза завершает живую сессию. При согласии BOT DEE сохраняет чат. Гости не сохраняются. Mingl остаётся в Mingl."},"help-botdee-knows-of-me":{"title":"Что BOT DEE знает обо мне","body":"Факты с вашего согласия — в разделе Функции и заказы → Мой BOT DEE. Список пуст, если память выключена или фактов нет. Экспорт или удаление здесь. BOT DEE не сохраняет IP. Mingl не копируется."},"help-search-settings-appearance":{"title":"Settings на Search","body":"На экране Home Search нажмите Settings, чтобы открыть Profile & Settings на вкладке Appearance — там Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Плитка Settings использует тот же набор chrome-иконок, что и другие метки Search."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"FloqR Inbox хранит System Messages и внутренние сообщения поддержки. Список загружается первым, чтобы письма появлялись быстро. Нажмите плавающую кнопку New Message, чтобы написать — введите имя или @username, чтобы найти разрешённого получателя (Club Admin, CSR или одобренный персонал). Переписка patron–patron остаётся в Mingl после взаимного Mingl. Открытие приглашения на смену не подтверждает её — просмотрите и нажмите Approve selected в Work Calendar."},"help-become-dj":{"title":"Стать DJ","body":"Выберите роль DJ и привяжитесь к клубам."},"help-become-promoter":{"title":"Стать Promoter","body":"Запросите доступ Promoter для гостевых списков и кампаний."},"help-template-tags":{"title":"Теги шаблонов","body":"Добавьте слова, которые гости могут ввести при поиске шаблона на вашей площадке, например вечер матча или день рождения. Менеджеры шаблонов могут добавлять теги. Администраторы шаблонов и Club Admin могут также удалять теги. Club Admin назначает эти роли в разделе Role Activity & Permission."},"help-vip-door-pass":{"title":"Пропуск VIP reserV","body":"После подтверждения депозита откройте Мой профиль → Бронирования и нажмите Show pass для одноразового QR. Возьмите ID 21+. Персонал двери использует VIP reserV Door."},"help-vip-door-ops":{"title":"Check-in у двери VIP reserV","body":"VIP Manager открывает VIP reserV Door на сегодня. Сканируйте или вставьте токен, подтвердите ID 21+, затем check-in. No-show только после grace. Ссылка notify не меняет статус."}},"nl":{"help-smartvisuals-notification":{"title":"Mingl Room SMARTnotification","body":"Een compacte Mingl Room-uitnodiging kan op Search verschijnen als een Mingl-vriend een BOT DEE-room plande waar jij voor bent uitgenodigd. Uitnodiging bekijken opent Room SMARTview. Join Now gaat naar BOT DEE, niet Mingl-chat. Niet nu verbergt de kaart in dit tabblad; Inbox houdt Review BOT DEE invite. De Cancun-demovraag is alleen Studio. Kunst is illustratie, geen foto. Join Now-rooms zonder plan verschijnen niet op Search."},"help-smartvisuals-room":{"title":"Room SMARTview met SMARTvisuals","body":"Room SMARTview toont de Mingl-uitnodiging: plan, RSVP of live-status, en Join Now. Join Now op Search opent BOT DEE (niet Mingl-chat) met room= en t=. SMARTstencils en SMARTbackgrounds volgen de geautoriseerde roomtitel — Cancun Trip gebruikt reisillustratie, geen echte Cancun-foto. Privé-BOT DEE-chat kiest nooit de kunst. Een gelabelde Ad eronder is een sample van die tags. Leeg bij privéchat of injectie; geen live adverteerder."},"help-scheduling-schedule-for":{"title":"Personeelsplanning","body":"Plan diensten en boekingen en laat iedereen het weten via Inbox, Email, SMS of WhatsApp. Kies onder 'Planning voor' aan welke agenda je werkt: 'Mijn DJ-planning' is je eigen agenda, 'Club' toont de clubs die je beheert en 'Promotiebedrijf' de bedrijven waarvoor je promoot. Elke agenda heeft een eigen abonnement van $ 20 per maand. Diensten die aan jou zijn toegewezen verschijnen onder 'Mijn toewijzingen', waar je ze bevestigt of weigert."},"help-staff-marketing-consent":{"title":"Marketingtoestemming voor personeel","body":"Wanneer je bij het team van een locatie of evenement aansluit, moet je het vakje voor marketingtoestemming aanvinken. Daarmee mogen die locatie of organisator en hun beheerders en managers je FLOQR-naam, je rol en je gepubliceerde foto’s en video’s gebruiken op hun websites, flyers en sociale media (Instagram, Facebook, TikTok, YouTube en vergelijkbare) zonder je voor elk gebruik opnieuw te vragen. Ze mogen je telefoonnummer of e-mailadres niet publiceren. Je kunt op elk moment intrekken in Mijn profiel, tabblad Services en servicemedewerkers. Dat stopt nieuwe marketing; materiaal dat al gedrukt of geplaatst is, hoeft niet te worden teruggehaald. Club Admins zien de toestemmingsstatus van elke medewerker in het Netwerk van medewerkers en personeel en bij Uitgelicht personeel."},"help-botdee-privacy-session":{"title":"BOT DEE privacy en sessie","body":"De pauze van vijf minuten beëindigt de live BOT DEE-sessie. Ze verwijdert deze ingelogde chat, herinneringen of workflows niet. Optionele kopieën in Mijn profiel → Functies en bestellingen → My BOT DEE blijven ook. Gasten blijven tijdelijk. Mingl-chats worden hier nooit gekopieerd. Enter verstuurt; Shift+Enter begint een nieuwe regel. Naam en toon staan in Mijn profiel → My BOT DEE, niet als knop in de chat."},"help-botdee-place-search":{"title":"Vraag BOT DEE naar FLOQR-venues","body":"Vraag in gewone taal — sushi restaurants in Washington DC, clubs in DC of een clubnaam. BOT DEE zoekt alleen onboarded FLOQR-venues, niet Google of Yelp. Treffers openen een compacte Place SMARTview (naam, korte blurb, ratings, publiekspagina) met een SMARTbackground — geen fotobak. Patronfoto’s en ShoutOut- / VIP-pitches blijven weg tenzij u daarnaar vroeg. Als er nog niets onboarded is, zegt BOT DEE dat."},"help-botdee-page":{"title":"BOT DEE","body":"Chat met BOT DEE op de BOT DEE-pagina in gewone taal: evenementen en clubs, ShoutOut, Mingl, RydR, BartR, FloqCAST, je profiel, personeelsroosters of Club Admin-tools. Druk op Enter om te versturen; Shift+Enter start een nieuwe regel. BOT DEE praat als een persoon (probeer How are you?) en zoekt alleen als je vraagt hoe je iets in FLOQR doet. Als je bent ingelogd, bewaart BOT DEE deze chat als je vernieuwt of een andere telefoon opent, en na de pauze verdergaan met de opgeslagen geschiedenis. De pauze verwijdert de chat niet. Antwoorden gebruiken de classificatie van jouw account. Ingelogd ziet BOT DEE dezelfde openbaar gedeelde profieldatapoints als jij (muziek, eten, reizen, hobby’s en de rest van Privacy datapoint sharing) — nooit e-mail, telefoon, kaartgegevens of GPS. Tik op Instellingen onder het chatvak voor opgeslagen chats en herinneringen. Tik in de chat op een foto om die in een apart venster te openen. Sluit met X of Sluiten om de chat weer te zien. De + rechtsboven opent opgeslagen chats en verwijdert ze niet."},"help-botdee-smartview-troubleshoot":{"title":"SMARTview-problemen","body":"Lege kaart: velden verborgen of geblokkeerd. Opslaan mislukt: meld u aan — vertalingen staan op de server. Wachtend of mislukt: brontaal met label. Alleen de eigenaar bewerkt. Master Admin SMARTviews blijft de mock-catalogus; Places en Yelp blijven uit. Thema volgt Site Chrome."},"help-botdee-smartcard-sync":{"title":"SMARTsummary blijft synchroon","body":"Bewerk uw SMARTsummary in de standaard profieltaal. Opslaan is direct. Open kaarten en SMARTview werken bij vanaf hetzelfde record. Vertalingen lopen op de achtergrond en overschrijven geen nieuwere bewerking. Als u het profiel verbergt, iemand blokkeert of het account verwijdert, verdwijnen die kaarten. Gemini overschrijft uw tekst niet."},"help-botdee-smartcard-search":{"title":"BOT DEE vragen wie iemand is","body":"“Who am I?” opent uw SMARTview. “Who is …”, “What do you know of …” of “What about …” plus voornaam, achternaam, weergavenaam, Mingl- of FloqR-handle, of een social handle (Instagram, TikTok, X). Alleen die identiteitsvelden tellen — geen bio’s, likes, drankjes of genres. Eén match opent een People SMARTview-kaart in de chat — geen markdownlijst of fotogrid. Meer matches tonen compacte SMARTcards. Privé, geblokkeerd of niet-gepubliceerd wordt niet getoond — BOT DEE bevestigt niet of dat account bestaat."},"help-botdee-smartcard":{"title":"Mensen-SMARTcards","body":"Als meer dan één openbaar FLOQR-profiel past, toont BOT DEE compacte mensen-SMARTcards in de chat: eerst een foto over de volle breedte, dan naam en handle, dan een compacte SMARTsummary zonder opgevulde box. Tik om de volledige SMARTview te openen — dezelfde stapeling. Kaarten gebruiken hetzelfde openbare profiel en dezelfde SMARTsummary. Openen roept Gemini niet aan."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Typ Ver, Vers of Version — hoofdletters maken niet uit. BOT DEE toont de versiekaart. Een langere vraag zoals “wat is je versie?” toont ook die kaart."},"help-botdee-version-smartview-status":{"title":"Version SMARTview-status is een live peiling","body":"Servicestatus wordt bij dit Version-verzoek gepeild: Functions en package bereikbaar met Gemini geconfigureerd → Operationeel; Functions en package oké maar Gemini niet geconfigureerd → Verminderd; Functions niet in dit verzoek → Niet beschikbaar. Nooit een statisch Niet gecontroleerd. Het AI-model toont het geconfigureerde Gemini-model-id van deze deployment ook als deze beurt niet genereerde. Frontend- en backendstempels kunnen verschillen; beide zijn gelabeld. Master Admin kan extra diagnostiek zien onder Technische details — patrons niet."},"help-botdee-version-smartview-tabs":{"title":"Version SMARTview-tabbladen","body":"Overzicht beschrijft BOT DEE en opent Technische details zonder de chat te verlaten. Nieuw toont alleen geverifieerde BOT DEE- en Gemini-wijzigingen — geen Master Admin, bèta-testertools of andere FLOQR-productnotities. Help herhaalt het commando Ver / Vers / Version. Tab wisselen of uitklappen bewaart je onverzonden concept en scroll. De kaart gebruikt jouw Site Chrome — er is geen tweede thema."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"Zeg in de BOT DEE-chat Open Room SMARTview, Start a group chat, of plan een Cancun-reis in gewone woorden. Daarna: Nu deelnemen of Plan instellen. Nu deelnemen opent nu een Mingl-vrienden-sessie en zet geen kaart op Search. Plan instellen is wanneer de BOT DEE-room start — niet Shared Itinerary — en zet Search SMARTnotification aan voor jou en uitgenodigde Mingl-vrienden. Nodig alleen Mingl-vrienden uit — host plus 7 gasten. Gasten kunnen ook uitnodigen. Deelnemen is geen betaling en opent geen gedeelde rekening. BOT DEE neemt nooit kaartnummers. Privé-BOT DEE-berichten blijven privé. Site Chrome volgt Appearance. Een live room blijft open tot End Room, tot ongeveer vier uur na opening, of tot iedereen zo’n 15 minuten weg is. De pauze van privé-BOT DEE-chat is apart."},"help-botdee-room-smartview-invite":{"title":"Mingl-vrienden uitnodigen","body":"Na Confirm toont Invite alleen je Mingl-vrienden. Elke uitnodiging is gebonden aan die vriend en landt in Inbox als Review BOT DEE invite. Geen openbare join-link. Cap is host plus 7. Gasten kunnen meer Mingl-vrienden uitnodigen tot de host dat uitzet. Deelnemen is geen betaling. Als een chip jij bent of iemand die al in de sessie zit, staat That’s you of Already in this session en wordt er geen tweede uitnodiging gestuurd."},"help-botdee-room-smartview-join":{"title":"Deelnemen aan een BOT DEE-sessie","body":"Open de Inbox-uitnodiging terwijl je bent aangemeld als de Mingl-vriend aan wie die is gestuurd. Verkeerd account, verlopen of ingetrokken weigert. Deelnemen aan de room is niet deelnemen aan een tab en keurt geen betaling goed. BOT DEE neemt nooit kaartnummers."},"help-botdee-room-smartview-end":{"title":"Room SMARTview beëindigen","body":"Alleen de host kan een room beëindigen. Beëindigen belast niemand en wist geen privéchats van anderen. Een onbetaalde gedeelde rekening moet eerst betaald of geannuleerd. Een live room blijft open tot End Room, tot ongeveer vier uur na opening, of tot iedereen zo’n 15 minuten weg is. De pauze van privé-BOT DEE-chat is geen room-logout. Een gast die weggaat beëindigt de room niet zolang de host er is."},"help-botdee-room-smartview-tab":{"title":"Gedeelde tab Room SMARTview","body":"Eerst opt-in. Voeg dan een regel toe. Sluit als één betaler of splits. Alleen bevestigende uids worden belast via FloqR Stripe. Deelnemen aan de room is niet deelnemen aan een tab. BOT DEE neemt nooit kaartnummers. Club POS komt later."},"help-botdee-room-smartview-who-pays":{"title":"Wie betaalt","body":"Vraag Who’s paying in een Room SMARTview om opt-in te zien. Niemand wordt belast omdat iemand buy zei. De laatste vier van de kaart blijven op het ontvangstbewijs van de betaler."},"help-botdee-room-smartview-kick":{"title":"Iemand uit Room SMARTview verwijderen","body":"Alleen de host kan een gast verwijderen. Een verwijderde vriend leest geen verdere roomberichten. Een modelantwoord kan niemand kicken."},"help-botdee-room-smartview-share":{"title":"Delen in Room SMARTview","body":"Share this conversation kopieert nooit je privé BOT DEE-thread. BOT DEE toont een voorbeeld van geselecteerde deelbare feiten uit dit bericht, gemarkeerd als voorlopig. Je kunt feiten bewerken of weglaten. Profielen en SMARTsummary blijven buiten de room."},"help-botdee-room-smartview-schedule":{"title":"Nu deelnemen of plan instellen","body":"Na Room SMARTview-setup kies je Nu deelnemen of Plan instellen. Nu deelnemen opent de BOT DEE-sessie nu en zet geen kaart op Search. Plan instellen is wanneer de BOT DEE-room start — niet Shared Itinerary. Een toekomstig tijdstip zet Search SMARTnotification alleen aan voor jou en uitgenodigde Mingl-vrienden. Gasten RSVP tot de room live is; daarna opent Join Now BOT DEE (niet Mingl-chat)."},"help-botdee-room-collab":{"title":"Deel een headless boeking in Room SMARTview","body":"In een Room SMARTview zien alle leden de VIP reserV- of ShoutOut-keuzes van de host. Leden stemmen Ja of Nee. Hold it en betalen blijven bij de host — meedoen en stemmen is geen betaling. BOT DEE neemt nooit kaartnummers. Stripe opent in een pop-out."},"help-botdee-room-elect-host":{"title":"Kies een Room SMARTview-host","body":"Iedereen in de sessie kan host zijn. Nomineer jezelf of een ander lid. Een kandidaat wordt host bij 60% van de huidige leden (naar boven afgerond). Als de host vertrekt, kiezen de overgebleven leden een nieuwe — de room blijft open. Kick en End blijven bij de gekozen host."},"help-botdee-smartview-review":{"title":"SMARTsummary controleren en corrigeren","body":"Gemini stelt alleen op uit openbare FLOQR-velden — niet bij elke weergave. Verkeerd feit: veld verbergen of samenvatting zelf bewerken. Uw tekst wordt niet overschreven. Profielconflicten vragen om controle. Meld een foute kaart in de overlay."},"help-botdee-smartview-chrome":{"title":"SMARTview en Site Chrome","body":"People SMARTview gebruikt de FLOQR Site Chrome van de kijker (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Geen tweede thema. Chrome wisselen werkt de kaart bij zonder het chatconcept te verliezen."},"help-botdee-smartview-categories":{"title":"SMARTview-categorieën","body":"Vier tabbladen: Sociaal, Daten, Dineren, Toekomstige reizen. Sociaal opent op Muziek, daarna Nightlife, Sport, Events. Tags zijn alleen wat u deelde — geen dubbele koppen, geen verzonnen reizen of scores. Toekomstige reizen alleen openbaar gemaakte bestemmingen."},"help-botdee-smartview-media":{"title":"SMARTview-foto’s en video’s","body":"De compacte kaart gebruikt dezelfde hero als uw openbare FLOQR-profiel — het eerste Profile Media-item (8 foto’s + 2 video’s). Tik voor Foto’s en Video’s uit die openbare slots. Veeg of pijlen, dan X (of Escape) terug naar dezelfde chatscroll en concept."},"help-botdee-smartview-privacy":{"title":"SMARTview-privacy","body":"SMARTview toont alleen velden die u al openbaar maakte in FLOQR. Geen webzoeken. Daten alleen met opt-in. Verberg een veld in Mijn profiel en het verdwijnt. Geblokkeerden zien de kaart niet. Meld een onjuiste samenvatting in de overlay."},"help-botdee-smartview-translation":{"title":"SMARTview-vertaling","body":"Uw SMARTsummary wordt opgeslagen in de standaard profieltaal — dat is de bron, ook als het geen Engels is. Na opslaan zet FLOQR een vertaling klaar voor elke andere taal, inclusief Engels. Een Engelstalige kijker ziet de Engelse SMARTsummary zodra die job klaar is. Bij wachten of fout ziet de kijker de brontaal met label — nooit een verouderde vertaling als actueel."},"help-botdee-smartview-edit":{"title":"Uw SMARTsummary bewerken","body":"Alleen u bewerkt uw SMARTsummary in de standaard profieltaal. Opslaan is direct. Vertalingen lopen op de achtergrond. Gemini overschrijft uw tekst niet. Als het openbare profiel wijzigt, vraagt FLOQR u te controleren in plaats van te vervangen."},"help-botdee-privacy-assistant":{"title":"BOT DEE Privacy Assistant","body":"Wijzig in Mijn profiel wat andere FLOQR-gebruikers zien — BOT DEE voegt geen tweede openbare schakelaar toe. Verkeerde webkoppeling kunt u betwisten zonder uw profiel te wijzigen. BOT DEE belooft geen verwijdering op sites van derden."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Elke aanbeveling kan bewijs, controledatum, personalisatie en sponsoring tonen. U kunt BOT DEE vragen deze zoekopdracht niet te personaliseren."},"help-botdee-research-library":{"title":"BOT DEE Research Library","body":"Bewaar plaatsen en kaarten die u BOT DEE vroeg. Een Google Place-ID is geen kopie van foto’s of reviews. U kunt vernieuwen of wissen. Gelicentieerde caches blijven uit tot de provider is goedgekeurd."},"help-botdee-smartview":{"title":"Mijn SMARTview bekijken","body":"Mijn SMARTview toont uw Person-kaart uit openbare FLOQR-velden, met dezelfde Profile Media als uw openbare pagina — geen club- of restaurantmocks. Mijn SMART Summary bewerken wijzigt de samenvatting in uw profieltaal. Gelabelde mock-kaarten staan in Master Admin → Features → BOT DEE → SMARTviews. Geen live Places of Yelp."},"help-botdee-memory":{"title":"Opgeslagen BOT DEE-chats","body":"Open Functies & bestellingen → Mijn BOT DEE om chats na de pauze op te slaan, te exporteren of geschiedenis te wissen. De pauze van vijf minuten beëindigt de live sessie. Met opt-in bewaart BOT DEE de chat. Gasten worden niet bewaard. Mingl blijft Mingl."},"help-botdee-knows-of-me":{"title":"Wat BOT DEE van mij weet","body":"Feiten met uw toestemming staan onder Functies & bestellingen → Mijn BOT DEE. De lijst is leeg als geheugen uit staat of er niets is opgeslagen. Exporteer of wis hier. BOT DEE slaat geen IP-adres op. Mingl wordt niet gekopieerd."},"help-search-settings-appearance":{"title":"Settings op Search","body":"Tik op Search op Settings om Profile & Settings te openen op het tabblad Appearance — daar staat Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). De Settings-tegel gebruikt hetzelfde chrome-iconenpakket als de andere Search-merken."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"FloqR Inbox bevat System Messages en interne supportberichten. De lijst laadt eerst zodat berichten snel verschijnen. Tik op de zwevende knop New Message om te schrijven — typ een naam of @username om een toegestane ontvanger te vinden (Club Admin, CSR of goedgekeurd personeel). Patron-naar-patron chat blijft in Mingl na wederzijds Mingl. Een shift-uitnodiging openen bevestigt niet — bekijk en tik Approve selected op Work Calendar."},"help-become-dj":{"title":"Word DJ","body":"Kies DJ als service-rol en koppel je aan clubs."},"help-become-promoter":{"title":"Word Promoter","body":"Vraag Promoter-toegang aan voor gastenlijsten en campagnes."},"help-template-tags":{"title":"Sjabloontags","body":"Voeg woorden toe die gasten kunnen typen als ze een sjabloon zoeken bij je locatie, zoals wedstrijdavond of verjaardag. Sjabloonmanagers kunnen tags toevoegen. Sjabloonbeheerders en Club Admins kunnen tags ook verwijderen. Club Admin wijst deze rollen toe onder Role Activity & Permission."},"help-vip-door-pass":{"title":"VIP reserV deurpass","body":"Na bevestigde borg: Mijn profiel → Reserveringen → Toon pass voor een eenmalige QR. Neem ID 21+ mee. Deurstaf gebruikt VIP reserV Door."},"help-vip-door-ops":{"title":"VIP reserV deur check-in","body":"VIP Managers openen VIP reserV Door voor vanavond. Scan of plak de token, bevestig ID 21+, check in. No-show alleen na grace. Een notify-link wijzigt de status niet."}},"fr":{"help-smartvisuals-notification":{"title":"SMARTnotification Mingl Room","body":"Une invitation Mingl Room compacte peut apparaître sur Search quand un ami Mingl a planifié une room BOT DEE à laquelle vous êtes invité. Voir l’invitation ouvre Room SMARTview. Join Now va vers BOT DEE, pas Mingl chat. Pas maintenant masque la carte dans cet onglet ; Inbox garde Review BOT DEE invite. La requête démo Cancun est réservée au Studio. L’art est une illustration, pas une photo. Les rooms Join Now sans horaire n’apparaissent pas sur Search."},"help-smartvisuals-room":{"title":"Room SMARTview et SMARTvisuals","body":"Room SMARTview montre l’invitation Mingl : horaire, RSVP ou statut en ligne, et Join Now. Join Now sur Search ouvre BOT DEE (pas Mingl chat) avec room= et t=. SMARTstencils et SMARTbackgrounds suivent le titre autorisé — Cancun Trip utilise une illustration voyage, pas une vraie photo de Cancun. Le chat BOT DEE privé ne choisit jamais l’art. Un Ad étiqueté en dessous est un échantillon de ces tags. Vide pour chat privé ou injection ; ce n’est pas un annonceur en direct."},"help-scheduling-schedule-for":{"title":"Planification du personnel","body":"Planifiez des shifts et des bookings, puis prévenez chaque personne par Inbox, Email, SMS ou WhatsApp. Sous « Planning pour », choisissez le calendrier sur lequel vous travaillez : « Mon planning DJ » est votre propre calendrier, « Club » liste les clubs que vous gérez et « Société de promotion » les sociétés pour lesquelles vous faites la promotion. Chaque calendrier a son propre abonnement à 20 $/mois. Les shifts qui vous sont attribués apparaissent sous « Mes affectations », où vous les confirmez ou les refusez."},"help-staff-marketing-consent":{"title":"Consentement marketing du personnel","body":"Lorsque vous rejoignez l’équipe d’un lieu ou d’un événement, vous devez cocher la case de consentement marketing. Elle permet à ce lieu ou à cet organisateur, ainsi qu’à ses administrateurs et responsables, d’utiliser votre nom FLOQR, votre rôle et vos photos et vidéos publiées sur leurs sites web, flyers et réseaux sociaux (Instagram, Facebook, TikTok, YouTube et similaires) sans vous redemander votre accord à chaque utilisation. Ils ne peuvent pas publier votre numéro de téléphone ni votre e-mail. Vous pouvez retirer ce consentement à tout moment dans Mon profil, onglet Services et membres de service. Cela met fin aux nouvelles utilisations ; les supports déjà imprimés ou publiés n’ont pas à être retirés. Les Club Admins voient le statut de consentement de chaque membre du personnel dans Réseau des employés et du personnel et dans Personnel mis en avant."},"help-botdee-privacy-session":{"title":"Confidentialité et session BOT DEE","body":"La pause de cinq minutes termine la session BOT DEE en direct. Elle ne supprime pas ce chat connecté, les souvenirs ni les workflows. Les copies dans Mon profil → Fonctions et commandes → My BOT DEE restent aussi. Les invités restent éphémères. Les discussions Mingl ne sont jamais copiées ici. Entrée envoie ; Maj+Entrée commence une nouvelle ligne. Le nom et le ton se règlent dans Mon profil → My BOT DEE, pas par un bouton dans le chat."},"help-botdee-place-search":{"title":"Demander à BOT DEE des lieux FLOQR","body":"Demandez en mots simples — restaurants de sushi à Washington DC, clubs à DC, ou un club nommé. BOT DEE ne cherche que les venues FLOQR embarquées, pas Google ni Yelp. Les correspondances ouvrent une Place SMARTview compacte (nom, court texte, notes, lien page publique) avec un SMARTbackground — pas un puits photo. Photos de patrons et pitches ShoutOut / VIP restent hors sujet sauf si vous les avez demandés. S’il n’y a encore rien, BOT DEE le dit."},"help-botdee-page":{"title":"BOT DEE","body":"Discutez avec BOT DEE sur la page BOT DEE en mots simples : événements et clubs, ShoutOut, Mingl, RydR, BartR, FloqCAST, votre profil, les plannings du personnel ou les outils Club Admin. Appuyez sur Entrée pour envoyer ; Maj+Entrée commence une nouvelle ligne. BOT DEE discute comme une personne (essayez How are you?) et ne cherche que lorsque vous demandez comment faire quelque chose dans FLOQR. Si vous êtes connecté, BOT DEE conserve cette discussion si vous actualisez ou ouvrez un autre téléphone, et après la pause il peut reprendre l’historique enregistré. La pause ne supprime pas le chat. Les réponses respectent la classification de votre compte. Connecté, BOT DEE voit les mêmes datapoints publics volontaires que vous (musique, nourriture, voyage, hobbies et le reste de Privacy datapoint sharing) — jamais e-mail, téléphone, données de carte ou GPS. Touchez Réglages sous la zone de chat pour les discussions et souvenirs enregistrés. Touchez une photo du chat pour l’ouvrir dans une fenêtre. Fermez avec X ou Fermer pour revoir le chat. Le + en haut à droite ouvre les chats enregistrés sans les supprimer."},"help-botdee-smartview-troubleshoot":{"title":"Dépannage SMARTview","body":"Carte vide : champs masqués ou blocage. Échec d’enregistrement : reconnectez-vous — les traductions sont sur le serveur. Traduction en attente ou en échec : langue source étiquetée. Seul le titulaire édite. SMARTviews Master Admin reste le catalogue mock ; Places et Yelp restent coupés. Le thème suit Site Chrome."},"help-botdee-smartcard-sync":{"title":"Le SMARTsummary reste synchronisé","body":"Modifiez votre SMARTsummary dans la langue par défaut du profil. L’enregistrement est immédiat. Les cartes et SMARTview déjà ouverts se mettent à jour depuis le même enregistrement. Les traductions partent en arrière-plan et n’écrasent pas une édition plus récente. Si vous masquez le profil, bloquez quelqu’un ou supprimez le compte, les cartes disparaissent. Gemini n’écrase pas votre texte."},"help-botdee-smartcard-search":{"title":"Demander à BOT DEE qui est quelqu’un","body":"« Who am I ? » ouvre votre SMARTview. « Who is … », « What do you know of … » ou « What about … » plus prénom, nom, nom d’affichage, identifiant Mingl ou FloqR, ou un identifiant social (Instagram, TikTok, X). La recherche ne porte que sur ces champs d’identité — pas la bio, les likes, les boissons ni les genres. Un résultat ouvre une carte People SMARTview dans le chat — pas une liste markdown ni une grille de photos. Plusieurs résultats montrent des SMARTcards compactes. Les profils privés, bloqués ou non publiés n’apparaissent pas — BOT DEE ne confirme pas l’existence du compte."},"help-botdee-smartcard":{"title":"SMARTcards Personnes","body":"Quand plusieurs profils publics FLOQR correspondent, BOT DEE affiche des SMARTcards compactes dans le chat : photo pleine largeur d’abord, puis nom et identifiant, puis un SMARTsummary compact sans boîte remplie. Touchez une carte pour ouvrir le SMARTview complet — même empilement. Les cartes utilisent le même profil public et le même SMARTsummary que SMARTview. Ouvrir une carte n’appelle pas Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Saisissez Ver, Vers ou Version — les majuscules ne comptent pas. BOT DEE affiche la carte de version. Une question plus longue comme « quelle est votre version ? » affiche aussi cette carte."},"help-botdee-version-smartview-status":{"title":"L’état Version SMARTview est une sonde live","body":"L’état du service est sondé sur cette requête Version : Functions et package joignables avec Gemini configuré → Opérationnel ; Functions et package OK mais Gemini non configuré → Dégradé ; Functions absentes de cette requête → Indisponible. Jamais un libellé statique Non vérifié. Le modèle d’IA affiche l’identifiant Gemini configuré pour ce déploiement même si ce tour n’a pas généré. Les tampons frontend et backend peuvent différer ; les deux sont étiquetés. Master Admin peut voir des diagnostics sous Détails techniques — pas les patrons."},"help-botdee-version-smartview-tabs":{"title":"Onglets Version SMARTview","body":"Aperçu décrit BOT DEE et ouvre les Détails techniques sans quitter le chat. Nouveautés n’affiche que les changements BOT DEE et Gemini vérifiés — pas Master Admin, les outils bêta-testeur, ni les autres notes produit FLOQR. Aide répète la commande Ver / Vers / Version. Changer d’onglet ou déplier garde le brouillon non envoyé et le défilement. La carte utilise votre Site Chrome — pas de second thème."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"Dans le chat BOT DEE, dites Open Room SMARTview, Start a group chat, ou planifiez un voyage à Cancun en mots simples. Ensuite : Rejoindre maintenant ou Définir un horaire. Rejoindre maintenant ouvre une session d’amis Mingl tout de suite et ne met pas de carte sur Search. Définir un horaire, c’est le début de la room BOT DEE — pas Shared Itinerary — et active SMARTnotification Search pour vous et les amis Mingl invités. Invitez seulement des amis Mingl — hôte plus 7 invités. Les invités peuvent aussi inviter. Rejoindre n’est pas un paiement et n’ouvre pas d’addition partagée. BOT DEE ne prend jamais de numéros de carte. Les messages BOT DEE privés restent privés. Site Chrome suit Appearance. Une room en ligne reste ouverte jusqu’à End Room, environ quatre heures après l’ouverture, ou si tout le monde est parti depuis environ 15 minutes. La pause du chat BOT DEE privé est séparée."},"help-botdee-room-smartview-invite":{"title":"Inviter des amis Mingl","body":"Après Confirm, Invite n’affiche que vos amis Mingl. Chaque invitation est liée à cet ami et arrive dans Inbox comme Review BOT DEE invite. Ce n’est pas un lien public. Capacité : hôte plus 7. Les invités peuvent inviter d’autres amis Mingl sauf si l’hôte désactive cela. Rejoindre n’est pas un paiement. Si une puce est vous ou quelqu’un déjà dans la session, elle reste marquée C’est vous ou Déjà dans cette session et n’envoie pas une deuxième invitation."},"help-botdee-room-smartview-join":{"title":"Rejoindre une session BOT DEE","body":"Ouvrez l’invitation Inbox en étant connecté comme l’ami Mingl destinataire. Mauvais compte, expiration ou révocation refuse. Rejoindre la room n’est pas rejoindre une addition et n’approuve pas un paiement. BOT DEE ne prend jamais de numéros de carte."},"help-botdee-room-smartview-end":{"title":"Terminer Room SMARTview","body":"Seul l’hôte peut terminer une room. Terminer ne facture personne et n’efface pas les chats privés des autres. Une addition partagée impayée doit d’abord être payée ou annulée. Une room en ligne reste ouverte jusqu’à End Room, environ quatre heures après l’ouverture, ou si tout le monde est parti depuis environ 15 minutes. La pause du chat BOT DEE privé n’est pas une déconnexion de room. Un invité qui part ne termine pas la room tant que l’hôte est présent."},"help-botdee-room-smartview-tab":{"title":"Addition partagée Room SMARTview","body":"D’abord l’opt-in. Puis ajoutez une ligne. Fermez en un payeur ou en partage. Seuls les uid qui confirment sont débités via FloqR Stripe. Rejoindre la room n’est pas rejoindre l’addition. BOT DEE ne prend jamais de numéros de carte. Club POS plus tard."},"help-botdee-room-smartview-who-pays":{"title":"Qui paie","body":"Demandez Who’s paying dans Room SMARTview pour voir l’opt-in. Personne n’est débité parce que quelqu’un a dit buy. Les quatre derniers chiffres restent sur le reçu du payeur."},"help-botdee-room-smartview-kick":{"title":"Retirer quelqu’un de Room SMARTview","body":"Seul l’hôte peut retirer un invité. Un ami retiré ne lit plus les messages de la room. Une réponse du modèle ne peut exclure personne."},"help-botdee-room-smartview-share":{"title":"Partager dans Room SMARTview","body":"Share this conversation ne copie jamais votre fil BOT DEE privé. BOT DEE montre un aperçu de faits partageables de ce message, marqués provisoires. Vous pouvez modifier ou retirer des faits. Profils et SMARTsummary restent hors de la room."},"help-botdee-room-smartview-schedule":{"title":"Rejoindre maintenant ou définir un horaire","body":"Après la configuration Room SMARTview, choisissez Rejoindre maintenant ou Définir un horaire. Rejoindre maintenant ouvre la session BOT DEE tout de suite et ne met pas de carte sur Search. Définir un horaire, c’est le début de la room BOT DEE — pas Shared Itinerary. Une heure future active SMARTnotification Search pour vous et les amis Mingl invités seulement. Les invités RSVP jusqu’à ce que la room soit en ligne ; Join Now ouvre alors BOT DEE (pas Mingl chat)."},"help-botdee-room-collab":{"title":"Partager une réservation headless dans Room SMARTview","body":"Dans une Room SMARTview, les choix VIP reserV ou ShoutOut de l’hôte apparaissent pour tout le monde. Les membres votent Oui ou Non. Hold it et le paiement restent à l’hôte — rejoindre et voter n’est pas un paiement. BOT DEE ne prend jamais de numéros de carte. Stripe s’ouvre dans un pop-out."},"help-botdee-room-elect-host":{"title":"Élire un hôte Room SMARTview","body":"N’importe qui dans la session peut être hôte. Proposez-vous ou un autre membre. Un candidat devient hôte à 60 % des membres actuellement présents (arrondi supérieur). Si l’hôte part, les autres élisent un nouvel hôte — la room reste ouverte. Kick et End restent à l’hôte élu."},"help-botdee-smartview-review":{"title":"Relire et corriger un SMARTsummary","body":"Gemini rédige uniquement à partir des champs publics dans FLOQR — jamais à chaque vue. Si un fait est faux, masquez le champ dans la visibilité du profil ou modifiez le résumé. Un texte rédigé par vous n’est pas écrasé. Un conflit de profil demande une relecture. Signalez une carte incorrecte depuis l’overlay."},"help-botdee-smartview-chrome":{"title":"SMARTview et Site Chrome","body":"Le SMARTview personne utilise le Site Chrome FLOQR du visiteur (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Pas de second thème. Changer le chrome met à jour la carte sans perdre le brouillon."},"help-botdee-smartview-categories":{"title":"Catégories SMARTview","body":"Quatre onglets : Social, Rencontre, Cuisine, Voyages à venir. Social s’ouvre sur Musique, puis Nightlife, Sports et Événements. Les tags sont uniquement ce que vous avez partagé — pas de titres en double ni de voyages ou notes inventés. Les voyages à venir n’affichent que les destinations publiques."},"help-botdee-smartview-media":{"title":"Photos et vidéos SMARTview","body":"La carte compacte utilise le même visuel que votre profil public FLOQR — le premier élément Médias du profil (8 photos + 2 vidéos). Appuyez pour Photos et Vidéos depuis ces emplacements publics. Balayez ou flèches, puis X (ou Échap) pour retrouver le chat et le brouillon."},"help-botdee-smartview-privacy":{"title":"Confidentialité SMARTview","body":"SMARTview n’affiche que les champs déjà publics dans FLOQR. Ce n’est pas une recherche web. La rencontre n’apparaît qu’avec opt-in. Masquez un champ dans Mon profil et il quitte SMARTview. Les personnes bloquées ne voient pas la carte. Signalez un résumé incorrect depuis l’overlay."},"help-botdee-smartview-translation":{"title":"Traduction SMARTview","body":"Votre SMARTsummary est enregistré dans la langue par défaut du profil — c’est la source, même si ce n’est pas l’anglais. Après enregistrement, FLOQR met en file une traduction vers chaque autre langue, y compris l’anglais. Un visiteur anglais voit le SMARTsummary en anglais une fois ce travail terminé. En attente ou en échec, les lecteurs voient la langue source clairement indiquée — jamais une traduction périmée comme actuelle."},"help-botdee-smartview-edit":{"title":"Modifier votre SMARTsummary","body":"Vous seul pouvez modifier votre SMARTsummary, dans la langue par défaut du profil. L’enregistrement est immédiat. Les traductions partent en arrière-plan. Gemini n’écrase pas un texte que vous avez modifié. Si le profil public change, FLOQR vous demande de relire le résumé."},"help-botdee-privacy-assistant":{"title":"Assistant confidentialité BOT DEE","body":"Changez ce que les autres utilisateurs FLOQR voient dans la visibilité de Mon profil — BOT DEE n’ajoute pas un second interrupteur public. Si la recherche web a lié la mauvaise personne, vous pouvez contester sans changer votre profil. BOT DEE ne promet pas qu’un site tiers supprimera la page d’origine."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Chaque recommandation peut montrer les preuves, la date de vérification, si la personnalisation était active, et si un emplacement est sponsorisé. Vous pouvez demander à BOT DEE de ne pas personnaliser cette recherche."},"help-botdee-research-library":{"title":"Bibliothèque de recherche BOT DEE","body":"Enregistrez les lieux et cartes demandés à BOT DEE. Un identifiant Google Place n’est pas une copie des photos ou avis Google. Vous pouvez actualiser ou supprimer. Les caches licenciés restent off tant que le fournisseur n’est pas approuvé."},"help-botdee-smartview":{"title":"Voir mon SMARTview","body":"Voir mon SMARTview affiche votre carte Personne depuis les champs publics FLOQR, avec les mêmes Médias du profil que la page publique — pas des maquettes de club ou restaurant. Modifier mon SMART Summary change le résumé dans la langue du profil. Les maquettes club/restaurant sont dans Master Admin → Features → BOT DEE → SMARTviews. Pas de Places ni Yelp en direct."},"help-botdee-memory":{"title":"Chats BOT DEE enregistrés","body":"Ouvrez Fonctionnalités et commandes → Mon BOT DEE pour enregistrer les chats après la pause, exporter ou supprimer l’historique. La pause de cinq minutes termine la session en direct. Si vous acceptez, BOT DEE conserve le chat. Les invités ne sont pas enregistrés. Mingl reste dans Mingl."},"help-botdee-knows-of-me":{"title":"Ce que BOT DEE sait de moi","body":"Les faits enregistrés avec votre accord se trouvent dans Fonctionnalités et commandes → Mon BOT DEE. La liste est vide si la mémoire est désactivée ou vide. Exportez ou supprimez ici. BOT DEE n’enregistre jamais votre adresse IP. Mingl n’est pas copié."},"help-search-settings-appearance":{"title":"Settings sur Search","body":"Sur l’écran Search, touchez Settings pour ouvrir Profile & Settings sur l’onglet Appearance — le Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green) s’y trouve. La tuile Settings utilise le même pack d’icônes chrome que les autres marques Search."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"FloqR Inbox contient les System Messages et les messages de support internes. La liste se charge d’abord pour afficher vos messages rapidement. Appuyez sur le bouton flottant New Message pour composer — saisissez un nom ou @username pour trouver un destinataire autorisé (Club Admin, CSR ou personnel approuvé). Le chat patron-à-patron reste dans Mingl après un Mingl mutuel. Ouvrir une invitation de shift ne confirme pas — examinez et Approve selected sur Work Calendar."},"help-become-dj":{"title":"Devenez un DJ","body":"Choisissez DJ comme votre rôle de service et associez-vous à des clubs."},"help-become-promoter":{"title":"Devenez un Promoter","body":"Demandez un accès Promoter aux listes d'invités et aux campagnes."},"help-template-tags":{"title":"Tags des modèles","body":"Ajoutez des mots que les clients pourraient taper pour trouver un modèle dans votre lieu, comme soirée match ou anniversaire. Les Gestionnaires des modèles peuvent ajouter des tags. Les Administrateurs des modèles et les Club Admins peuvent aussi en retirer. Le Club Admin attribue ces rôles dans Role Activity & Permission."},"help-vip-door-pass":{"title":"Pass porte VIP reserV","body":"Après confirmation de l’acompte, Mon profil → Réservations → Afficher le pass pour un jeton QR unique. Apportez une ID 21+. Le personnel utilise VIP reserV Door."},"help-vip-door-ops":{"title":"Enregistrement porte VIP reserV","body":"Les VIP Managers ouvrent VIP reserV Door pour ce soir. Scannez ou collez le jeton, confirmez ID 21+, enregistrez. No-show seulement après grâce. Un lien notify ne change pas le statut."}},"de":{"help-smartvisuals-notification":{"title":"Mingl Room SMARTnotification","body":"Eine kompakte Mingl-Room-Einladung kann auf Search erscheinen, wenn ein Mingl-Freund eine BOT DEE-Room geplant hat, zu der Sie eingeladen sind. Einladung ansehen öffnet Room SMARTview. Join Now geht zu BOT DEE, nicht Mingl-Chat. Nicht jetzt blendet die Karte in diesem Tab aus; Inbox behält Review BOT DEE invite. Die Cancun-Demo-Abfrage ist nur Studio. Kunst ist Illustration, kein Foto. Join-Now-Rooms ohne Zeitplan erscheinen nicht auf Search."},"help-smartvisuals-room":{"title":"Room SMARTview mit SMARTvisuals","body":"Room SMARTview zeigt die Mingl-Einladung: Zeitplan, RSVP oder Live-Status und Join Now. Join Now auf Search öffnet BOT DEE (nicht Mingl-Chat) mit room= und t=. SMARTstencils und SMARTbackgrounds folgen dem autorisierten Room-Titel — Cancun Trip nutzt Reisekunst, kein echtes Cancun-Foto. Privater BOT DEE-Chat wählt nie die Kunst. Ein beschriftetes Ad darunter ist ein Muster aus diesen Tags. Leer bei privatem Chat oder Injektion; kein Live-Werber."},"help-scheduling-schedule-for":{"title":"Mitarbeiterplanung","body":"Plane Schichten und Bookings und benachrichtige jede Person per Inbox, Email, SMS oder WhatsApp. Unter „Planen für“ wählst du, wessen Kalender du bearbeitest: „Mein DJ-Plan“ ist dein eigener Kalender, „Club“ zeigt die Clubs, die du verwaltest, und „Promo-Firma“ die Firmen, für die du promotest. Jeder Kalender hat sein eigenes Abo für 20 $/Monat. Schichten für dich erscheinen unter „Meine Einsätze“, wo du sie bestätigst oder ablehnst."},"help-staff-marketing-consent":{"title":"Marketing-Einwilligung für Personal","body":"Wenn du dem Team einer Location oder eines Events beitrittst, musst du das Feld zur Marketing-Einwilligung anhaken. Damit dürfen diese Location oder dieser Veranstalter sowie deren Admins und Manager deinen FLOQR-Namen, deine Rolle und deine veröffentlichten Fotos und Videos auf ihren Websites, Flyern und in sozialen Medien (Instagram, Facebook, TikTok, YouTube und ähnliche) nutzen, ohne dich für jede Nutzung erneut zu fragen. Deine Telefonnummer und E-Mail dürfen sie nicht veröffentlichen. Du kannst jederzeit in Mein Profil im Tab Services und Service-Mitglieder widerrufen. Das stoppt neues Marketing; bereits gedruckte oder gepostete Materialien müssen nicht zurückgerufen werden. Club Admins sehen den Einwilligungsstatus jeder Person im Mitarbeiter- und Personalnetzwerk und bei Hervorgehobenes Personal."},"help-botdee-privacy-session":{"title":"BOT DEE Datenschutz und Sitzung","body":"Die fünfminütige Pause beendet die Live-Sitzung. Sie löscht nicht diesen angemeldeten Chat, Erinnerungen oder Workflows. Optionale Kopien unter Mein Profil → Funktionen & Bestellungen → My BOT DEE bleiben. Gäste bleiben flüchtig. Mingl-Chats werden hier nie kopiert. Enter sendet; Umschalt+Enter beginnt eine neue Zeile. Name und Ton stellst du unter Mein Profil → My BOT DEE ein, nicht per Schaltfläche im Chat."},"help-botdee-place-search":{"title":"BOT DEE nach FLOQR-Locations fragen","body":"Fragen Sie in einfachen Worten — Sushi-Restaurants in Washington DC, Clubs in DC oder einen Clubnamen. BOT DEE sucht nur onboardete FLOQR-Venues, nicht Google oder Yelp. Treffer öffnen eine kompakte Place SMARTview (Name, Kurztext, Bewertungen, Public-Page-Link) mit SMARTbackground — keinen Fotoschacht. Patron-Fotos und ShoutOut-/VIP-Pitches bleiben weg, außer Sie haben danach gefragt. Ist noch nichts onboardet, sagt BOT DEE das."},"help-botdee-page":{"title":"BOT DEE","body":"Chatte mit BOT DEE auf der BOT DEE-Seite in einfachen Worten: Events und Clubs, ShoutOut, Mingl, RydR, BartR, FloqCAST, dein Profil, Mitarbeiterpläne oder Club-Admin-Werkzeuge. Enter sendet die Nachricht; Umschalt+Enter beginnt eine neue Zeile. BOT DEE chattet wie ein Mensch (versuch How are you?) und sucht nur, wenn du fragst, wie man etwas in FLOQR macht. Wenn du angemeldet bist, behält BOT DEE diesen Chat beim Aktualisieren oder auf einem zweiten Handy, und nach der Pause den gespeicherten Verlauf fortsetzen. Die Pause löscht den Chat nicht. Antworten nutzen die Klassifizierung deines Kontos. Angemeldet sieht BOT DEE dieselben freiwillig öffentlichen Profildatenpunkte wie du (Musik, Essen, Reisen, Hobbys und der Rest von Privacy datapoint sharing) — niemals E-Mail, Telefon, Kartendaten oder GPS. Tippe unter dem Chatfeld auf Einstellungen für gespeicherte Chats und Erinnerungen. Tippe im Chat auf ein Foto, um es in einem eigenen Fenster zu öffnen. Schließen mit X oder Schließen, um den Chat wieder zu sehen. Das + oben rechts öffnet gespeicherte Chats und löscht sie nicht."},"help-botdee-smartview-troubleshoot":{"title":"SMARTview-Fehlerbehebung","body":"Leere Karte: Felder ausgeblendet oder blockiert. Speichern fehlgeschlagen: anmelden — Übersetzungen laufen auf dem Server. Ausstehend/Fehler: Quellsprache mit Label. Nur der Inhaber bearbeitet. Master-Admin-SMARTviews bleibt Mock; Places/Yelp aus. Theme folgt Site Chrome."},"help-botdee-smartcard-sync":{"title":"SMARTsummary bleibt synchron","body":"Bearbeiten Sie Ihre SMARTsummary in der Standard-Profilsprache. Speichern ist sofort. Offene Karten und SMARTview aktualisieren sich aus demselben Datensatz. Übersetzungen laufen im Hintergrund und überschreiben keine neuere Bearbeitung. Wenn Sie das Profil verbergen, jemanden blockieren oder das Konto löschen, verschwinden die Karten. Gemini überschreibt Ihren Text nicht."},"help-botdee-smartcard-search":{"title":"BOT DEE fragen, wer jemand ist","body":"„Who am I?“ öffnet Ihre SMARTview. „Who is …“, „What do you know of …“ oder „What about …“ plus Vorname, Nachname, Anzeigename, Mingl- oder FloqR-Handle oder ein Social-Handle (Instagram, TikTok, X). Treffer nur über diese Identitätsfelder — nicht über Bio, Likes, Getränke oder Genres. Ein Treffer öffnet eine People-SMARTview-Karte im Chat — keine Markdown-Liste und kein Fotogitter. Mehrere Treffer zeigen kompakte SMARTcards. Private, blockierte oder unveröffentlichte Profile erscheinen nicht — BOT DEE bestätigt nicht, ob das Konto existiert."},"help-botdee-smartcard":{"title":"Personen-SMARTcards","body":"Wenn mehrere öffentliche FLOQR-Profile passen, zeigt BOT DEE kompakte Personen-SMARTcards im Chat: zuerst das Foto in voller Breite, dann Name und Handle, dann eine kompakte SMARTsummary ohne gepolsterte Box. Tippen öffnet die volle SMARTview — dasselbe Layout. Karten nutzen dasselbe öffentliche Profil und dieselbe SMARTsummary. Öffnen ruft Gemini nicht auf."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Geben Sie Ver, Vers oder Version ein — Groß- und Kleinschreibung spielt keine Rolle. BOT DEE zeigt die Versionskarte. Eine längere Frage wie „Was ist deine Version?“ zeigt ebenfalls diese Karte."},"help-botdee-version-smartview-status":{"title":"Version-SMARTview-Status ist eine Live-Prüfung","body":"Der Dienststatus wird bei dieser Version-Anfrage geprüft: Functions und Package erreichbar und Gemini konfiguriert → Betriebsbereit; Functions und Package da, Gemini nicht konfiguriert → Eingeschränkt; Functions nicht in dieser Anfrage → Nicht verfügbar. Nie ein statisches Nicht geprüft. Das KI-Modell zeigt die konfigurierte Gemini-Modell-ID dieses Deployments, auch wenn dieser Zug nicht generiert. Frontend- und Backend-Stempel können sich unterscheiden; beide sind beschriftet. Master Admin sieht extra Diagnosen unter Technische Details — Gäste nicht."},"help-botdee-version-smartview-tabs":{"title":"Version-SMARTview-Reiter","body":"Übersicht beschreibt BOT DEE und öffnet Technische Details ohne den Chat zu verlassen. Neuigkeiten listet nur geprüfte BOT-DEE- und Gemini-Änderungen — nicht Master Admin, Beta-Tester-Werkzeuge oder andere FLOQR-Produkthinweise. Hilfe wiederholt den Befehl Ver / Vers / Version. Reiterwechsel oder Aufklappen behält den ungesendeten Entwurf und den Scroll. Die Karte nutzt Ihr Site Chrome — kein zweites Thema."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"Im BOT DEE-Chat sagen Sie Open Room SMARTview, Start a group chat oder planen Sie eine Cancun-Reise in einfachen Worten. Danach: Jetzt beitreten oder Zeitplan festlegen. Jetzt beitreten öffnet eine Mingl-Freunde-Session sofort und legt keine Karte auf Search. Zeitplan festlegen ist der Start der BOT DEE-Room — nicht Shared Itinerary — und schaltet Search SMARTnotification für Sie und eingeladene Mingl-Freunde ein. Nur Mingl-Freunde einladen — Host plus 7 Gäste. Gäste können auch einladen. Beitreten ist keine Zahlung und öffnet keine geteilte Rechnung. BOT DEE nimmt nie Kartennummern. Private BOT DEE-Nachrichten bleiben privat. Site Chrome folgt Appearance. Eine Live-Room bleibt offen, bis der Host End Room tippt, etwa vier Stunden nach dem Öffnen, oder alle etwa 15 Minuten weg sind. Die Pause des privaten BOT DEE-Chats ist getrennt."},"help-botdee-room-smartview-invite":{"title":"Mingl-Freunde einladen","body":"Nach Confirm zeigt Invite nur deine Mingl-Freunde. Jede Einladung ist an diesen Freund gebunden und landet in Inbox als Review BOT DEE invite. Kein öffentlicher Join-Link. Maximum Gastgeber plus 7. Gäste können weitere Mingl-Freunde einladen, bis der Gastgeber das abschaltet. Beitreten ist keine Zahlung. Ist ein Chip du selbst oder schon in der Sitzung, bleibt er mit Das sind Sie oder Schon in dieser Sitzung markiert und sendet keine zweite Einladung."},"help-botdee-room-smartview-join":{"title":"Einer BOT DEE-Sitzung beitreten","body":"Öffne die Inbox-Einladung, angemeldet als der Mingl-Freund, dem sie gilt. Falsches Konto, Ablauf oder Widerruf lehnt ab. Der Room ist nicht der Tab und genehmigt keine Zahlung. BOT DEE nimmt niemals Kartennummern."},"help-botdee-room-smartview-end":{"title":"Room SMARTview beenden","body":"Nur der Host kann einen Room beenden. Beenden belastet niemanden und löscht keine privaten Chats anderer. Eine unbezahlte geteilte Rechnung muss zuerst bezahlt oder storniert werden. Eine Live-Room bleibt offen bis End Room, etwa vier Stunden nach dem Öffnen, oder bis alle etwa 15 Minuten weg sind. Die Pause des privaten BOT DEE-Chats ist kein Room-Logout. Ein Gast, der geht, beendet die Room nicht, solange der Host da ist."},"help-botdee-room-smartview-tab":{"title":"Gemeinsamer Tab Room SMARTview","body":"Zuerst zustimmen. Dann eine Zeile hinzufügen. Als ein Zahler oder geteilt schließen. Nur bestätigende uids werden über FloqR Stripe belastet. Dem Room beitreten heißt nicht dem Tab beitreten. BOT DEE nimmt niemals Kartennummern. Club POS kommt später."},"help-botdee-room-smartview-who-pays":{"title":"Wer zahlt","body":"Frage Who’s paying in Room SMARTview, um den Opt-in zu sehen. Niemand wird belastet, weil jemand buy gesagt hat. Die letzten vier der Karte bleiben auf dem Beleg des Zahlers."},"help-botdee-room-smartview-kick":{"title":"Jemanden aus Room SMARTview entfernen","body":"Nur der Gastgeber kann einen Gast entfernen. Ein entfernter Freund liest keine weiteren Raumnachrichten. Eine Modellantwort kann niemanden kicken."},"help-botdee-room-smartview-share":{"title":"In Room SMARTview teilen","body":"Share this conversation kopiert niemals deinen privaten BOT DEE-Thread. BOT DEE zeigt eine Vorschau ausgewählter teilbarer Fakten aus dieser Nachricht, als vorläufig markiert. Du kannst Fakten bearbeiten oder streichen. Profile und SMARTsummary bleiben draußen."},"help-botdee-room-smartview-schedule":{"title":"Jetzt beitreten oder Zeitplan festlegen","body":"Nach dem Room-SMARTview-Setup wählen Sie Jetzt beitreten oder Zeitplan festlegen. Jetzt beitreten öffnet die BOT DEE-Session sofort und legt keine Karte auf Search. Zeitplan festlegen ist der Start der BOT DEE-Room — nicht Shared Itinerary. Ein zukünftiger Zeitpunkt schaltet Search SMARTnotification nur für Sie und eingeladene Mingl-Freunde ein. Gäste sagen zu, bis die Room live ist; dann öffnet Join Now BOT DEE (nicht Mingl-Chat)."},"help-botdee-room-collab":{"title":"Headless-Buchung in Room SMARTview teilen","body":"In einer Room SMARTview sehen alle die VIP reserV- oder ShoutOut-Auswahl des Gastgebers. Mitglieder stimmen Ja oder Nein. Hold it und Bezahlen bleiben beim Gastgeber — Beitreten und Abstimmen ist keine Zahlung. BOT DEE nimmt niemals Kartennummern. Stripe öffnet in einem Pop-out."},"help-botdee-room-elect-host":{"title":"Room SMARTview-Gastgeber wählen","body":"Jeder in der Session kann Gastgeber sein. Nominiere dich oder ein anderes Mitglied. Ein Kandidat wird Gastgeber bei 60 % der aktuell beigetretenen Mitglieder (aufgerundet). Wenn der Gastgeber geht, wählen die übrigen einen neuen — der Room bleibt offen. Kick und End bleiben beim gewählten Gastgeber."},"help-botdee-smartview-review":{"title":"SMARTsummary prüfen und korrigieren","body":"Gemini entwirft nur aus öffentlichen FLOQR-Feldern — nie bei jedem Öffnen. Falsche Fakten: Feld in der Profilsichtbarkeit ausblenden oder Summary selbst ändern. Ihr Text wird nicht überschrieben. Profilkonflikte verlangen Prüfung. Falsche Karten im Overlay melden."},"help-botdee-smartview-chrome":{"title":"SMARTview und Site Chrome","body":"People SMARTview nutzt das FLOQR Site Chrome des Betrachters (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Kein zweites Theme. Chrome-Wechsel aktualisiert die Karte, der Chat-Entwurf bleibt."},"help-botdee-smartview-categories":{"title":"SMARTview-Kategorien","body":"Vier Tabs: Social, Dating, Dining, Zukünftige Reisen. Social startet bei Musik, dann Nightlife, Sport, Events. Tags nur Geteiltes — keine doppelten Überschriften, keine erfundenen Reisen oder Bewertungen. Künftige Reisen nur öffentlich markierte Ziele."},"help-botdee-smartview-media":{"title":"SMARTview-Fotos und Videos","body":"Die Karte nutzt dasselbe Hero-Bild wie Ihre öffentliche FLOQR-Seite — das erste Profile-Media-Element (8 Fotos + 2 Videos). Tippen öffnet Fotos und Videos aus diesen öffentlichen Slots. Wischen oder Pfeile, dann X (oder Escape) zurück zum Chat und Entwurf."},"help-botdee-smartview-privacy":{"title":"SMARTview-Datenschutz","body":"SMARTview zeigt nur Felder, die in FLOQR schon öffentlich sind. Keine Websuche. Dating nur mit Opt-in. Blenden Sie ein Feld in Mein Profil aus, verschwindet es. Blockierte Personen sehen die Karte nicht. Falsche Summaries im Overlay melden."},"help-botdee-smartview-translation":{"title":"SMARTview-Übersetzung","body":"Ihre SMARTsummary wird in der Standard-Profilsprache gespeichert — das ist die Quelle, auch wenn es nicht Englisch ist. Nach dem Speichern reiht FLOQR eine Übersetzung für jede andere Sprache ein, einschließlich Englisch. Ein englischsprachiger Betrachter sieht die englische SMARTsummary, sobald der Job fertig ist. Bei ausstehend oder Fehler sehen Betrachter die Quellsprache klar gekennzeichnet — nie eine veraltete Übersetzung als aktuell."},"help-botdee-smartview-edit":{"title":"SMARTsummary bearbeiten","body":"Nur Sie bearbeiten Ihre SMARTsummary in der Standard-Profilsprache. Speichern ist sofort. Übersetzungen laufen im Hintergrund. Gemini überschreibt Ihren Text nicht. Wenn sich das öffentliche Profil ändert, prüft FLOQR mit Ihnen statt zu ersetzen."},"help-botdee-privacy-assistant":{"title":"BOT DEE Privacy Assistant","body":"Ändern Sie in Mein Profil, was andere FLOQR-Nutzer sehen — BOT DEE fügt keinen zweiten Öffentlich-Schalter hinzu. Falsche Web-Zuordnung können Sie widersprechen, ohne das Profil zu ändern. BOT DEE verspricht keine Löschung auf Drittseiten."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Jede Empfehlung kann Belege, Prüfdatum, Personalisierung und Sponsoring zeigen. Sie können BOT DEE bitten, diese Suche nicht zu personalisieren."},"help-botdee-research-library":{"title":"BOT DEE Research Library","body":"Speichern Sie Orte und Karten, die Sie BOT DEE gefragt haben. Eine Google Place-ID ist keine Kopie von Fotos oder Bewertungen. Sie können aktualisieren oder löschen. Lizenzierte Caches bleiben aus, bis der Anbieter genehmigt ist."},"help-botdee-smartview":{"title":"Mein SMARTview anzeigen","body":"Mein SMARTview zeigt Ihre Personenkarte aus öffentlichen FLOQR-Feldern, mit denselben Profile Media wie die öffentliche Seite — keine Club- oder Restaurant-Mocks. Meine SMART Summary bearbeiten ändert den Text in Ihrer Profilsprache. Gekennzeichnete Mock-Karten liegen unter Master Admin → Features → BOT DEE → SMARTviews. Kein Live-Places oder Yelp."},"help-botdee-memory":{"title":"Gespeicherte BOT DEE-Chats","body":"Öffnen Sie Funktionen & Bestellungen → Mein BOT DEE, um Chats nach der Pause zu speichern, zu exportieren oder den Verlauf zu löschen. Die 5-Minuten-Pause beendet die Live-Sitzung. Mit Opt-in behält BOT DEE den Chat. Gäste werden nicht gespeichert. Mingl bleibt Mingl."},"help-botdee-knows-of-me":{"title":"Was BOT DEE von mir weiß","body":"Mit Ihrer Zustimmung gespeicherte Fakten liegen unter Funktionen & Bestellungen → Mein BOT DEE. Die Liste ist leer, wenn die Erinnerung aus ist oder nichts gespeichert ist. Export oder Löschung hier. BOT DEE speichert keine IP-Adresse. Mingl wird nicht kopiert."},"help-search-settings-appearance":{"title":"Settings auf Search","body":"Tippe auf dem Search-Bildschirm auf Settings, um Profile & Settings auf dem Tab Appearance zu öffnen — dort liegt Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Die Settings-Kachel nutzt dasselbe Chrome-Icon-Paket wie die anderen Search-Marken."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"FloqR Inbox enthält System Messages und interne Support-Nachrichten. Die Liste lädt zuerst, damit Nachrichten schnell erscheinen. Tippe auf den schwebenden New Message-Button zum Verfassen — gib einen Namen oder @username ein, um einen erlaubten Empfänger zu finden (Club Admin, CSR oder genehmigtes Personal). Patron-zu-Patron-Chat bleibt in Mingl nach gegenseitigem Mingl. Eine Schicht-Einladung zu öffnen bestätigt nicht — prüfe und tippe Approve selected im Work Calendar."},"help-become-dj":{"title":"Werde ein DJ","body":"Wählen Sie DJ als Ihre Servicerolle und verbinden Sie sich mit Clubs."},"help-become-promoter":{"title":"Werde ein Promoter","body":"Fordern Sie Promoter Zugang für Gästelisten und Kampagnen an."},"help-template-tags":{"title":"Vorlagen-Tags","body":"Füge Wörter hinzu, die Gäste eintippen könnten, wenn sie bei deiner Location eine Vorlage suchen, etwa Spieleabend oder Geburtstag. Vorlagen-Manager können Tags hinzufügen. Vorlagen-Administratoren und Club Admins können Tags auch entfernen. Club Admin vergibt diese Rollen unter Role Activity & Permission."},"help-vip-door-pass":{"title":"VIP reserV Tür-Pass","body":"Nach bestätigter Anzahlung: Mein Profil → Reservierungen → Pass anzeigen für einmaligen QR. Ausweis 21+ mitbringen. Türpersonal nutzt VIP reserV Door."},"help-vip-door-ops":{"title":"VIP reserV Tür-Check-in","body":"VIP Manager öffnen VIP reserV Door für heute. Token scannen/einfügen, ID 21+ prüfen, einchecken. No-Show erst nach Grace. Notify-Links ändern den Status nicht."}},"es":{"help-smartvisuals-notification":{"title":"SMARTnotification de Mingl Room","body":"Una invitación compacta Mingl Room puede aparecer en Search cuando un amigo Mingl programó una room BOT DEE a la que usted está invitado. Ver invitación abre Room SMARTview. Join Now va a BOT DEE, no a Mingl chat. Ahora no oculta la tarjeta en esta pestaña; Inbox sigue con Review BOT DEE invite. La consulta demo Cancun es solo Studio. El arte es ilustración, no foto. Las rooms Join Now sin horario no aparecen en Search."},"help-smartvisuals-room":{"title":"Room SMARTview con SMARTvisuals","body":"Room SMARTview muestra la invitación Mingl: horario, RSVP o estado en vivo, y Join Now. Join Now en Search abre BOT DEE (no Mingl chat) con room= y t=. SMARTstencils y SMARTbackgrounds siguen el título autorizado — Cancun Trip usa arte de viaje, no una foto real de Cancun. El chat privado de BOT DEE nunca elige el arte. Un Ad etiquetado debajo es una muestra de esas etiquetas. Vacío para chat privado o inyección; no es un anunciante en vivo."},"help-scheduling-schedule-for":{"title":"Planificación del personal","body":"Planifica turnos y contrataciones y avisa a cada persona por Inbox, Email, SMS o WhatsApp. En «Horario de», elige el calendario con el que trabajas: «Mi horario de DJ» es tu propio calendario, «Club» muestra los clubs que administras y «Empresa de promoción» las empresas para las que promocionas. Cada calendario tiene su propia suscripción de 20 $/mes. Los turnos que te asignan aparecen en «Mis asignaciones», donde los confirmas o rechazas."},"help-staff-marketing-consent":{"title":"Consentimiento de marketing del personal","body":"Cuando te unes al equipo de un local o evento, debes marcar la casilla de consentimiento de marketing. Permite que ese local u organizador, y sus administradores y gerentes, usen tu nombre de FLOQR, tu rol y tus fotos y videos publicados en sus sitios web, flyers y redes sociales (Instagram, Facebook, TikTok, YouTube y similares) sin volver a pedirte permiso para cada uso. No pueden publicar tu teléfono ni tu correo electrónico. Puedes retirarlo en cualquier momento en Mi perfil, pestaña Servicios y miembros de servicio. Esto detiene el nuevo marketing; los materiales ya impresos o publicados no tienen que retirarse. Los Club Admins ven el estado del consentimiento de cada miembro del personal en Red de empleados y personal y en Personal destacado."},"help-botdee-privacy-session":{"title":"Privacidad y sesión de BOT DEE","body":"La pausa de cinco minutos termina la sesión en vivo. No borra este chat con sesión iniciada, los recuerdos ni los flujos. Las copias en Mi perfil → Funciones y pedidos → My BOT DEE también se quedan. Los invitados siguen siendo efímeros. Los chats de Mingl nunca se copian aquí. Intro envía; Mayús+Intro empieza una línea nueva. Nombre y tono se eligen en Mi perfil → My BOT DEE, no con un botón en el chat."},"help-botdee-place-search":{"title":"Preguntar a BOT DEE por locales FLOQR","body":"Pregunte en palabras simples — restaurantes de sushi en Washington DC, clubs en DC o un club concreto. BOT DEE busca solo venues FLOQR dadas de alta, no Google ni Yelp. Las coincidencias abren un Place SMARTview compacto (nombre, texto corto, valoraciones, enlace a la página pública) con un SMARTbackground — no un pozo de foto. Las fotos de patrons y los pitches de ShoutOut / VIP no aparecen salvo que los pida. Si aún no hay nada, BOT DEE lo dice."},"help-botdee-page":{"title":"BOT DEE","body":"Chatea con BOT DEE en la página BOT DEE con palabras sencillas: eventos y clubs, ShoutOut, Mingl, RydR, BartR, FloqCAST, tu perfil, horarios del personal o herramientas de Club Admin. Pulsa Intro para enviar; Mayús+Intro empieza una línea nueva. BOT DEE habla como una persona (prueba How are you?) y solo busca cuando preguntas cómo hacer algo en FLOQR. Si has iniciado sesión, BOT DEE guarda este chat si actualizas o abres otro teléfono, y después de la pausa puede continuar el historial guardado. La pausa no borra el chat. Las respuestas usan la clasificación de tu cuenta. Si has iniciado sesión, BOT DEE ve los mismos datapoints públicos voluntarios que tú (música, comida, viajes, hobbies y el resto de Privacy datapoint sharing) — nunca email, teléfono, datos de tarjeta ni GPS. Toca Ajustes bajo el cuadro de chat para chats y recuerdos guardados. Toca una foto del chat para abrirla en una ventana. Cierra con X o Cerrar para volver al chat. El + de arriba a la derecha abre chats guardados y no los borra."},"help-botdee-smartview-troubleshoot":{"title":"Solución de problemas de SMARTview","body":"Tarjeta vacía: campos ocultos o bloqueo. Fallo al guardar: inicie sesión — las traducciones van al servidor. Pendiente o error: idioma de origen etiquetado. Solo el titular edita. SMARTviews de Master Admin sigue siendo el catálogo mock; Places y Yelp apagados. El tema sigue Site Chrome."},"help-botdee-smartcard-sync":{"title":"SMARTsummary permanece sincronizado","body":"Edite su SMARTsummary en el idioma predeterminado del perfil. El guardado es inmediato. Las tarjetas y SMARTview abiertos se actualizan desde el mismo registro. Las traducciones van en segundo plano y no sobrescriben una edición más nueva. Si oculta el perfil, bloquea a alguien o elimina la cuenta, esas tarjetas desaparecen. Gemini no sobrescribe su texto."},"help-botdee-smartcard-search":{"title":"Preguntar a BOT DEE quién es alguien","body":"«Who am I?» abre su SMARTview. «Who is …», «What do you know of …» o «What about …» más nombre, apellido, nombre para mostrar, identificador Mingl o FloqR, o un identificador social (Instagram, TikTok, X). Solo coinciden esos campos de identidad — no la bio, los likes, las bebidas ni los géneros. Un resultado abre una tarjeta People SMARTview en el chat — no una lista markdown ni una cuadrícula de fotos. Varios muestran SMARTcards compactas. Perfiles privados, bloqueados o no publicados no aparecen — BOT DEE no confirma si esa cuenta existe."},"help-botdee-smartcard":{"title":"SMARTcards de personas","body":"Si coinciden varios perfiles públicos de FLOQR, BOT DEE muestra SMARTcards compactas en el chat: primero la foto a todo el ancho, luego nombre y @identificador, luego un SMARTsummary compacto sin caja rellena. Toque una tarjeta para abrir el SMARTview completo — el mismo apilado. Las tarjetas usan el mismo perfil público y SMARTsummary. Abrir una tarjeta no llama a Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Escriba Ver, Vers o Version — las mayúsculas no importan. BOT DEE muestra la tarjeta de versión. Una pregunta más larga como “¿cuál es tu versión?” también muestra esa tarjeta."},"help-botdee-version-smartview-status":{"title":"El estado de Version SMARTview es una sonda en vivo","body":"El estado del servicio se sondea en esta petición Version: Functions y paquete alcanzables con Gemini configurado → Operativo; Functions y paquete bien pero Gemini no configurado → Degradado; Functions no en esta petición → No disponible. Nunca una etiqueta estática Sin comprobar. El modelo de IA muestra el id de Gemini configurado de este despliegue aunque este turno no genere. Los sellos de frontend y backend pueden diferir; ambos se etiquetan. Master Admin puede ver diagnósticos extra en Detalles técnicos — los patrons no."},"help-botdee-version-smartview-tabs":{"title":"Pestañas de Version SMARTview","body":"Resumen describe BOT DEE y abre Detalles técnicos sin salir del chat. Novedades lista solo cambios verificados de BOT DEE y Gemini — no Master Admin, herramientas de beta testers ni otras notas de producto FLOQR. Ayuda repite el comando Ver / Vers / Version. Cambiar de pestaña o expandir conserva el borrador no enviado y el scroll. La tarjeta usa su Site Chrome — no hay un segundo tema."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"En el chat de BOT DEE, diga Open Room SMARTview, Start a group chat, o planee un viaje a Cancun en palabras simples. Luego: Unirse ahora o Fijar un horario. Unirse ahora abre una sesión de amigos Mingl ya y no pone una tarjeta en Search. Fijar un horario es cuando empieza la room BOT DEE — no Shared Itinerary — y activa SMARTnotification de Search para usted y amigos Mingl invitados. Invite solo amigos Mingl — anfitrión más 7 invitados. Los invitados también pueden invitar. Unirse no es un pago y no abre una cuenta compartida. BOT DEE nunca toma números de tarjeta. Los mensajes privados de BOT DEE siguen privados. Site Chrome sigue Appearance. Una room en vivo sigue abierta hasta End Room, unas cuatro horas después de abrir, o si todos se han ido unos 15 minutos. Pausar el chat privado de BOT DEE es aparte."},"help-botdee-room-smartview-invite":{"title":"Invitar amigos Mingl","body":"Tras Confirm, Invite muestra solo tus amigos Mingl. Cada invitación está ligada a ese amigo y llega a Inbox como Review BOT DEE invite. No es un enlace público. Cupo: anfitrión más 7. Los invitados pueden invitar más amigos Mingl salvo que el anfitrión lo desactive. Unirse no es un pago. Si un chip eres tú o alguien ya en la sesión, queda marcado Eres tú o Ya en esta sesión y no envía otra invitación."},"help-botdee-room-smartview-join":{"title":"Unirse a una sesión BOT DEE","body":"Abre la invitación de Inbox iniciado sesión como el amigo Mingl destinatario. Cuenta incorrecta, caducada o revocada se niega. Unirse a la room no es unirse a una cuenta ni aprobar un pago. BOT DEE nunca toma números de tarjeta."},"help-botdee-room-smartview-end":{"title":"Terminar Room SMARTview","body":"Solo el anfitrión puede terminar una room. Terminar no cobra a nadie ni borra chats privados de otros. Una cuenta compartida impagada debe pagarse o anularse primero. Una room en vivo sigue abierta hasta End Room, unas cuatro horas después de abrir, o si todos se han ido unos 15 minutos. Pausar el chat privado de BOT DEE no es salir de la room. Un invitado que se va no termina la room mientras el anfitrión sigue."},"help-botdee-room-smartview-tab":{"title":"Cuenta compartida Room SMARTview","body":"Primero el opt-in. Luego añade una línea. Cierra con un pagador o dividido. Solo se cobra a los uid que confirman, vía FloqR Stripe. Unirse a la room no es unirse a la cuenta. BOT DEE nunca toma números de tarjeta. Club POS más adelante."},"help-botdee-room-smartview-who-pays":{"title":"Quién paga","body":"Pregunta Who’s paying en Room SMARTview para ver el opt-in. Nadie se cobra porque alguien dijo buy. Los últimos cuatro de la tarjeta quedan en el recibo del pagador."},"help-botdee-room-smartview-kick":{"title":"Quitar a alguien de Room SMARTview","body":"Solo el anfitrión puede quitar a un invitado. Un amigo expulsado no lee más mensajes de la room. Una respuesta del modelo no puede expulsar a nadie."},"help-botdee-room-smartview-share":{"title":"Compartir en Room SMARTview","body":"Share this conversation nunca copia tu hilo privado de BOT DEE. BOT DEE muestra una vista previa de hechos compartibles de este mensaje, marcados como provisionales. Puedes editar o quitar hechos. Perfiles y SMARTsummary quedan fuera de la room."},"help-botdee-room-smartview-schedule":{"title":"Unirse ahora o fijar un horario","body":"Tras configurar Room SMARTview, elija Unirse ahora o Fijar un horario. Unirse ahora abre la sesión BOT DEE ya y no pone una tarjeta en Search. Fijar un horario es cuando empieza la room BOT DEE — no Shared Itinerary. Una hora futura activa SMARTnotification de Search solo para usted y amigos Mingl invitados. Los invitados confirman RSVP hasta que la room esté en vivo; entonces Join Now abre BOT DEE (no Mingl chat)."},"help-botdee-room-collab":{"title":"Compartir una reserva headless en Room SMARTview","body":"En una Room SMARTview, las elecciones VIP reserV o ShoutOut del anfitrión aparecen para todos. Los miembros votan Sí o No. Hold it y el pago quedan con el anfitrión — unirse y votar no es un pago. BOT DEE nunca toma números de tarjeta. Stripe se abre en un pop-out."},"help-botdee-room-elect-host":{"title":"Elegir un anfitrión de Room SMARTview","body":"Cualquiera en la sesión puede ser anfitrión. Nómate a ti o a otro miembro. Un candidato se convierte en anfitrión con el 60 % de los miembros actuales (redondeo hacia arriba). Si el anfitrión se va, el resto elige uno nuevo — la room sigue abierta. Kick y End quedan con el anfitrión elegido."},"help-botdee-smartview-review":{"title":"Revisar y corregir un SMARTsummary","body":"Gemini redacta solo con campos públicos en FLOQR — no en cada vista. Si un dato es falso, oculte el campo o edite el resumen. Su texto no se sobrescribe. Un conflicto de perfil pide revisión. Informe una tarjeta incorrecta desde la superposición."},"help-botdee-smartview-chrome":{"title":"SMARTview y Site Chrome","body":"People SMARTview usa el Site Chrome FLOQR del visitante (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). No hay un segundo tema. Cambiar el chrome actualiza la tarjeta sin perder el borrador."},"help-botdee-smartview-categories":{"title":"Categorías SMARTview","body":"Cuatro pestañas: Social, Citas, Gastronomía y Viajes futuros. Social abre en Música, luego Nightlife, Deportes y Eventos. Las etiquetas son solo lo compartido — sin títulos duplicados ni viajes o notas inventados. Viajes futuros solo destinos públicos."},"help-botdee-smartview-media":{"title":"Fotos y vídeos SMARTview","body":"La tarjeta compacta usa el mismo hero que tu perfil público FLOQR — el primer elemento de Profile Media (8 fotos + 2 vídeos). Toque para Fotos y Vídeos de esos huecos públicos. Deslice o flechas, luego X (o Escape) vuelve al chat y al borrador."},"help-botdee-smartview-privacy":{"title":"Privacidad de SMARTview","body":"SMARTview muestra solo campos ya públicos en FLOQR. No es búsqueda web. Citas solo con opt-in. Oculte un campo en Mi perfil y sale de SMARTview. Quien esté bloqueado no ve la tarjeta. Informe un resumen incorrecto desde la superposición."},"help-botdee-smartview-translation":{"title":"Traducción de SMARTview","body":"Su SMARTsummary se guarda en el idioma predeterminado del perfil — ese es el origen, aunque no sea inglés. Tras guardar, FLOQR encola una traducción a cada otro idioma, incluido el inglés. Un visitante en inglés ve el SMARTsummary en inglés cuando termina ese trabajo. Si está pendiente o falla, se muestra el idioma de origen etiquetado — nunca una traducción antigua como actual."},"help-botdee-smartview-edit":{"title":"Editar su SMARTsummary","body":"Solo usted edita su SMARTsummary en el idioma predeterminado del perfil. El guardado es inmediato. Las traducciones van en segundo plano. Gemini no sobrescribe su texto. Si el perfil público cambia, FLOQR le pide revisar, no reemplazar."},"help-botdee-privacy-assistant":{"title":"Asistente de privacidad BOT DEE","body":"Cambie lo que otros usuarios FLOQR ven en la visibilidad de Mi perfil — BOT DEE no añade un segundo interruptor público. Si la investigación web asoció a la persona equivocada, puede disputarlo sin cambiar su perfil. BOT DEE no promete que un sitio tercero borre la página original."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Cada recomendación puede mostrar evidencias, fecha de comprobación, si hubo personalización y si un espacio es patrocinado. Puede pedir a BOT DEE que no personalice esta búsqueda."},"help-botdee-research-library":{"title":"Biblioteca de investigación BOT DEE","body":"Guarde lugares y tarjetas que pidió a BOT DEE. Un Place ID de Google no copia fotos ni reseñas. Puede actualizar o borrar. Las cachés con licencia siguen apagadas hasta aprobar al proveedor."},"help-botdee-smartview":{"title":"Ver mi SMARTview","body":"Ver mi SMARTview muestra tu tarjeta de persona con campos públicos de FLOQR, con los mismos Profile Media que tu página pública — no maquetas de club o restaurante. Editar mi SMART Summary cambia el resumen en el idioma del perfil. Las maquetas de club/restaurante están en Master Admin → Features → BOT DEE → SMARTviews. No hay Places ni Yelp en vivo."},"help-botdee-memory":{"title":"Chats BOT DEE guardados","body":"Abra Funciones y pedidos → Mi BOT DEE para guardar chats tras la pausa, exportar o borrar historial. La pausa de cinco minutos termina la sesión en vivo. Si acepta, BOT DEE guarda el chat. Los invitados no se guardan. Mingl se queda en Mingl."},"help-botdee-knows-of-me":{"title":"Lo que BOT DEE sabe de mí","body":"Los hechos guardados con su consentimiento están en Funciones y pedidos → Mi BOT DEE. La lista está vacía si la memoria está apagada o no hay datos. Exporte o borre aquí. BOT DEE nunca guarda su dirección IP. Mingl no se copia."},"help-search-settings-appearance":{"title":"Settings en Search","body":"En la pantalla Search, toca Settings para abrir Profile & Settings en la pestaña Appearance — ahí está Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). La ficha Settings usa el mismo pack de iconos chrome que las demás marcas de Search."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"FloqR Inbox guarda System Messages y mensajes internos de soporte. La lista carga primero para que tus mensajes aparezcan rápido. Pulsa el botón flotante New Message para redactar — escribe un nombre o @username para encontrar un destinatario permitido (Club Admin, CSR o personal aprobado). El chat patron-a-patron sigue en Mingl tras Mingl mutuo. Abrir una invitación de turno no confirma — revisa y Approve selected en Work Calendar."},"help-become-dj":{"title":"Conviértete en un DJ","body":"Elija DJ como su función de servicio y asóciese con clubes."},"help-become-promoter":{"title":"Conviértete en un Promoter","body":"Solicite acceso Promoter para listas de invitados y campañas."},"help-template-tags":{"title":"Etiquetas de plantillas","body":"Añade palabras que los clientes podrían escribir al buscar una plantilla en tu local, como noche de partido o cumpleaños. Los Gestores de plantillas pueden añadir etiquetas. Los Administradores de plantillas y los Club Admins también pueden quitarlas. El Club Admin asigna estos roles en Role Activity & Permission."},"help-vip-door-pass":{"title":"Pase de puerta VIP reserV","body":"Tras confirmar el depósito, Mi perfil → Reservas → Mostrar pase para un QR de un solo uso. Trae ID 21+. El personal usa VIP reserV Door."},"help-vip-door-ops":{"title":"Check-in en puerta VIP reserV","body":"Los VIP Managers abren VIP reserV Door para esta noche. Escanea o pega el token, confirma ID 21+, check-in. No-show solo tras gracia. Un enlace notify no cambia el estado."}},"it":{"help-smartvisuals-notification":{"title":"SMARTnotification Mingl Room","body":"Un invito compatto Mingl Room può comparire su Search quando un amico Mingl ha programmato una room BOT DEE a cui sei invitato. Vedi invito apre Room SMARTview. Join Now va a BOT DEE, non Mingl chat. Non ora nasconde la scheda in questa scheda; Inbox tiene Review BOT DEE invite. La query demo Cancun è solo Studio. L’arte è illustrazione, non foto. Le room Join Now senza orario non appaiono su Search."},"help-smartvisuals-room":{"title":"Room SMARTview con SMARTvisuals","body":"Room SMARTview mostra l’invito Mingl: orario, RSVP o stato live, e Join Now. Join Now su Search apre BOT DEE (non Mingl chat) con room= e t=. SMARTstencils e SMARTbackgrounds seguono il titolo autorizzato — Cancun Trip usa arte di viaggio, non una foto reale di Cancun. La chat BOT DEE privata non sceglie mai l’arte. Un Ad etichettato sotto è un campione da quei tag. Vuoto per chat privata o iniezione; non è un inserzionista live."},"help-scheduling-schedule-for":{"title":"Pianificazione del personale","body":"Pianifica turni e ingaggi, poi avvisa ogni persona tramite Inbox, Email, SMS o WhatsApp. In «Turni per» scegli il calendario su cui lavori: «Il mio calendario DJ» è il tuo calendario, «Club» elenca i club che gestisci e «Società di promozione» le società per cui fai promozione. Ogni calendario ha il proprio abbonamento da 20 $/mese. I turni assegnati a te compaiono in «I miei incarichi», dove li confermi o li rifiuti."},"help-staff-marketing-consent":{"title":"Consenso marketing del personale","body":"Quando entri nel team di un locale o di un evento, devi selezionare la casella del consenso marketing. Consente a quel locale o organizzatore, e ai suoi amministratori e manager, di usare il tuo nome FLOQR, il tuo ruolo e le tue foto e i tuoi video pubblicati su siti web, volantini e social media (Instagram, Facebook, TikTok, YouTube e simili) senza chiederti di nuovo il permesso per ogni utilizzo. Non possono pubblicare il tuo numero di telefono né la tua email. Puoi revocarlo in qualsiasi momento in Il mio profilo, scheda Servizi e membri del servizio. La revoca interrompe il nuovo marketing; i materiali già stampati o pubblicati non devono essere ritirati. I Club Admin vedono lo stato del consenso di ogni membro del personale in Rete di dipendenti e personale e in Personale in evidenza."},"help-botdee-privacy-session":{"title":"Privacy e sessione BOT DEE","body":"La pausa di cinque minuti termina la sessione dal vivo. Non cancella questa chat da connesso, i ricordi o i flussi. Restano anche le copie in Il mio profilo → Funzioni e ordini → My BOT DEE. Gli ospiti restano effimeri. Le chat Mingl non vengono mai copiate qui. Invio invia; Maiusc+Invio inizia una nuova riga. Nome e tono sono in Il mio profilo → My BOT DEE, non un pulsante in chat."},"help-botdee-place-search":{"title":"Chiedere a BOT DEE i locali FLOQR","body":"Chiedi in parole semplici — ristoranti di sushi a Washington DC, club a DC o un club per nome. BOT DEE cerca solo venue FLOQR onboardate, non Google o Yelp. I risultati aprono una Place SMARTview compatta (nome, breve testo, valutazioni, link alla pagina pubblica) con SMARTbackground — non un pozzo foto. Foto dei patron e pitch ShoutOut / VIP restano fuori se non li hai chiesti. Se non c’è ancora nulla, BOT DEE lo dice."},"help-botdee-page":{"title":"BOT DEE","body":"Chatta con BOT DEE nella pagina BOT DEE con parole semplici: eventi e club, ShoutOut, Mingl, RydR, BartR, FloqCAST, il tuo profilo, gli orari del personale o gli strumenti Club Admin. Premi Invio per inviare; Maiusc+Invio inizia una nuova riga. BOT DEE chiacchiera come una persona (prova How are you?) e cerca solo quando chiedi come fare qualcosa in FLOQR. Se hai effettuato l’accesso, BOT DEE conserva questa chat se aggiorni o apri un altro telefono, e dopo la pausa può riprendere la cronologia salvata. La pausa non cancella la chat. Le risposte usano la classificazione del tuo account. Se hai effettuato l’accesso, BOT DEE vede gli stessi datapoint pubblici volontari che vedi tu (musica, cibo, viaggi, hobby e il resto di Privacy datapoint sharing) — mai email, telefono, dati della carta o GPS. Tocca Impostazioni sotto la casella di chat per chat e memorie salvate. Tocca una foto in chat per aprirla in una finestra. Chiudi con X o Chiudi per tornare alla chat. Il + in alto a destra apre le chat salvate e non le elimina."},"help-botdee-smartview-troubleshoot":{"title":"Risoluzione problemi SMARTview","body":"Scheda vuota: campi nascosti o blocco. Salvataggio fallito: accedi — le traduzioni stanno sul server. In attesa o errore: lingua di origine etichettata. Solo il titolare modifica. SMARTviews Master Admin resta il catalogo mock; Places e Yelp restano off. Il tema segue Site Chrome."},"help-botdee-smartcard-sync":{"title":"SMARTsummary resta sincronizzato","body":"Modifica lo SMARTsummary nella lingua predefinita del profilo. Il salvataggio è immediato. Schede e SMARTview aperti si aggiornano dallo stesso record. Le traduzioni partono in background e non sovrascrivono una modifica più recente. Se nascondi il profilo, blocchi qualcuno o elimini l’account, le schede scompaiono. Gemini non sovrascrive il tuo testo."},"help-botdee-smartcard-search":{"title":"Chiedere a BOT DEE chi è qualcuno","body":"“Who am I?” apre il tuo SMARTview. “Who is …”, “What do you know of …” o “What about …” più nome, cognome, nome visualizzato, handle Mingl o FloqR, o un handle social (Instagram, TikTok, X). Solo quei campi di identità — non bio, like, drink o generi. Un risultato apre una scheda People SMARTview in chat — non un elenco markdown né una griglia di foto. Più risultati mostrano SMARTcard compatte. Profili privati, bloccati o non pubblicati non compaiono — BOT DEE non conferma se l’account esiste."},"help-botdee-smartcard":{"title":"SMARTcard persone","body":"Se più profili pubblici FLOQR corrispondono, BOT DEE mostra SMARTcard compatte in chat: prima la foto a tutta larghezza, poi nome e handle, poi un SMARTsummary compatto senza riquadro imbottito. Tocca una scheda per aprire lo SMARTview completo — stesso impilamento. Le schede usano lo stesso profilo pubblico e SMARTsummary. Aprire una scheda non chiama Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Digita Ver, Vers o Version — le maiuscole non contano. BOT DEE mostra la scheda della versione. Una domanda più lunga come “qual è la tua versione?” mostra comunque quella scheda."},"help-botdee-version-smartview-status":{"title":"Lo stato Version SMARTview è una sonda live","body":"Lo stato del servizio è sondato su questa richiesta Version: Functions e package raggiungibili con Gemini configurato → Operativo; Functions e package ok ma Gemini non configurato → Degradato; Functions assenti da questa richiesta → Non disponibile. Mai un’etichetta statica Non verificato. Il modello IA mostra l’id Gemini configurato di questo deployment anche se questo turno non ha generato. I timbri frontend e backend possono differire; entrambi sono etichettati. Master Admin può vedere diagnostica extra in Dettagli tecnici — i patron no."},"help-botdee-version-smartview-tabs":{"title":"Schede Version SMARTview","body":"Panoramica descrive BOT DEE e apre Dettagli tecnici senza uscire dalla chat. Novità elenca solo i cambiamenti verificati di BOT DEE e Gemini — non Master Admin, strumenti beta tester o altre note di prodotto FLOQR. Aiuto ripete il comando Ver / Vers / Version. Cambiare scheda o espandere tiene la bozza non inviata e lo scorrimento. La scheda usa il tuo Site Chrome — non c’è un secondo tema."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"Nella chat BOT DEE di’ Open Room SMARTview, Start a group chat, o pianifica un viaggio a Cancun in parole semplici. Poi: Entra ora o Imposta un orario. Entra ora apre una sessione di amici Mingl subito e non mette una scheda su Search. Imposta un orario è quando inizia la room BOT DEE — non Shared Itinerary — e attiva SMARTnotification di Search per te e gli amici Mingl invitati. Invita solo amici Mingl — host più 7 ospiti. Anche gli ospiti possono invitare. Unirsi non è un pagamento e non apre un conto condiviso. BOT DEE non prende mai numeri di carta. I messaggi BOT DEE privati restano privati. Site Chrome segue Appearance. Una room live resta aperta fino a End Room, circa quattro ore dopo l’apertura, o se tutti sono assenti da circa 15 minuti. La pausa della chat BOT DEE privata è distinta."},"help-botdee-room-smartview-invite":{"title":"Invita amici Mingl","body":"Dopo Confirm, Invite mostra solo i tuoi amici Mingl. Ogni invito è legato a quell’amico e arriva in Inbox come Review BOT DEE invite. Non è un link pubblico. Capienza: host più 7. Gli ospiti possono invitare altri amici Mingl finché l’host non lo disattiva. Entrare non è un pagamento. Se un chip sei tu o qualcuno già in sessione, resta Sei tu o Già in questa sessione e non invia un secondo invito."},"help-botdee-room-smartview-join":{"title":"Unisciti a una sessione BOT DEE","body":"Apri l’invito Inbox autenticato come l’amico Mingl destinatario. Account sbagliato, scaduto o revocato rifiuta. Entrare nella room non è entrare in un conto e non approva un pagamento. BOT DEE non prende mai numeri di carta."},"help-botdee-room-smartview-end":{"title":"Termina Room SMARTview","body":"Solo l’host può terminare una room. Terminare non addebita nessuno e non cancella le chat private altrui. Un conto condiviso non pagato va prima pagato o annullato. Una room live resta aperta fino a End Room, circa quattro ore dopo l’apertura, o se tutti sono assenti da circa 15 minuti. La pausa della chat BOT DEE privata non è un logout della room. Un ospite che esce non termina la room se l’host è presente."},"help-botdee-room-smartview-tab":{"title":"Conto condiviso Room SMARTview","body":"Prima l’opt-in. Poi aggiungi una riga. Chiudi con un pagatore o diviso. Solo gli uid che confermano vengono addebitati via FloqR Stripe. Entrare nella room non è entrare nel conto. BOT DEE non prende mai numeri di carta. Club POS più avanti."},"help-botdee-room-smartview-who-pays":{"title":"Chi paga","body":"Chiedi Who’s paying in Room SMARTview per vedere l’opt-in. Nessuno viene addebitato perché qualcuno ha detto buy. Le ultime quattro della carta restano sulla ricevuta del pagatore."},"help-botdee-room-smartview-kick":{"title":"Rimuovi qualcuno da Room SMARTview","body":"Solo l’host può rimuovere un ospite. Un amico rimosso non legge altri messaggi della room. Una risposta del modello non può espellere nessuno."},"help-botdee-room-smartview-share":{"title":"Condividi in Room SMARTview","body":"Share this conversation non copia mai il tuo thread BOT DEE privato. BOT DEE mostra un’anteprima di fatti condivisibili da questo messaggio, contrassegnati come provvisori. Puoi modificare o togliere fatti. Profili e SMARTsummary restano fuori dalla room."},"help-botdee-room-smartview-schedule":{"title":"Entra ora o imposta un orario","body":"Dopo il setup Room SMARTview, scegli Entra ora o Imposta un orario. Entra ora apre la sessione BOT DEE subito e non mette una scheda su Search. Imposta un orario è quando inizia la room BOT DEE — non Shared Itinerary. Un orario futuro attiva SMARTnotification di Search solo per te e gli amici Mingl invitati. Gli ospiti RSVP finché la room è live; poi Join Now apre BOT DEE (non Mingl chat)."},"help-botdee-room-collab":{"title":"Condividere una prenotazione headless in Room SMARTview","body":"In una Room SMARTview le scelte VIP reserV o ShoutOut dell’host appaiono a tutti. I membri votano Sì o No. Hold it e il pagamento restano all’host — unirsi e votare non è un pagamento. BOT DEE non prende mai numeri di carta. Stripe si apre in un pop-out."},"help-botdee-room-elect-host":{"title":"Eleggere un host Room SMARTview","body":"Chiunque nella sessione può essere host. Candidati te stesso o un altro membro. Un candidato diventa host al 60% dei membri attualmente presenti (arrotondato per eccesso). Se l’host esce, gli altri eleggono un nuovo host — la room resta aperta. Kick e End restano all’host eletto."},"help-botdee-smartview-review":{"title":"Rivedi e correggi lo SMARTsummary","body":"Gemini bozza solo dai campi pubblici in FLOQR — non a ogni vista. Se un fatto è sbagliato, nascondi il campo o modifica il riassunto. Il tuo testo non viene sovrascritto. Un conflitto di profilo chiede revisione. Segnala una scheda errata dall’overlay."},"help-botdee-smartview-chrome":{"title":"SMARTview e Site Chrome","body":"People SMARTview usa il Site Chrome FLOQR di chi guarda (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Nessun secondo tema. Cambiare chrome aggiorna la scheda senza perdere la bozza chat."},"help-botdee-smartview-categories":{"title":"Categorie SMARTview","body":"Quattro schede: Social, Dating, Dining, Viaggi futuri. Social si apre su Musica, poi Nightlife, Sport, Eventi. I tag sono solo ciò che hai condiviso — niente titoli duplicati né viaggi o voti inventati. I viaggi futuri mostrano solo destinazioni pubbliche."},"help-botdee-smartview-media":{"title":"Foto e video SMARTview","body":"La scheda compatta usa lo stesso hero della pagina pubblica FLOQR — il primo elemento Profile Media (8 foto + 2 video). Tocca per Foto e Video da quegli slot pubblici. Scorri o frecce, poi X (o Escape) torna allo stesso chat e bozza."},"help-botdee-smartview-privacy":{"title":"Privacy SMARTview","body":"SMARTview mostra solo campi già pubblici in FLOQR. Non è ricerca web. Dating solo con opt-in. Nascondi un campo in Il mio profilo e sparisce. Chi è bloccato non vede la scheda. Segnala un riassunto errato dall’overlay."},"help-botdee-smartview-translation":{"title":"Traduzione SMARTview","body":"Il tuo SMARTsummary è salvato nella lingua predefinita del profilo — quella è la fonte, anche se non è l’inglese. Dopo il salvataggio FLOQR mette in coda una traduzione per ogni altra lingua, incluso l’inglese. Un visitatore inglese vede lo SMARTsummary in inglese a lavoro finito. In attesa o errore i visitatori vedono la lingua di origine etichettata — mai una traduzione vecchia come attuale."},"help-botdee-smartview-edit":{"title":"Modifica lo SMARTsummary","body":"Solo tu modifichi lo SMARTsummary nella lingua predefinita del profilo. Il salvataggio è immediato. Le traduzioni partono in background. Gemini non sovrascrive il tuo testo. Se il profilo pubblico cambia, FLOQR chiede una revisione invece di sostituirlo."},"help-botdee-privacy-assistant":{"title":"Privacy Assistant BOT DEE","body":"Cambia in Il mio profilo cosa vedono gli altri utenti FLOQR — BOT DEE non aggiunge un secondo interruttore pubblico. Se la ricerca web ha collegato la persona sbagliata, puoi contestare senza cambiare il profilo. BOT DEE non promette la cancellazione su siti terzi."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Ogni raccomandazione può mostrare prove, data di verifica, personalizzazione e sponsorship. Puoi chiedere a BOT DEE di non personalizzare questa ricerca."},"help-botdee-research-library":{"title":"Research Library BOT DEE","body":"Salva luoghi e schede chieste a BOT DEE. Un Place ID Google non è una copia di foto o recensioni. Puoi aggiornare o eliminare. Le cache con licenza restano off finché il provider non è approvato."},"help-botdee-smartview":{"title":"Vedi il mio SMARTview","body":"Vedi il mio SMARTview mostra la tua scheda Persona dai campi pubblici FLOQR, con gli stessi Profile Media della pagina pubblica — non mock di club o ristoranti. Modifica il mio SMART Summary cambia il riassunto nella lingua del profilo. I mock club/ristorante stanno in Master Admin → Features → BOT DEE → SMARTviews. Niente Places o Yelp live."},"help-botdee-memory":{"title":"Chat BOT DEE salvate","body":"Apri Funzioni e ordini → Il mio BOT DEE per salvare le chat dopo la pausa, esportare o eliminare la cronologia. La pausa di cinque minuti chiude la sessione dal vivo. Con opt-in BOT DEE tiene la chat. Gli ospiti non vengono salvati. Mingl resta in Mingl."},"help-botdee-knows-of-me":{"title":"Cosa BOT DEE sa di me","body":"I fatti salvati con il tuo consenso sono in Funzioni e ordini → Il mio BOT DEE. L’elenco è vuoto se la memoria è spenta o non c’è nulla. Esporta o elimina qui. BOT DEE non memorizza l’IP. Mingl non viene copiato."},"help-search-settings-appearance":{"title":"Settings su Search","body":"Nella schermata Search tocca Settings per aprire Profile & Settings sulla scheda Appearance — lì c’è Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). La tile Settings usa lo stesso pack di icone chrome degli altri marchi Search."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"FloqR Inbox contiene System Messages e messaggi di supporto interni. L’elenco si carica per primo così i messaggi appaiono subito. Tocca il pulsante fluttuante New Message per scrivere — digita un nome o @username per trovare un destinatario consentito (Club Admin, CSR o staff approvato). La chat patron-a-patron resta in Mingl dopo il Mingl reciproco. Aprire un invito di turno non conferma — rivedi e Approve selected su Work Calendar."},"help-become-dj":{"title":"Diventa un DJ","body":"Scegli DJ come tuo ruolo di servizio e associalo ai club."},"help-become-promoter":{"title":"Diventa un Promoter","body":"Richiedi l'accesso Promoter per elenchi di invitati e campagne."},"help-template-tags":{"title":"Tag dei modelli","body":"Aggiungi parole che i clienti potrebbero scrivere cercando un modello nel tuo locale, come serata partita o compleanno. I Gestori dei modelli possono aggiungere tag. Gli Amministratori dei modelli e i Club Admin possono anche rimuoverli. Il Club Admin assegna questi ruoli in Role Activity & Permission."},"help-vip-door-pass":{"title":"Pass porta VIP reserV","body":"Dopo la conferma del deposito, Il mio profilo → Prenotazioni → Mostra pass per un QR monouso. Porta ID 21+. Lo staff usa VIP reserV Door."},"help-vip-door-ops":{"title":"Check-in porta VIP reserV","body":"I VIP Manager aprono VIP reserV Door per stasera. Scansiona o incolla il token, conferma ID 21+, check-in. No-show solo dopo grace. Un link notify non cambia lo stato."}},"pt":{"help-smartvisuals-notification":{"title":"SMARTnotification Mingl Room","body":"Um convite compacto Mingl Room pode aparecer na Search quando um amigo Mingl agendou uma room BOT DEE para a qual foi convidado. Ver convite abre Room SMARTview. Join Now vai para BOT DEE, não Mingl chat. Agora não esconde o cartão neste separador; Inbox mantém Review BOT DEE invite. A consulta demo Cancun é só Studio. A arte é ilustração, não foto. Rooms Join Now sem horário não aparecem na Search."},"help-smartvisuals-room":{"title":"Room SMARTview com SMARTvisuals","body":"Room SMARTview mostra o convite Mingl: horário, RSVP ou estado ao vivo, e Join Now. Join Now na Search abre BOT DEE (não Mingl chat) com room= e t=. SMARTstencils e SMARTbackgrounds seguem o título autorizado — Cancun Trip usa arte de viagem, não uma foto real de Cancun. O chat privado BOT DEE nunca escolhe a arte. Um Ad rotulado abaixo é uma amostra dessas etiquetas. Vazio para chat privado ou injeção; não é um anunciante ao vivo."},"help-scheduling-schedule-for":{"title":"Agendamento de pessoal","body":"Planeje turnos e contratações e avise cada pessoa por Inbox, Email, SMS ou WhatsApp. Em «Escala de», escolha em qual agenda você está trabalhando: «Minha agenda de DJ» é a sua própria agenda, «Clube» lista os clubes que você administra e «Empresa de promoção» as empresas para as quais você promove. Cada agenda tem sua própria assinatura de US$ 20/mês. Os turnos enviados para você aparecem em «Minhas atribuições», onde você os confirma ou recusa."},"help-staff-marketing-consent":{"title":"Consentimento de marketing da equipe","body":"Quando você entra na equipe de uma casa ou evento, precisa marcar a caixa de consentimento de marketing. Ela permite que essa casa ou organizador, e seus administradores e gerentes, usem seu nome no FLOQR, sua função e suas fotos e vídeos publicados em sites, flyers e redes sociais (Instagram, Facebook, TikTok, YouTube e similares) sem pedir sua permissão novamente a cada uso. Eles não podem publicar seu telefone nem seu e-mail. Você pode retirar o consentimento a qualquer momento em Meu perfil, aba Serviços e membros do serviço. Isso interrompe novo marketing; materiais já impressos ou publicados não precisam ser recolhidos. Os Club Admins veem o status de consentimento de cada pessoa da equipe em Rede de funcionários e equipe e em Equipe em destaque."},"help-botdee-privacy-session":{"title":"Privacidade e sessão BOT DEE","body":"A pausa de cinco minutos termina a sessão ao vivo. Não apaga este chat com sessão iniciada, memórias ou fluxos. As cópias em O meu perfil → Funções e encomendas → My BOT DEE também ficam. Os convidados continuam efémeros. Os chats Mingl nunca são copiados para aqui. Enter envia; Shift+Enter começa uma nova linha. Nome e tom estão em O meu perfil → My BOT DEE, não num botão no chat."},"help-botdee-place-search":{"title":"Perguntar ao BOT DEE por locais FLOQR","body":"Pergunte em palavras simples — restaurantes de sushi em Washington DC, clubs em DC ou um clube pelo nome. O BOT DEE pesquisa só venues FLOQR onboardadas, não Google nem Yelp. As correspondências abrem um Place SMARTview compacto (nome, texto curto, classificações, ligação à página pública) com SMARTbackground — não um poço de foto. Fotos de patrons e pitches de ShoutOut / VIP ficam de fora salvo se pedir. Se ainda não houver listing, o BOT DEE diz."},"help-botdee-page":{"title":"BOT DEE","body":"Converse com o BOT DEE na página BOT DEE em palavras simples: eventos e clubes, ShoutOut, Mingl, RydR, BartR, FloqCAST, seu perfil, escalas da equipe ou ferramentas de Club Admin. Pressione Enter para enviar; Shift+Enter começa uma nova linha. O BOT DEE conversa como uma pessoa (experimente How are you?) e só pesquisa quando você pergunta como fazer algo no FLOQR. Se você estiver conectado, o BOT DEE guarda este chat se você atualizar ou abrir outro telefone, e depois da pausa pode continuar o histórico guardado. A pausa não apaga o chat. As respostas usam a classificação da sua conta. Se estiver conectado, o BOT DEE vê os mesmos datapoints públicos voluntários que você (música, comida, viagem, hobbies e o restante de Privacy datapoint sharing) — nunca e-mail, telefone, dados de cartão ou GPS. Toque em Definições abaixo da caixa de chat para chats e memórias guardados. Toque numa foto do chat para abri-la numa janela. Feche com X ou Fechar para voltar ao chat. O + no canto superior direito abre chats guardados e não os apaga."},"help-botdee-smartview-troubleshoot":{"title":"Resolução de problemas SMARTview","body":"Cartão vazio: campos ocultos ou bloqueio. Falha ao guardar: inicie sessão — as traduções ficam no servidor. Pendente ou falha: idioma de origem com etiqueta. Só o dono edita. SMARTviews Master Admin continua o catálogo mock; Places e Yelp desligados. O tema segue o Site Chrome."},"help-botdee-smartcard-sync":{"title":"O SMARTsummary fica sincronizado","body":"Edite o SMARTsummary no idioma predefinido do perfil. A gravação é imediata. Cards e SMARTview abertos atualizam a partir do mesmo registo. As traduções correm em segundo plano e não substituem uma edição mais nova. Se ocultar o perfil, bloquear alguém ou apagar a conta, essas cards desaparecem. O Gemini não substitui o seu texto."},"help-botdee-smartcard-search":{"title":"Perguntar ao BOT DEE quem é alguém","body":"“Who am I?” abre o seu SMARTview. “Who is …”, “What do you know of …” ou “What about …” mais nome, apelido, nome de exibição, handle Mingl ou FloqR, ou um handle social (Instagram, TikTok, X). Só esses campos de identidade — não bios, likes, bebidas ou géneros. Um resultado abre um cartão People SMARTview no chat — não uma lista markdown nem uma grelha de fotos. Vários mostram SMARTcards compactos. Perfis privados, bloqueados ou não publicados não aparecem — o BOT DEE não confirma se essa conta existe."},"help-botdee-smartcard":{"title":"SMARTcards de pessoas","body":"Quando mais de um perfil público FLOQR corresponde, o BOT DEE mostra SMARTcards compactas no chat: foto em largura total primeiro, depois nome e handle, depois um SMARTsummary compacto sem caixa preenchida. Toque para abrir o SMARTview completo — o mesmo empilhamento. As cards usam o mesmo perfil público e SMARTsummary. Abrir não chama o Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Digite Ver, Vers ou Version — maiúsculas não importam. BOT DEE mostra o cartão de versão. Uma pergunta mais longa como “qual é a sua versão?” também mostra esse cartão."},"help-botdee-version-smartview-status":{"title":"O estado do Version SMARTview é uma sonda ao vivo","body":"O estado do serviço é sondado neste pedido Version: Functions e pacote alcançáveis com Gemini configurado → Operacional; Functions e pacote ok mas Gemini não configurado → Degradado; Functions fora deste pedido → Indisponível. Nunca um rótulo estático Não verificado. O modelo de IA mostra o id Gemini configurado deste deployment mesmo quando esta vez não gerou. Os carimbos de frontend e backend podem diferir; ambos são rotulados. Master Admin pode ver diagnósticos extra em Detalhes técnicos — patrons não."},"help-botdee-version-smartview-tabs":{"title":"Abas do Version SMARTview","body":"Visão geral descreve o BOT DEE e abre Detalhes técnicos sem sair do chat. Novidades lista só mudanças verificadas de BOT DEE e Gemini — não Master Admin, ferramentas de beta tester nem outras notas de produto FLOQR. Ajuda repete o comando Ver / Vers / Version. Trocar de aba ou expandir mantém o rascunho não enviado e a rolagem. O cartão usa o seu Site Chrome — não há um segundo tema."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"No chat BOT DEE, diga Open Room SMARTview, Start a group chat, ou planeie uma viagem a Cancun em palavras simples. Depois: Entrar agora ou Definir um horário. Entrar agora abre uma sessão de amigos Mingl já e não põe um cartão na Search. Definir um horário é quando a room BOT DEE começa — não Shared Itinerary — e liga SMARTnotification da Search para si e amigos Mingl convidados. Convide só amigos Mingl — anfitrião mais 7 convidados. Convidados também podem convidar. Entrar não é um pagamento e não abre uma conta partilhada. O BOT DEE nunca pede números de cartão. As mensagens privadas do BOT DEE ficam privadas. Site Chrome segue Appearance. Uma room ao vivo fica aberta até End Room, cerca de quatro horas depois de abrir, ou se todos saíram há cerca de 15 minutos. Pausar o chat privado BOT DEE é separado."},"help-botdee-room-smartview-invite":{"title":"Convidar amigos Mingl","body":"Depois de Confirm, Invite mostra só os seus amigos Mingl. Cada convite fica ligado a esse amigo e chega ao Inbox como Review BOT DEE invite. Não é um link público. Limite: anfitrião mais 7. Convidados podem convidar mais amigos Mingl até o anfitrião desligar isso. Entrar não é pagamento. Se um chip é você ou alguém já na sessão, fica É você ou Já nesta sessão e não envia outro convite."},"help-botdee-room-smartview-join":{"title":"Entrar numa sessão BOT DEE","body":"Abra o convite do Inbox autenticado como o amigo Mingl destinatário. Conta errada, expirado ou revogado recusa. Entrar na room não é entrar numa conta nem aprovar um pagamento. BOT DEE nunca pega números de cartão."},"help-botdee-room-smartview-end":{"title":"Terminar Room SMARTview","body":"Só o anfitrião pode terminar uma room. Terminar não cobra ninguém nem apaga chats privados de outros. Uma conta partilhada por pagar deve ser paga ou anulada primeiro. Uma room ao vivo fica aberta até End Room, cerca de quatro horas depois de abrir, ou se todos saíram há cerca de 15 minutos. Pausar o chat privado BOT DEE não é logout da room. Um convidado que sai não termina a room enquanto o anfitrião está presente."},"help-botdee-room-smartview-tab":{"title":"Conta partilhada Room SMARTview","body":"Primeiro o opt-in. Depois adicione uma linha. Feche com um pagador ou dividido. Só uid que confirmam são cobrados via FloqR Stripe. Entrar na room não é entrar na conta. BOT DEE nunca pega números de cartão. Club POS mais tarde."},"help-botdee-room-smartview-who-pays":{"title":"Quem paga","body":"Pergunte Who’s paying em Room SMARTview para ver o opt-in. Ninguém é cobrado porque alguém disse buy. Os últimos quatro do cartão ficam no recibo do pagador."},"help-botdee-room-smartview-kick":{"title":"Remover alguém de Room SMARTview","body":"Só o anfitrião pode remover um convidado. Um amigo removido não lê mais mensagens da room. Uma resposta do modelo não pode expulsar ninguém."},"help-botdee-room-smartview-share":{"title":"Partilhar em Room SMARTview","body":"Share this conversation nunca copia o seu tópico privado BOT DEE. BOT DEE mostra uma pré-visualização de factos partilháveis desta mensagem, marcados como provisórios. Pode editar ou retirar factos. Perfis e SMARTsummary ficam fora da room."},"help-botdee-room-smartview-schedule":{"title":"Entrar agora ou definir um horário","body":"Depois da configuração Room SMARTview, escolha Entrar agora ou Definir um horário. Entrar agora abre a sessão BOT DEE já e não põe um cartão na Search. Definir um horário é quando a room BOT DEE começa — não Shared Itinerary. Uma hora futura liga SMARTnotification da Search só para si e amigos Mingl convidados. Convidados RSVP até a room estar ao vivo; depois Join Now abre BOT DEE (não Mingl chat)."},"help-botdee-room-collab":{"title":"Partilhar uma reserva headless no Room SMARTview","body":"Num Room SMARTview, as escolhas VIP reserV ou ShoutOut do anfitrião aparecem para todos. Os membros votam Sim ou Não. Hold it e o pagamento ficam com o anfitrião — juntar-se e votar não é um pagamento. BOT DEE nunca pede números de cartão. O Stripe abre num pop-out."},"help-botdee-room-elect-host":{"title":"Eleger um anfitrião do Room SMARTview","body":"Qualquer pessoa na sessão pode ser anfitrião. Nomeie-se a si ou a outro membro. Um candidato torna-se anfitrião com 60% dos membros atuais (arredondado para cima). Se o anfitrião sair, os restantes elegem um novo — a room fica aberta. Kick e End ficam com o anfitrião eleito."},"help-botdee-smartview-review":{"title":"Rever e corrigir o SMARTsummary","body":"O Gemini redige só a partir de campos públicos no FLOQR — não em cada vista. Se um facto estiver errado, oculte o campo ou edite o resumo. O seu texto não é substituído. Um conflito de perfil pede revisão. Reporte um cartão errado na sobreposição."},"help-botdee-smartview-chrome":{"title":"SMARTview e Site Chrome","body":"O People SMARTview usa o Site Chrome FLOQR de quem vê (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Não há segundo tema. Mudar o chrome atualiza o cartão sem perder o rascunho."},"help-botdee-smartview-categories":{"title":"Categorias SMARTview","body":"Quatro separadores: Social, Dating, Dining e Viagens futuras. Social abre em Música, depois Nightlife, Desporto e Eventos. As etiquetas são só o que partilhou — sem títulos duplicados nem viagens ou notas inventadas. Viagens futuras só destinos públicos."},"help-botdee-smartview-media":{"title":"Fotos e vídeos SMARTview","body":"O cartão compacto usa o mesmo hero da página pública FLOQR — o primeiro item de Profile Media (8 fotos + 2 vídeos). Toque para Fotos e Vídeos desses espaços públicos. Deslize ou setas, depois X (ou Escape) regressa ao mesmo chat e rascunho."},"help-botdee-smartview-privacy":{"title":"Privacidade SMARTview","body":"O SMARTview mostra só campos já públicos no FLOQR. Não é pesquisa web. Dating só com opt-in. Oculte um campo no perfil e sai do SMARTview. Bloqueados não veem o cartão. Reporte um resumo errado na sobreposição."},"help-botdee-smartview-translation":{"title":"Tradução SMARTview","body":"O seu SMARTsummary fica no idioma predefinido do perfil — essa é a origem, mesmo que não seja inglês. Depois de guardar, o FLOQR mete na fila uma tradução para cada outro idioma, incluindo inglês. Um visitante em inglês vê o SMARTsummary em inglês quando o trabalho termina. Pendente ou falhado, vê-se o idioma de origem com etiqueta — nunca uma tradução antiga como atual."},"help-botdee-smartview-edit":{"title":"Editar o SMARTsummary","body":"Só você edita o SMARTsummary no idioma predefinido do perfil. A gravação é imediata. As traduções correm em segundo plano. O Gemini não substitui o seu texto. Se o perfil público mudar, o FLOQR pede revisão em vez de substituir."},"help-botdee-privacy-assistant":{"title":"Assistente de privacidade BOT DEE","body":"Altere em O meu perfil o que outros utilizadores FLOQR veem — o BOT DEE não adiciona um segundo interruptor público. Se a pesquisa web associou a pessoa errada, pode contestar sem alterar o perfil. O BOT DEE não promete que um site terceiro apague a página original."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Cada recomendação pode mostrar evidências, data da verificação, personalização e patrocínio. Pode pedir ao BOT DEE para não personalizar esta pesquisa."},"help-botdee-research-library":{"title":"Biblioteca de pesquisa BOT DEE","body":"Guarde lugares e cartões que pediu ao BOT DEE. Um Place ID do Google não copia fotos ou avaliações. Pode atualizar ou apagar. Caches licenciados ficam desligados até o fornecedor ser aprovado."},"help-botdee-smartview":{"title":"Ver o meu SMARTview","body":"Ver o meu SMARTview mostra o seu cartão de Pessoa a partir dos campos públicos FLOQR, com os mesmos Profile Media da página pública — não mocks de clube ou restaurante. Editar o meu SMART Summary altera o resumo no idioma do perfil. Os mocks de clube/restaurante ficam em Master Admin → Features → BOT DEE → SMARTviews. Sem Places ou Yelp em direto."},"help-botdee-memory":{"title":"Chats BOT DEE guardados","body":"Abra Funcionalidades e encomendas → O meu BOT DEE para guardar chats após a pausa, exportar ou apagar histórico. A pausa de cinco minutos termina a sessão ao vivo. Se aderir, o BOT DEE guarda o chat. Convidados não são guardados. Mingl fica no Mingl."},"help-botdee-knows-of-me":{"title":"O que o BOT DEE sabe de mim","body":"Factos guardados com a sua aprovação estão em Funcionalidades e encomendas → O meu BOT DEE. A lista fica vazia se a memória estiver desligada ou não houver dados. Exporte ou apague aqui. O BOT DEE não guarda IP. Mingl não é copiado."},"help-search-settings-appearance":{"title":"Settings na Search","body":"No ecrã Search, toque em Settings para abrir Profile & Settings no separador Appearance — o Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green) fica aí. O mosaico Settings usa o mesmo pack de ícones chrome das outras marcas Search."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"O FloqR Inbox guarda System Messages e mensagens internas de suporte. A lista carrega primeiro para as mensagens aparecerem depressa. Toque no botão flutuante New Message para escrever — digite um nome ou @username para encontrar um destinatário permitido (Club Admin, CSR ou staff aprovado). O chat patron-a-patron fica no Mingl após Mingl mútuo. Abrir um convite de turno não confirma — reveja e Approve selected no Work Calendar."},"help-become-dj":{"title":"Torne-se um DJ","body":"Eleja DJ como sua função de serviço e associe-se aos clubes."},"help-become-promoter":{"title":"Torne-se um Promoter","body":"Solicite acesso Promoter para listas de convidados e campanhas."},"help-template-tags":{"title":"Tags de modelos","body":"Adicione palavras que os clientes possam digitar ao procurar um modelo no seu local, como noite de jogo ou aniversário. Gestores de modelos podem adicionar tags. Administradores de modelos e Club Admins também podem removê-las. O Club Admin atribui esses papéis em Role Activity & Permission."},"help-vip-door-pass":{"title":"Passe de porta VIP reserV","body":"Após confirmar o depósito, Meu perfil → Reservas → Mostrar passe para um QR de uso único. Traga ID 21+. A equipa usa VIP reserV Door."},"help-vip-door-ops":{"title":"Check-in na porta VIP reserV","body":"VIP Managers abrem VIP reserV Door para esta noite. Digitalize ou cole o token, confirme ID 21+, faça check-in. No-show só após grace. Um link notify não altera o estado."}},"el":{"help-smartvisuals-notification":{"title":"SMARTnotification Mingl Room","body":"Μια συμπαγής πρόσκληση Mingl Room μπορεί να εμφανιστεί στο Search όταν ένας φίλος Mingl προγραμμάτισε BOT DEE room στο οποίο προσκληθήκατε. Προβολή πρόσκλησης ανοίγει Room SMARTview. Το Join Now πηγαίνει στο BOT DEE, όχι Mingl chat. Όχι τώρα κρύβει την κάρτα σε αυτή την καρτέλα· το Inbox κρατά Review BOT DEE invite. Το demo Cancun είναι μόνο Studio. Η τέχνη είναι εικονογράφηση, όχι φωτογραφία. Rooms Join Now χωρίς πρόγραμμα δεν εμφανίζονται στο Search."},"help-smartvisuals-room":{"title":"Room SMARTview με SMARTvisuals","body":"Το Room SMARTview δείχνει την πρόσκληση Mingl: πρόγραμμα, RSVP ή live κατάσταση, και Join Now. Το Join Now στο Search ανοίγει BOT DEE (όχι Mingl chat) με room= και t=. SMARTstencils και SMARTbackgrounds ακολουθούν τον εγκεκριμένο τίτλο — Cancun Trip χρησιμοποιεί ταξιδιωτική εικονογράφηση, όχι πραγματική φωτογραφία Cancun. Η ιδιωτική συνομιλία BOT DEE δεν επιλέγει ποτέ την τέχνη. Ένα επισημασμένο Ad από κάτω είναι δείγμα από αυτές τις ετικέτες. Κενό για ιδιωτική συνομιλία ή έγχυση· δεν είναι ζωντανός διαφημιστής."},"help-scheduling-schedule-for":{"title":"Προγραμματισμός προσωπικού","body":"Σχεδιάστε βάρδιες και κρατήσεις και ειδοποιήστε κάθε άτομο μέσω Inbox, Email, SMS ή WhatsApp. Στο «Πρόγραμμα για» επιλέξτε σε ποιο ημερολόγιο δουλεύετε: «Το πρόγραμμά μου ως DJ» είναι το δικό σας ημερολόγιο, το «Club» δείχνει τα clubs που διαχειρίζεστε και η «Εταιρεία προώθησης» τις εταιρείες για τις οποίες κάνετε προώθηση. Κάθε ημερολόγιο έχει τη δική του συνδρομή 20 $/μήνα. Οι βάρδιες που σας ανατίθενται εμφανίζονται στις «Οι αναθέσεις μου», όπου τις επιβεβαιώνετε ή τις απορρίπτετε."},"help-staff-marketing-consent":{"title":"Συγκατάθεση μάρκετινγκ προσωπικού","body":"Όταν εντάσσεστε στην ομάδα ενός χώρου ή μιας εκδήλωσης, πρέπει να επιλέξετε το πλαίσιο συγκατάθεσης μάρκετινγκ. Επιτρέπει σε αυτόν τον χώρο ή διοργανωτή, και στους διαχειριστές και υπευθύνους του, να χρησιμοποιούν το όνομά σας στο FLOQR, τον ρόλο σας και τις δημοσιευμένες φωτογραφίες και βίντεό σας σε ιστότοπους, φυλλάδια και μέσα κοινωνικής δικτύωσης (Instagram, Facebook, TikTok, YouTube και παρόμοια) χωρίς να σας ρωτούν ξανά για κάθε χρήση. Δεν επιτρέπεται να δημοσιεύουν το τηλέφωνο ή το email σας. Μπορείτε να την ανακαλέσετε ανά πάσα στιγμή στο «Το προφίλ μου», καρτέλα «Μέλη Υπηρεσιών & Υπηρεσιών». Η ανάκληση σταματά το νέο μάρκετινγκ· υλικό που έχει ήδη τυπωθεί ή δημοσιευτεί δεν χρειάζεται να αποσυρθεί. Οι Club Admins βλέπουν την κατάσταση συγκατάθεσης κάθε μέλους του προσωπικού στο Δίκτυο υπαλλήλων και προσωπικού και στο Προβεβλημένο προσωπικό."},"help-botdee-privacy-session":{"title":"Απόρρητο και συνεδρία BOT DEE","body":"Η παύση των πέντε λεπτών τελειώνει τη ζωντανή συνεδρία. Δεν διαγράφει αυτή τη συνομιλία για συνδεδεμένους, τις μνήμες ή τις ροές. Οι προαιρετικές αντιγραφές στο Προφίλ μου → Λειτουργίες και παραγγελίες → My BOT DEE μένουν κι αυτές. Οι επισκέπτες μένουν προσωρινοί. Οι συνομιλίες Mingl δεν αντιγράφονται εδώ. Enter στέλνει· Shift+Enter ξεκινά νέα γραμμή. Όνομα και ύφος είναι στο Προφίλ μου → My BOT DEE, όχι κουμπί στη συνομιλία."},"help-botdee-place-search":{"title":"Ρωτήστε τον BOT DEE για χώρους FLOQR","body":"Ρωτήστε απλά — εστιατόρια σούσι στην Washington DC, clubs στην DC ή ένα club με όνομα. Ο BOT DEE ψάχνει μόνο onboarded χώρους FLOQR, όχι Google ή Yelp. Τα αποτελέσματα ανοίγουν μια συμπαγή Place SMARTview (όνομα, σύντομο κείμενο, βαθμολογίες, σύνδεσμος δημόσιας σελίδας) με SMARTbackground — όχι πηγάδι φωτογραφίας. Φωτογραφίες patrons και pitches ShoutOut / VIP μένουν εκτός εκτός αν τα ζητήσατε. Αν δεν υπάρχει ακόμα, ο BOT DEE το λέει."},"help-botdee-page":{"title":"BOT DEE","body":"Συνομιλήστε με τον BOT DEE στη σελίδα BOT DEE με απλά λόγια: εκδηλώσεις και κλαμπ, ShoutOut, Mingl, RydR, BartR, FloqCAST, το προφίλ σας, προγράμματα προσωπικού ή εργαλεία Club Admin. Πατήστε Enter για αποστολή· Shift+Enter ξεκινά νέα γραμμή. Ο BOT DEE συνομιλεί σαν άνθρωπος (δοκιμάστε How are you?) και αναζητά μόνο όταν ρωτάτε πώς να κάνετε κάτι στο FLOQR. Αν έχετε συνδεθεί, ο BOT DEE κρατά αυτή τη συνομιλία αν ανανεώσετε ή ανοίξετε άλλο τηλέφωνο, και μετά την παύση μπορεί να συνεχίσει το αποθηκευμένο ιστορικό. Η παύση δεν διαγράφει τη συνομιλία. Οι απαντήσεις χρησιμοποιούν την ταξινόμηση του λογαριασμού σας. Αν έχετε συνδεθεί, ο BOT DEE βλέπει τα ίδια δημόσια εθελοντικά datapoints προφίλ με εσάς (μουσική, φαγητό, ταξίδια, χόμπι και τα υπόλοιπα του Privacy datapoint sharing) — ποτέ email, τηλέφωνο, στοιχεία κάρτας ή GPS. Πατήστε Ρυθμίσεις κάτω από το πλαίσιο συνομιλίας για αποθηκευμένες συνομιλίες και μνήμες. Πατήστε μια φωτογραφία στη συνομιλία για να ανοίξει σε παράθυρο. Κλείστε με X ή Κλείσιμο για να δείτε πάλι τη συνομιλία. Το + πάνω δεξιά ανοίγει αποθηκευμένες συνομιλίες και δεν τις διαγράφει."},"help-botdee-smartview-troubleshoot":{"title":"Αντιμετώπιση SMARTview","body":"Κενή κάρτα: κρυμμένα πεδία ή αποκλεισμός. Αποτυχία αποθήκευσης: συνδεθείτε — οι μεταφράσεις είναι στον διακομιστή. Εκκρεμές/αποτυχία: γλώσσα πηγής με σήμανση. Μόνο ο κάτοχος επεξεργάζεται. Το SMARTviews Master Admin μένει mock. Places/Yelp κλειστά. Το θέμα ακολουθεί το Site Chrome."},"help-botdee-smartcard-sync":{"title":"Το SMARTsummary μένει συγχρονισμένο","body":"Επεξεργαστείτε το SMARTsummary στην προεπιλεγμένη γλώσσα προφίλ. Η αποθήκευση είναι άμεση. Ανοιχτές κάρτες και SMARTview ενημερώνονται από την ίδια εγγραφή. Οι μεταφράσεις τρέχουν στο παρασκήνιο και δεν αντικαθιστούν νεότερη επεξεργασία. Αν κρύψετε το προφίλ, αποκλείσετε κάποιον ή διαγράψετε τον λογαριασμό, οι κάρτες εξαφανίζονται. Το Gemini δεν αντικαθιστά το κείμενό σας."},"help-botdee-smartcard-search":{"title":"Ρωτήστε τον BOT DEE ποιος είναι κάποιος","body":"Το «Who am I?» ανοίγει το SMARTview σας. Το «Who is …», «What do you know of …» ή «What about …» με όνομα, επώνυμο, εμφανιζόμενο όνομα, handle Mingl ή FloqR, ή social handle (Instagram, TikTok, X). Μόνο αυτά τα πεδία ταυτότητας — όχι βιογραφικά, likes, ποτά ή είδη. Ένα αποτέλεσμα ανοίγει κάρτα People SMARTview στη συνομιλία — όχι λίστα markdown ούτε πλέγμα φωτογραφιών. Πολλά δείχνουν συμπαγείς SMARTcard. Ιδιωτικά, αποκλεισμένα ή μη δημοσιευμένα δεν εμφανίζονται — ο BOT DEE δεν επιβεβαιώνει αν υπάρχει λογαριασμός."},"help-botdee-smartcard":{"title":"SMARTcard ατόμων","body":"Όταν ταιριάζουν περισσότερα δημόσια προφίλ FLOQR, ο BOT DEE δείχνει συμπαγείς SMARTcard στη συνομιλία: πρώτα φωτογραφία σε πλήρες πλάτος, μετά όνομα και handle, μετά συμπαγές SMARTsummary χωρίς γεμάτο πλαίσιο. Πατήστε για πλήρες SMARTview — ίδια στοίβαξη. Οι κάρτες χρησιμοποιούν το ίδιο δημόσιο προφίλ και SMARTsummary. Το άνοιγμα δεν καλεί Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Πληκτρολογήστε Ver, Vers ή Version — τα κεφαλαία δεν μετράνε. Η BOT DEE δείχνει την κάρτα έκδοσης. Μια μεγαλύτερη ερώτηση όπως «ποια είναι η έκδοσή σου;» δείχνει επίσης αυτή την κάρτα."},"help-botdee-version-smartview-status":{"title":"Η κατάσταση Version SMARTview είναι ζωντανός έλεγχος","body":"Η κατάσταση υπηρεσίας ελέγχεται σε αυτό το αίτημα Version: Functions και πακέτο προσβάσιμα με ρυθμισμένο Gemini → Λειτουργικό; Functions και πακέτο εντάξει αλλά Gemini μη ρυθμισμένο → Υποβαθμισμένο; Functions εκτός αυτού του αιτήματος → Μη διαθέσιμο. Ποτέ στατική ετικέτα Δεν ελέγχθηκε. Το μοντέλο ΤΝ δείχνει το ρυθμισμένο id Gemini αυτού του deployment ακόμα κι αν αυτός ο γύρος δεν παρήγαγε. Τα σφραγίσματα frontend και backend μπορεί να διαφέρουν· και τα δύο έχουν ετικέτα. Ο Master Admin μπορεί να δει επιπλέον διάγνωση στις Τεχνικές λεπτομέρειες — οι patrons όχι."},"help-botdee-version-smartview-tabs":{"title":"Καρτέλες Version SMARTview","body":"Η Επισκόπηση περιγράφει το BOT DEE και ανοίγει Τεχνικές λεπτομέρειες χωρίς να φύγετε από τη συνομιλία. Νέα δείχνει μόνο επαληθευμένες αλλαγές BOT DEE και Gemini — όχι Master Admin, εργαλεία beta tester ή άλλες σημειώσεις προϊόντος FLOQR. Βοήθεια επαναλαμβάνει την εντολή Ver / Vers / Version. Αλλαγή καρτέλας ή ανάπτυξη κρατά το μη σταλμένο πρόχειρο και την κύλιση. Η κάρτα χρησιμοποιεί το Site Chrome σας — δεν υπάρχει δεύτερο θέμα."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"Στη συνομιλία BOT DEE πείτε Open Room SMARTview, Start a group chat ή σχεδιάστε ταξίδι Cancun με απλά λόγια. Έπειτα: Συμμετοχή τώρα ή Ορισμός προγράμματος. Η συμμετοχή τώρα ανοίγει συνεδρία φίλων Mingl τώρα και δεν βάζει κάρτα στο Search. Ορισμός προγράμματος είναι η έναρξη του BOT DEE room — όχι Shared Itinerary — και ενεργοποιεί Search SMARTnotification για εσάς και προσκεκλημένους φίλους Mingl. Προσκαλέστε μόνο φίλους Mingl — host συν 7 επισκέπτες. Οι επισκέπτες μπορούν επίσης να προσκαλούν. Η είσοδος δεν είναι πληρωμή και δεν ανοίγει κοινό λογαριασμό. Το BOT DEE δεν παίρνει ποτέ αριθμούς κάρτας. Τα ιδιωτικά μηνύματα BOT DEE μένουν ιδιωτικά. Το Site Chrome ακολουθεί Appearance. Ένα live room μένει ανοιχτό μέχρι End Room, περίπου τέσσερις ώρες μετά το άνοιγμα, ή αν όλοι έχουν φύγει περίπου 15 λεπτά. Η παύση ιδιωτικής συνομιλίας BOT DEE είναι ξεχωριστή."},"help-botdee-room-smartview-invite":{"title":"Πρόσκληση φίλων Mingl","body":"Μετά το Confirm, το Invite δείχνει μόνο τους φίλους Mingl. Κάθε πρόσκληση δεσμεύεται σε αυτόν τον φίλο και φτάνει στο Inbox ως Review BOT DEE invite. Όχι δημόσιος σύνδεσμος. Όριο: οικοδεσπότης συν 7. Οι επισκέπτες μπορούν να προσκαλούν περισσότερους φίλους Mingl μέχρι ο οικοδεσπότης να το κλείσει. Η συμμετοχή δεν είναι πληρωμή. Αν ένα chip είστε εσείς ή κάποιος ήδη στη συνεδρία, μένει Είστε εσείς ή Ήδη στη συνεδρία και δεν στέλνει δεύτερη πρόσκληση."},"help-botdee-room-smartview-join":{"title":"Συμμετοχή σε συνεδρία BOT DEE","body":"Ανοίξτε την πρόσκληση Inbox συνδεδεμένοι ως ο φίλος Mingl στον οποίο στάλθηκε. Λάθος λογαριασμός, λήξη ή ανάκληση αρνείται. Η είσοδος στη room δεν είναι είσοδος σε λογαριασμό ούτε έγκριση πληρωμής. Το BOT DEE δεν παίρνει ποτέ αριθμούς καρτών."},"help-botdee-room-smartview-end":{"title":"Τέλος Room SMARTview","body":"Μόνο ο host μπορεί να τελειώσει μια room. Το τέλος δεν χρεώνει κανέναν και δεν σβήνει ιδιωτικές συνομιλίες άλλων. Ένας απλήρωτος κοινός λογαριασμός πρέπει πρώτα να πληρωθεί ή να ακυρωθεί. Ένα live room μένει ανοιχτό μέχρι End Room, περίπου τέσσερις ώρες μετά το άνοιγμα, ή αν όλοι έχουν φύγει περίπου 15 λεπτά. Η παύση ιδιωτικής συνομιλίας BOT DEE δεν είναι αποσύνδεση room. Ένας επισκέπτης που φεύγει δεν τελειώνει τη room όσο ο host είναι εκεί."},"help-botdee-room-smartview-tab":{"title":"Κοινός λογαριασμός Room SMARTview","body":"Πρώτα opt-in. Μετά προσθέστε γραμμή. Κλείστε με έναν πληρωτή ή μοιρασμένα. Χρεώνονται μόνο uid που επιβεβαιώνουν, μέσω FloqR Stripe. Η είσοδος στη room δεν είναι είσοδος στον λογαριασμό. Το BOT DEE δεν παίρνει ποτέ αριθμούς καρτών. Club POS αργότερα."},"help-botdee-room-smartview-who-pays":{"title":"Ποιος πληρώνει","body":"Ρωτήστε Who’s paying σε Room SMARTview για να δείτε το opt-in. Κανείς δεν χρεώνεται επειδή κάποιος είπε buy. Τα τελευταία τέσσερα της κάρτας μένουν στην απόδειξη του πληρωτή."},"help-botdee-room-smartview-kick":{"title":"Αφαίρεση από Room SMARTview","body":"Μόνο ο οικοδεσπότης αφαιρεί επισκέπτη. Ένας απομακρυσμένος φίλος δεν διαβάζει άλλα μηνύματα room. Απάντηση μοντέλου δεν αποκλείει κανέναν."},"help-botdee-room-smartview-share":{"title":"Κοινοποίηση σε Room SMARTview","body":"Το Share this conversation δεν αντιγράφει ποτέ το ιδιωτικό νήμα BOT DEE. Το BOT DEE δείχνει προεπισκόπηση επιλεγμένων κοινοποιήσιμων στοιχείων από αυτό το μήνυμα, ως προσωρινά. Μπορείτε να επεξεργαστείτε ή να αφαιρέσετε στοιχεία. Προφίλ και SMARTsummary μένουν έξω από τη room."},"help-botdee-room-smartview-schedule":{"title":"Συμμετοχή τώρα ή ορισμός προγράμματος","body":"Μετά το setup Room SMARTview επιλέξτε Συμμετοχή τώρα ή Ορισμός προγράμματος. Η συμμετοχή τώρα ανοίγει τη συνεδρία BOT DEE τώρα και δεν βάζει κάρτα στο Search. Ορισμός προγράμματος είναι η έναρξη του BOT DEE room — όχι Shared Itinerary. Μελλοντική ώρα ενεργοποιεί Search SMARTnotification μόνο για εσάς και προσκεκλημένους φίλους Mingl. Οι επισκέπτες RSVP μέχρι το room να είναι live· μετά το Join Now ανοίγει BOT DEE (όχι Mingl chat)."},"help-botdee-room-collab":{"title":"Κοινή headless κράτηση στο Room SMARTview","body":"Σε ένα Room SMARTview οι επιλογές VIP reserV ή ShoutOut του οικοδεσπότη φαίνονται σε όλους. Τα μέλη ψηφίζουν Ναι ή Όχι. Το Hold it και η πληρωμή μένουν στον οικοδεσπότη — η συμμετοχή και η ψήφος δεν είναι πληρωμή. Το BOT DEE δεν παίρνει ποτέ αριθμούς κάρτας. Το Stripe ανοίγει σε pop-out."},"help-botdee-room-elect-host":{"title":"Εκλογή οικοδεσπότη Room SMARTview","body":"Οποιοσδήποτε στη συνεδρία μπορεί να είναι οικοδεσπότης. Προτείνετε τον εαυτό σας ή άλλο μέλος. Ένας υποψήφιος γίνεται οικοδεσπότης στο 60% των τρεχόντων μελών (στρογγυλοποίηση προς τα πάνω). Αν φύγει ο οικοδεσπότης, οι υπόλοιποι εκλέγουν νέο — το room μένει ανοιχτό. Kick και End μένουν στον εκλεγμένο οικοδεσπότη."},"help-botdee-smartview-review":{"title":"Έλεγχος και διόρθωση SMARTsummary","body":"Το Gemini συντάσσει μόνο από δημόσια πεδία FLOQR — όχι σε κάθε προβολή. Λάθος γεγονός: αποκρύψτε το πεδίο ή επεξεργαστείτε την περίληψη. Το κείμενό σας δεν αντικαθίσταται. Σύγκρουση προφίλ ζητά έλεγχο. Αναφέρετε λάθος κάρτα από την επικάλυψη."},"help-botdee-smartview-chrome":{"title":"SMARTview και Site Chrome","body":"Το People SMARTview χρησιμοποιεί το FLOQR Site Chrome του θεατή (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Δεν υπάρχει δεύτερο θέμα. Η αλλαγή chrome ενημερώνει την κάρτα χωρίς απώλεια προσχεδίου."},"help-botdee-smartview-categories":{"title":"Κατηγορίες SMARTview","body":"Τέσσερις καρτέλες: Κοινωνικά, Γνωριμίες, Εστίαση, Μελλοντικά ταξίδια. Τα Κοινωνικά ανοίγουν στη Μουσική, μετά Nightlife, Αθλητισμός, Εκδηλώσεις. Οι ετικέτες είναι μόνο όσα μοιραστήκατε — χωρίς διπλούς τίτλους ή επινοημένα ταξίδια."},"help-botdee-smartview-media":{"title":"Φωτογραφίες και βίντεο SMARTview","body":"Η συμπαγής κάρτα χρησιμοποιεί το ίδιο κύριο μέσο με τη δημόσια σελίδα FLOQR — το πρώτο στοιχείο Profile Media (8 φωτογραφίες + 2 βίντεο). Πατήστε για Φωτογραφίες και Βίντεο από αυτές τις δημόσιες θέσεις. Σύρετε ή βέλη, μετά X (ή Escape) επιστρέφετε στην ίδια συνομιλία και προσχέδιο."},"help-botdee-smartview-privacy":{"title":"Απόρρητο SMARTview","body":"Το SMARTview δείχνει μόνο πεδία ήδη δημόσια στο FLOQR. Δεν είναι αναζήτηση ιστού. Γνωριμίες μόνο με opt-in. Απόκρυψη πεδίου στο προφίλ το αφαιρεί. Οι αποκλεισμένοι δεν βλέπουν την κάρτα. Αναφέρετε λάθος περίληψη από την επικάλυψη."},"help-botdee-smartview-translation":{"title":"Μετάφραση SMARTview","body":"Το SMARTsummary αποθηκεύεται στην προεπιλεγμένη γλώσσα προφίλ — αυτή είναι η πηγή, ακόμη κι αν δεν είναι αγγλικά. Μετά την αποθήκευση το FLOQR βάζει σε ουρά μετάφραση για κάθε άλλη γλώσσα, συμπεριλαμβανομένων των Αγγλικών. Ένας αγγλόφωνος βλέπει το αγγλικό SMARTsummary όταν τελειώσει η εργασία. Σε εκκρεμότητα ή αποτυχία φαίνεται η γλώσσα πηγής με σήμανση — ποτέ παλιά μετάφραση ως τρέχουσα."},"help-botdee-smartview-edit":{"title":"Επεξεργασία SMARTsummary","body":"Μόνο εσείς επεξεργάζεστε το SMARTsummary στην προεπιλεγμένη γλώσσα προφίλ. Η αποθήκευση είναι άμεση. Οι μεταφράσεις τρέχουν στο παρασκήνιο. Το Gemini δεν αντικαθιστά το κείμενό σας. Αν αλλάξει το δημόσιο προφίλ, το FLOQR ζητά έλεγχο αντί αντικατάστασης."},"help-botdee-privacy-assistant":{"title":"Βοηθός απορρήτου BOT DEE","body":"Αλλάξτε στο Προφίλ μου τι βλέπουν άλλοι χρήστες FLOQR — το BOT DEE δεν προσθέτει δεύτερο δημόσιο διακόπτη. Λάθος διαδικτυακή αντιστοίχιση μπορείτε να αμφισβητήσετε χωρίς αλλαγή προφίλ. Το BOT DEE δεν υπόσχεται διαγραφή σε ιστότοπο τρίτου."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Κάθε σύσταση μπορεί να δείξει στοιχεία, ημερομηνία ελέγχου, εξατομίκευση και χορηγία. Μπορείτε να ζητήσετε από το BOT DEE να μην εξατομικεύσει αυτή την αναζήτηση."},"help-botdee-research-library":{"title":"Βιβλιοθήκη έρευνας BOT DEE","body":"Αποθηκεύστε μέρη και κάρτες που ρωτήσατε το BOT DEE. Ένα Google Place ID δεν αντιγράφει φωτογραφίες ή κριτικές. Μπορείτε να ανανεώσετε ή να διαγράψετε. Οι αδειοδοτημένες μνήμες μένουν κλειστές μέχρι έγκριση παρόχου."},"help-botdee-smartview":{"title":"Το SMARTview μου","body":"Το SMARTview μου δείχνει την κάρτα Προσώπου από δημόσια πεδία FLOQR, με τα ίδια Profile Media της δημόσιας σελίδας — όχι mock χώρων ή εστιατορίων. Η επεξεργασία SMART Summary αλλάζει την περίληψη στη γλώσσα προφίλ. Τα mock χώρων/εστιατορίων είναι στο Master Admin → Features → BOT DEE → SMARTviews. Χωρίς ζωντανά Places ή Yelp."},"help-botdee-memory":{"title":"Αποθηκευμένες συνομιλίες BOT DEE","body":"Ανοίξτε Λειτουργίες & παραγγελίες → Το BOT DEE μου για αποθήκευση μετά την παύση, εξαγωγή ή διαγραφή ιστορικού. Η παύση πέντε λεπτών κλείνει τη ζωντανή συνεδρία. Με opt-in το BOT DEE κρατά τη συνομιλία. Οι επισκέπτες δεν αποθηκεύονται. Το Mingl μένει στο Mingl."},"help-botdee-knows-of-me":{"title":"Τι γνωρίζει το BOT DEE για μένα","body":"Τα γεγονότα με την έγκρισή σας βρίσκονται σε Λειτουργίες & παραγγελίες → Το BOT DEE μου. Η λίστα είναι κενή αν η μνήμη είναι off ή δεν υπάρχουν δεδομένα. Εξαγωγή ή διαγραφή εδώ. Το BOT DEE δεν αποθηκεύει IP. Το Mingl δεν αντιγράφεται."},"help-search-settings-appearance":{"title":"Settings στην Search","body":"Στην οθόνη Search πατήστε Settings για να ανοίξετε Profile & Settings στην καρτέλα Appearance — εκεί είναι το Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Το πλακίδιο Settings χρησιμοποιεί το ίδιο πακέτο εικονιδίων chrome με τα άλλα σήματα Search."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"Το FloqR Inbox κρατά System Messages και εσωτερικά μηνύματα υποστήριξης. Η λίστα φορτώνει πρώτη ώστε τα μηνύματα να εμφανίζονται γρήγορα. Πατήστε το αιωρούμενο κουμπί New Message για σύνταξη — πληκτρολογήστε όνομα ή @username για επιτρεπόμενο παραλήπτη (Club Admin, CSR ή εγκεκριμένο προσωπικό). Η συνομιλία patron-προς-patron μένει στο Mingl μετά από αμοιβαίο Mingl. Το άνοιγμα πρόσκλησης βάρδιας δεν επιβεβαιώνει — ελέγξτε και Approve selected στο Work Calendar."},"help-become-dj":{"title":"Γίνε DJ","body":"Επιλέξτε το DJ ως ρόλο υπηρεσίας και συνεργαστείτε με συλλόγους."},"help-become-promoter":{"title":"Γίνε Promoter","body":"Ζητήστε Promoter πρόσβαση για λίστες καλεσμένων και καμπάνιες."},"help-template-tags":{"title":"Ετικέτες προτύπων","body":"Προσθέστε λέξεις που μπορεί να πληκτρολογήσουν οι πελάτες όταν ψάχνουν πρότυπο στον χώρο σας, όπως βραδιά αγώνα ή γενέθλια. Οι Υπεύθυνοι προτύπων μπορούν να προσθέτουν ετικέτες. Οι Διαχειριστές προτύπων και οι Club Admin μπορούν επίσης να τις αφαιρούν. Ο Club Admin αναθέτει αυτούς τους ρόλους στο Role Activity & Permission."},"help-vip-door-pass":{"title":"Πάσο πόρτας VIP reserV","body":"Μετά την επιβεβαίωση προκαταβολής, Το προφίλ μου → Κρατήσεις → Εμφάνιση πάσου για QR μίας χρήσης. Φέρτε ID 21+. Το προσωπικό χρησιμοποιεί VIP reserV Door."},"help-vip-door-ops":{"title":"Check-in πόρτας VIP reserV","body":"Οι VIP Managers ανοίγουν VIP reserV Door για απόψε. Σαρώστε ή επικολλήστε token, επιβεβαιώστε ID 21+, check-in. No-show μόνο μετά από grace. Σύνδεσμος notify δεν αλλάζει κατάσταση."}},"pl":{"help-smartvisuals-notification":{"title":"SMARTnotification Mingl Room","body":"Kompaktowe zaproszenie Mingl Room może pojawić się na Search, gdy znajomy Mingl zaplanował room BOT DEE, na które Cię zaproszono. Zobacz zaproszenie otwiera Room SMARTview. Join Now idzie do BOT DEE, nie Mingl chat. Nie teraz chowa kartę w tej karcie; Inbox zostawia Review BOT DEE invite. Demo Cancun jest tylko Studio. Grafika to ilustracja, nie zdjęcie. Roomy Join Now bez harmonogramu nie pojawiają się na Search."},"help-smartvisuals-room":{"title":"Room SMARTview ze SMARTvisuals","body":"Room SMARTview pokazuje zaproszenie Mingl: harmonogram, RSVP lub status na żywo oraz Join Now. Join Now na Search otwiera BOT DEE (nie Mingl chat) z room= i t=. SMARTstencils i SMARTbackgrounds idą za autoryzowanym tytułem — Cancun Trip używa grafiki podróży, nie prawdziwego zdjęcia Cancun. Prywatny czat BOT DEE nigdy nie wybiera grafiki. Oznakowane Ad poniżej to próbka z tych tagów. Puste przy czacie prywatnym lub iniekcji; to nie żywy reklamodawca."},"help-scheduling-schedule-for":{"title":"Planowanie personelu","body":"Planuj zmiany i bookingi, a potem powiadamiaj każdą osobę przez Inbox, Email, SMS lub WhatsApp. W sekcji „Grafik dla” wybierz, czyim kalendarzem się zajmujesz: „Mój grafik DJ” to twój własny kalendarz, „Klub” pokazuje kluby, którymi zarządzasz, a „Firma promocyjna” firmy, dla których promujesz. Każdy kalendarz ma własną subskrypcję za 20 $/miesiąc. Zmiany przypisane tobie pojawiają się w „Moje przydziały”, gdzie je potwierdzasz lub odrzucasz."},"help-staff-marketing-consent":{"title":"Zgoda marketingowa personelu","body":"Dołączając do zespołu lokalu lub wydarzenia, musisz zaznaczyć pole zgody marketingowej. Pozwala ona temu lokalowi lub organizatorowi oraz jego administratorom i menedżerom używać Twojej nazwy FLOQR, roli oraz opublikowanych zdjęć i filmów na swoich stronach, ulotkach i w mediach społecznościowych (Instagram, Facebook, TikTok, YouTube i podobne) bez ponownego pytania o każde użycie. Nie mogą publikować Twojego numeru telefonu ani adresu e-mail. Zgodę możesz wycofać w każdej chwili w sekcji Mój profil, karta Usługi i członkowie serwisu. Wycofanie zatrzymuje nowy marketing; materiałów już wydrukowanych lub opublikowanych nie trzeba wycofywać. Club Admini widzą status zgody każdej osoby w Sieci pracowników i personelu oraz w Wyróżnionym personelu."},"help-botdee-privacy-session":{"title":"Prywatność i sesja BOT DEE","body":"Pięciominutowa pauza kończy sesję na żywo. Nie usuwa tego czatu dla zalogowanych, wspomnień ani przepływów. Zostają też kopie w Mój profil → Funkcje i zamówienia → My BOT DEE. Goście pozostają tymczasowi. Czaty Mingl nigdy nie są tu kopiowane. Enter wysyła; Shift+Enter zaczyna nową linię. Imię i ton ustawisz w Mój profil → My BOT DEE, nie przyciskiem na czacie."},"help-botdee-place-search":{"title":"Zapytaj BOT DEE o lokale FLOQR","body":"Pytaj zwykłym językiem — restauracje sushi w Washington DC, kluby w DC albo konkretny klub. BOT DEE szuka tylko onboardowanych venue FLOQR, nie Google ani Yelp. Trafienia otwierają zwartą kartę Place SMARTview (nazwa, krótki opis, oceny, link do strony publicznej) ze SMARTbackground — nie studnią zdjęcia. Zdjęcia patronów i pitch ShoutOut / VIP zostają pominięte, chyba że o nie poprosisz. Jeśli nic jeszcze nie jest onboardowane, BOT DEE to powie."},"help-botdee-page":{"title":"BOT DEE","body":"Czatuj z BOT DEE na stronie BOT DEE prostymi słowami: wydarzenia i kluby, ShoutOut, Mingl, RydR, BartR, FloqCAST, Twój profil, grafiki personelu lub narzędzia Club Admin. Naciśnij Enter, aby wysłać; Shift+Enter zaczyna nową linię. BOT DEE rozmawia jak człowiek (spróbuj How are you?) i szuka tylko gdy pytasz, jak coś zrobić w FLOQR. Po zalogowaniu BOT DEE zachowuje ten czat przy odświeżeniu lub na drugim telefonie, a po pauzie może wrócić do zapisanej historii. Pauza nie usuwa czatu. Odpowiedzi używają klasyfikacji Twojego konta. Po zalogowaniu BOT DEE widzi te same dobrowolnie publiczne datapointy profilu co Ty (muzyka, jedzenie, podróże, hobby i reszta Privacy datapoint sharing) — nigdy e-mail, telefon, dane karty ani GPS. Dotknij Ustawienia pod polem czatu, aby otworzyć zapisane czaty i wspomnienia. Dotknij zdjęcia na czacie, aby otworzyć je w osobnym oknie. Zamknij X lub Zamknij, aby wrócić do czatu. Znak + w prawym górnym rogu otwiera zapisane czaty i ich nie usuwa."},"help-botdee-smartview-troubleshoot":{"title":"Rozwiązywanie problemów SMARTview","body":"Pusta karta: ukryte pola lub blokada. Zapis nieudany: zaloguj się — tłumaczenia są na serwerze. Oczekujące/błąd: język źródłowy z etykietą. Edytuje tylko właściciel. SMARTviews Master Admin to nadal mock; Places i Yelp wyłączone. Motyw idzie za Site Chrome."},"help-botdee-smartcard-sync":{"title":"SMARTsummary zostaje zsynchronizowane","body":"Edytuj SMARTsummary w domyślnym języku profilu. Zapis jest natychmiastowy. Otwarte karty i SMARTview aktualizują się z tego samego rekordu. Tłumaczenia idą w tle i nie nadpisują nowszej edycji. Ukrycie profilu, blokada lub usunięcie konta chowa te karty. Gemini nie nadpisuje Twojego tekstu."},"help-botdee-smartcard-search":{"title":"Zapytaj BOT DEE, kim ktoś jest","body":"„Who am I?” otwiera Twoje SMARTview. „Who is …”, „What do you know of …” lub „What about …” plus imię, nazwisko, nazwa wyświetlana, handle Mingl lub FloqR albo handle społecznościowy (Instagram, TikTok, X). Trafienia tylko po tych polach tożsamości — nie bio, polubienia, napoje ani gatunki. Jeden wynik otwiera kartę People SMARTview w czacie — nie listę markdown ani siatkę zdjęć. Więcej wyników to zwarte SMARTcard. Prywatne, zablokowane lub nieopublikowane nie są listowane — BOT DEE nie potwierdza, czy konto istnieje."},"help-botdee-smartcard":{"title":"SMARTcard osób","body":"Gdy pasuje więcej niż jeden publiczny profil FLOQR, BOT DEE pokazuje zwarte karty w czacie: najpierw zdjęcie na pełną szerokość, potem imię i handle, potem zwarty SMARTsummary bez wypełnionego pola. Dotknij, aby otworzyć pełny SMARTview — ten sam układ. Karty używają tego samego profilu i SMARTsummary. Otwarcie nie wywołuje Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Wpisz Ver, Vers lub Version — wielkość liter nie ma znaczenia. BOT DEE pokazuje kartę wersji. Dłuższe pytanie, na przykład „jaka jest twoja wersja?”, też pokazuje tę kartę."},"help-botdee-version-smartview-status":{"title":"Status Version SMARTview to żywa sonda","body":"Status usługi jest sondowany przy tym żądaniu Version: Functions i pakiet osiągalne z skonfigurowanym Gemini → Działa; Functions i pakiet ok, ale Gemini nieskonfigurowane → Ograniczone; Functions poza tym żądaniem → Niedostępne. Nigdy statyczna etykieta Nie sprawdzono. Model AI pokazuje skonfigurowane id Gemini tego wdrożenia nawet gdy ta tura nie generowała. Stemple frontendu i backendu mogą się różnić; oba są opisane. Master Admin może zobaczyć dodatkową diagnostykę w Szczegółach technicznych — patroni nie."},"help-botdee-version-smartview-tabs":{"title":"Karty Version SMARTview","body":"Przegląd opisuje BOT DEE i otwiera Szczegóły techniczne bez opuszczania czatu. Nowości wypisuje tylko zweryfikowane zmiany BOT DEE i Gemini — nie Master Admin, narzędzia beta testerów ani inne notatki produktów FLOQR. Pomoc powtarza polecenie Ver / Vers / Version. Zmiana karty lub rozwinięcie zostawia niewysłany szkic i przewijanie. Karta używa Twojego Site Chrome — nie ma drugiego motywu."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"W czacie BOT DEE powiedz Open Room SMARTview, Start a group chat albo zaplanuj wyjazd do Cancun zwykłymi słowami. Potem: Dołącz teraz lub Ustaw harmonogram. Dołącz teraz otwiera sesję znajomych Mingl od razu i nie kładzie karty na Search. Ustaw harmonogram to start room BOT DEE — nie Shared Itinerary — i włącza Search SMARTnotification dla Ciebie i zaproszonych znajomych Mingl. Zaproś tylko znajomych Mingl — host plus 7 gości. Goście też mogą zapraszać. Dołączenie to nie płatność i nie otwiera wspólnego rachunku. BOT DEE nigdy nie bierze numerów kart. Prywatne wiadomości BOT DEE zostają prywatne. Site Chrome idzie za Appearance. Live room zostaje otwarty do End Room, około czterech godzin po otwarciu, albo gdy wszyscy nieobecni są około 15 minut. Pauza prywatnego czatu BOT DEE jest osobna."},"help-botdee-room-smartview-invite":{"title":"Zaproś znajomych Mingl","body":"Po Confirm Invite pokazuje tylko Twoich znajomych Mingl. Każde zaproszenie jest powiązane z tym znajomym i trafia do Inbox jako Review BOT DEE invite. To nie jest publiczny link. Limit: gospodarz plus 7. Goście mogą zapraszać więcej znajomych Mingl, dopóki gospodarz tego nie wyłączy. Dołączenie nie jest płatnością. Jeśli chip to ty albo ktoś już w sesji, zostaje To ty albo Już w tej sesji i nie wysyła drugiego zaproszenia."},"help-botdee-room-smartview-join":{"title":"Dołącz do sesji BOT DEE","body":"Otwórz zaproszenie Inbox zalogowany jako znajomy Mingl, do którego je wysłano. Złe konto, wygaśnięcie lub odwołanie odmawia. Dołączenie do room to nie dołączenie do rachunku ani zgoda na płatność. BOT DEE nigdy nie bierze numerów kart."},"help-botdee-room-smartview-end":{"title":"Zakończ Room SMARTview","body":"Tylko host może zakończyć room. Zakończenie nikogo nie obciąża i nie kasuje prywatnych czatów innych. Nieopłacony wspólny rachunek trzeba najpierw zapłacić lub unieważnić. Live room zostaje otwarty do End Room, około czterech godzin po otwarciu, albo gdy wszyscy nieobecni są około 15 minut. Pauza prywatnego czatu BOT DEE to nie wylogowanie z room. Gość, który wychodzi, nie zamyka room, gdy host jest obecny."},"help-botdee-room-smartview-tab":{"title":"Wspólny rachunek Room SMARTview","body":"Najpierw opt-in. Potem dodaj pozycję. Zamknij jednym płatnikiem lub podziel. Obciążani są tylko potwierdzający uid przez FloqR Stripe. Dołączenie do room to nie dołączenie do rachunku. BOT DEE nigdy nie bierze numerów kart. Club POS później."},"help-botdee-room-smartview-who-pays":{"title":"Kto płaci","body":"Zapytaj Who’s paying w Room SMARTview, by zobaczyć opt-in. Nikt nie jest obciążany, bo ktoś powiedział buy. Ostatnie cztery karty zostają na paragonie płatnika."},"help-botdee-room-smartview-kick":{"title":"Usuń kogoś z Room SMARTview","body":"Tylko gospodarz może usunąć gościa. Usunięty znajomy nie czyta dalszych wiadomości room. Odpowiedź modelu nikogo nie wyrzuca."},"help-botdee-room-smartview-share":{"title":"Udostępnij w Room SMARTview","body":"Share this conversation nigdy nie kopiuje Twojego prywatnego wątku BOT DEE. BOT DEE pokazuje podgląd wybranych faktów z tej wiadomości, oznaczonych jako wstępne. Możesz edytować lub odrzucić fakty. Profile i SMARTsummary zostają poza room."},"help-botdee-room-smartview-schedule":{"title":"Dołącz teraz lub ustaw harmonogram","body":"Po konfiguracji Room SMARTview wybierz Dołącz teraz lub Ustaw harmonogram. Dołącz teraz otwiera sesję BOT DEE od razu i nie kładzie karty na Search. Ustaw harmonogram to start room BOT DEE — nie Shared Itinerary. Przyszła godzina włącza Search SMARTnotification tylko dla Ciebie i zaproszonych znajomych Mingl. Goście RSVP, aż room będzie na żywo; potem Join Now otwiera BOT DEE (nie Mingl chat)."},"help-botdee-room-collab":{"title":"Udostępnij rezerwację headless w Room SMARTview","body":"W Room SMARTview wybory VIP reserV lub ShoutOut gospodarza widzą wszyscy. Członkowie głosują Tak lub Nie. Hold it i płatność zostają u gospodarza — dołączenie i głos to nie płatność. BOT DEE nigdy nie bierze numerów kart. Stripe otwiera się w pop-out."},"help-botdee-room-elect-host":{"title":"Wybierz gospodarza Room SMARTview","body":"Każdy w sesji może być gospodarzem. Nominuj siebie lub innego członka. Kandydat zostaje gospodarzem przy 60% aktualnych członków (zaokrąglenie w górę). Jeśli gospodarz wyjdzie, pozostali wybierają nowego — room zostaje otwarty. Kick i End zostają u wybranego gospodarza."},"help-botdee-smartview-review":{"title":"Przejrzyj i popraw SMARTsummary","body":"Gemini szkicuje tylko z publicznych pól FLOQR — nie przy każdym otwarciu. Błędny fakt: ukryj pole lub edytuj podsumowanie. Twój tekst nie jest nadpisywany. Konflikt profilu prosi o przegląd. Zgłoś błędną kartę z nakładki."},"help-botdee-smartview-chrome":{"title":"SMARTview i Site Chrome","body":"People SMARTview używa Site Chrome FLOQR oglądającego (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Nie ma drugiego motywu. Zmiana chrome odświeża kartę bez utraty szkicu czatu."},"help-botdee-smartview-categories":{"title":"Kategorie SMARTview","body":"Cztery karty: Społeczność, Randki, Jedzenie, Przyszłe podróże. Społeczność otwiera się na Muzyce, potem Nightlife, Sport, Wydarzenia. Tagi to tylko to, co udostępniłeś — bez podwójnych nagłówków i wymyślonych podróży."},"help-botdee-smartview-media":{"title":"Zdjęcia i filmy SMARTview","body":"Zwarta karta używa tego samego zdjęcia głównego co publiczna strona FLOQR — pierwszy element Profile Media (8 zdjęć + 2 filmy). Dotknij Zdjęcia i Filmy z tych publicznych slotów. Przesuń lub strzałki, potem X (lub Escape) wraca do tego samego czatu i szkicu."},"help-botdee-smartview-privacy":{"title":"Prywatność SMARTview","body":"SMARTview pokazuje tylko pola już publiczne w FLOQR. To nie wyszukiwarka sieci. Randki tylko po opt-in. Ukryj pole w profilu — zniknie. Zablokowani nie widzą karty. Zgłoś błędne podsumowanie z nakładki."},"help-botdee-smartview-translation":{"title":"Tłumaczenie SMARTview","body":"Twój SMARTsummary jest zapisany w domyślnym języku profilu — to źródło, nawet gdy to nie angielski. Po zapisie FLOQR kolejuje tłumaczenie na każdy inny język, w tym angielski. Angielski widz widzi angielski SMARTsummary po zakończeniu zadania. Gdy trwa lub zawiedzie, widać język źródłowy z etykietą — nigdy stare tłumaczenie jako aktualne."},"help-botdee-smartview-edit":{"title":"Edytuj SMARTsummary","body":"Tylko Ty edytujesz SMARTsummary w domyślnym języku profilu. Zapis jest natychmiastowy. Tłumaczenia idą w tle. Gemini nie nadpisuje Twojego tekstu. Gdy profil publiczny się zmieni, FLOQR prosi o przegląd zamiast zastępować."},"help-botdee-privacy-assistant":{"title":"Asystent prywatności BOT DEE","body":"W Mój profil zmień, co widzą inni użytkownicy FLOQR — BOT DEE nie dodaje drugiego przełącznika publicznego. Błędne powiązanie z sieci możesz zgłosić bez zmiany profilu. BOT DEE nie obiecuje usunięcia na stronie trzeciej."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Każda rekomendacja może pokazać dowody, datę sprawdzenia, personalizację i sponsoring. Możesz poprosić BOT DEE, aby nie personalizował tego wyszukiwania."},"help-botdee-research-library":{"title":"Biblioteka badań BOT DEE","body":"Zapisuj miejsca i karty, o które pytałeś BOT DEE. Google Place ID to nie kopia zdjęć ani recenzji. Możesz odświeżyć lub usunąć. Licencjonowane cache zostaje wyłączone, dopóki dostawca nie zostanie zatwierdzony."},"help-botdee-smartview":{"title":"Zobacz mój SMARTview","body":"Zobacz mój SMARTview pokazuje Twoją kartę osoby z publicznych pól FLOQR, z tymi samymi Profile Media co strona publiczna — nie mocki klubów ani restauracji. Edytuj mój SMART Summary zmienia streszczenie w języku profilu. Mocki klubów/restauracji są w Master Admin → Features → BOT DEE → SMARTviews. Brak żywego Places ani Yelp."},"help-botdee-memory":{"title":"Zapisane czaty BOT DEE","body":"Otwórz Funkcje i zamówienia → Mój BOT DEE, aby zapisywać czaty po pauzie, eksportować lub usuwać historię. Pięciominutowa pauza kończy sesję na żywo. Po zgodzie BOT DEE zachowuje czat. Goście nie są zapisywani. Mingl zostaje w Mingl."},"help-botdee-knows-of-me":{"title":"Co BOT DEE wie o mnie","body":"Fakty zapisane za zgodą są w Funkcje i zamówienia → Mój BOT DEE. Lista jest pusta, gdy pamięć jest wyłączona lub brak danych. Eksport lub usuń tutaj. BOT DEE nie zapisuje IP. Mingl nie jest kopiowany."},"help-search-settings-appearance":{"title":"Settings na Search","body":"Na ekranie Search stuknij Settings, aby otworzyć Profile & Settings na karcie Appearance — tam jest Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Kafelek Settings używa tego samego pakietu ikon chrome co inne znaki Search."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"FloqR Inbox przechowuje System Messages i wewnętrzne wiadomości wsparcia. Lista ładuje się najpierw, aby wiadomości pojawiały się szybko. Dotknij pływającego przycisku New Message, aby napisać — wpisz imię lub @username, by znaleźć dozwolonego odbiorcę (Club Admin, CSR lub zatwierdzony personel). Czat patron-do-patron zostaje w Mingl po wzajemnym Mingl. Otwarcie zaproszenia na zmianę nie potwierdza — przejrzyj i Approve selected w Work Calendar."},"help-become-dj":{"title":"Zostań DJ","body":"Wybierz DJ jako swoją rolę usługową i połącz się z klubami."},"help-become-promoter":{"title":"Zostań Promoter","body":"Poproś o dostęp Promoter do list gości i kampanii."},"help-template-tags":{"title":"Tagi szablonów","body":"Dodaj słowa, które goście mogą wpisać, szukając szablonu w Twoim lokalu, np. wieczór meczowy albo urodziny. Menedżerowie szablonów mogą dodawać tagi. Administratorzy szablonów i Club Admin mogą je też usuwać. Club Admin przydziela te role w sekcji Role Activity & Permission."},"help-vip-door-pass":{"title":"Pass drzwi VIP reserV","body":"Po potwierdzeniu depozytu: Mój profil → Rezerwacje → Pokaż pass dla jednorazowego QR. Weź ID 21+. Personel używa VIP reserV Door."},"help-vip-door-ops":{"title":"Check-in drzwi VIP reserV","body":"VIP Managerowie otwierają VIP reserV Door na dziś. Zeskanuj lub wklej token, potwierdź ID 21+, check-in. No-show dopiero po grace. Link notify nie zmienia statusu."}},"ar":{"help-smartvisuals-notification":{"title":"SMARTnotification لـ Mingl Room","body":"يمكن أن تظهر دعوة Mingl Room مختصرة على Search عندما يجدول صديق Mingl room BOT DEE دُعيت إليها. عرض الدعوة يفتح Room SMARTview. Join Now يذهب إلى BOT DEE وليس Mingl chat. ليس الآن يخفي البطاقة في هذا التبويب؛ يبقى Inbox فيه Review BOT DEE invite. استعلام Cancun التجريبي لـ Studio فقط. الرسم توضيح وليس صورة. غرف Join Now بلا جدول لا تظهر على Search."},"help-smartvisuals-room":{"title":"Room SMARTview مع SMARTvisuals","body":"يعرض Room SMARTview دعوة Mingl: الجدول وRSVP أو الحالة المباشرة وJoin Now. Join Now على Search يفتح BOT DEE (وليس Mingl chat) مع room= وt=. تتبع SMARTstencils وSMARTbackgrounds العنوان المصرّح — Cancun Trip فن سفر وليس صورة Cancun حقيقية. دردشة BOT DEE الخاصة لا تختار الرسم أبداً. إعلان موسوم أسفلها عيّنة من تلك الوسوم. يبقى فارغاً للدردشة الخاصة أو الحقن وليس معلناً مباشراً."},"help-scheduling-schedule-for":{"title":"جداول الموظفين","body":"خطّط المناوبات والحجوزات ثم أبلغ كل شخص عبر Inbox أو Email أو SMS أو WhatsApp. من «الجدول لـ» اختر التقويم الذي تعمل عليه: «جدولي كـ DJ» هو تقويمك الخاص، و«نادٍ» يعرض النوادي التي تديرها، و«شركة ترويج» يعرض الشركات التي تروّج لها. لكل تقويم اشتراكه الخاص بـ 20 دولارًا شهريًا. تظهر المناوبات المسندة إليك في «مهامي» حيث تؤكدها أو ترفضها."},"help-staff-marketing-consent":{"title":"موافقة الطاقم على التسويق","body":"عند انضمامك إلى فريق مكان أو فعالية، يجب أن تحدد مربع الموافقة على التسويق. تسمح هذه الموافقة لذلك المكان أو المنظّم ومسؤوليه ومديريه باستخدام اسمك على FLOQR ودورك وصورك ومقاطع الفيديو المنشورة على مواقعهم الإلكترونية ومنشوراتهم ووسائل التواصل الاجتماعي (Instagram وFacebook وTikTok وYouTube وما شابهها) دون أن يطلبوا إذنك مجددًا لكل استخدام. لا يجوز لهم نشر رقم هاتفك أو بريدك الإلكتروني. يمكنك سحب الموافقة في أي وقت من ملفي، علامة تبويب أعضاء الخدمات والخدمة. يوقف السحب التسويق الجديد، ولا يلزم استرجاع المواد المطبوعة أو المنشورة بالفعل. يرى Club Admins حالة موافقة كل فرد من الطاقم في شبكة الموظفين والعاملين وفي الطاقم المميز."},"help-botdee-privacy-session":{"title":"خصوصية وجلسة BOT DEE","body":"توقف الخمس دقائق ينهي جلسة BOT DEE المباشرة. لا يحذف هذه المحادثة للمستخدم المسجّل أو الذكريات أو مسارات العمل. تبقى النسخ الاختيارية في ملفي → الميزات والطلبات → My BOT DEE أيضًا. يبقى الضيوف مؤقتين. لا تُنسخ محادثات Mingl إلى هنا. Enter يرسل؛ Shift+Enter يبدأ سطرًا جديدًا. الاسم والأسلوب من ملفي → My BOT DEE، وليس زرًا في المحادثة."},"help-botdee-place-search":{"title":"اسأل BOT DEE عن أماكن FLOQR","body":"اسأل بكلمات بسيطة — مطاعم السوشي في Washington DC أو النوادي في DC أو نادٍ باسمه. يبحث BOT DEE فقط في أماكن FLOQR المسجّلة، وليس Google أو Yelp. النتائج تفتح Place SMARTview مضغوطًا (الاسم، نبذة قصيرة، التقييمات، رابط الصفحة العامة) مع SMARTbackground — وليس بئر صورة. صور الرواد وعروض ShoutOut / VIP لا تظهر إلا إذا طلبتها. إذا لم يُدرج المكان بعد، يقول BOT DEE ذلك."},"help-botdee-page":{"title":"BOT DEE","body":"تحدث مع BOT DEE في صفحة BOT DEE بكلمات بسيطة: الفعاليات والنوادي وShoutOut وMingl وRydR وBartR وFloqCAST وملفك الشخصي وجداول الطاقم وأدوات Club Admin. اضغط Enter للإرسال؛ Shift+Enter يبدأ سطرًا جديدًا. يتحدث BOT DEE كشخص (جرّب How are you?) ويبحث فقط عندما تسأل كيف تفعل شيئًا في FLOQR. إذا سجّلت الدخول، يحتفظ BOT DEE بهذه المحادثة عند التحديث أو على هاتف آخر وبعد التوقف يمكنه متابعة السجل المحفوظ. التوقف لا يحذف المحادثة. تستخدم الإجابات تصنيف حسابك. بعد تسجيل الدخول يرى BOT DEE نفس نقاط البيانات العامة المتطوع بها التي تراها (الموسيقى والطعام والسفر والهوايات وبقية Privacy datapoint sharing) — لا بريد إلكتروني ولا هاتف ولا بيانات بطاقة ولا GPS. اضغط الإعدادات تحت صندوق الدردشة للمحادثات والذكريات المحفوظة. اضغط على صورة في المحادثة لفتحها في نافذة. أغلق بـ X أو إغلاق للعودة إلى المحادثة. علامة + أعلى اليمين تفتح المحادثات المحفوظة ولا تحذفها."},"help-botdee-smartview-troubleshoot":{"title":"استكشاف أخطاء SMARTview","body":"بطاقة فارغة: الحقول مخفية أو أنت محظور. فشل الحفظ: سجّل الدخول — الترجمات على الخادم. انتظار أو فشل: لغة المصدر بوسم. التعديل للمالك فقط. SMARTviews في Master Admin ما زال كتالوج المحاكاة؛ Places وYelp متوقفان. السمة تتبع Site Chrome."},"help-botdee-smartcard-sync":{"title":"يبقى SMARTsummary متزامنًا","body":"عدّل SMARTsummary بلغة الملف الافتراضية. الحفظ فوري. البطاقات وSMARTview المفتوحة تتحدّث من نفس السجل. تُترجم اللغات الأخرى في الخلفية ولا تستبدل تعديلاً أحدث. إذا أخفيت الملف أو حظرت شخصًا أو حذفت الحساب تختفي البطاقات. لا يستبدل Gemini نصك."},"help-botdee-smartcard-search":{"title":"اسأل BOT DEE من هذا الشخص","body":"«Who am I?» يفتح SMARTview الخاص بك. «Who is …» أو «What do you know of …» أو «What about …» مع الاسم الأول أو الأخير أو الاسم المعروض أو معرّف Mingl أو FloqR أو معرّف اجتماعي (Instagram أو TikTok أو X). المطابقة على حقول الهوية فقط — وليس السيرة أو الإعجابات أو المشروبات أو الأنواع. نتيجة واحدة تفتح بطاقة People SMARTview في الدردشة — وليس قائمة markdown أو شبكة صور. عدة نتائج تعرض SMARTcard مدمجة. الملفات الخاصة أو المحظورة أو غير المنشورة لا تُعرض — BOT DEE لا يؤكد وجود الحساب."},"help-botdee-smartcard":{"title":"SMARTcard الأشخاص","body":"عندما يطابق أكثر من ملف FLOQR عام، يعرض BOT DEE بطاقات مضغوطة في الدردشة: الصورة بعرض كامل أولاً، ثم الاسم والمعرّف، ثم SMARTsummary مضغوط بلا صندوق مبطّن. اضغط لفتح SMARTview الكامل — نفس الترتيب. البطاقات تستخدم نفس الملف العام وSMARTsummary. الفتح لا يستدعي Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"اكتب Ver أو Vers أو Version — لا يهم حجم الأحرف. تعرض BOT DEE بطاقة الإصدار. سؤال أطول مثل «ما إصدارك؟» يعرض هذه البطاقة أيضًا."},"help-botdee-version-smartview-status":{"title":"حالة Version SMARTview فحص حي","body":"تُفحص حالة الخدمة في طلب Version هذا: Functions والحزمة قابلان للوصول وGemini مضبوط → تشغيلي؛ Functions والحزمة جاهزان لكن Gemini غير مضبوط → متدهور؛ Functions ليست في هذا الطلب → غير متاح. ليست أبداً تسمية ثابتة «لم يُتحقق». يعرض نموذج الذكاء الاصطناعي معرّف Gemini المضبوط لهذا النشر حتى إن لم يولّد هذا الدور. يمكن أن يختلف ختم الواجهة عن الخلفية؛ كلاهما مُسمّى. قد يرى Master Admin تشخيصاً إضافياً تحت التفاصيل التقنية — الضيوف لا."},"help-botdee-version-smartview-tabs":{"title":"علامات Version SMARTview","body":"نظرة عامة تصف BOT DEE وتفتح التفاصيل التقنية دون مغادرة الدردشة. ما الجديد يعرض تغييرات BOT DEE وGemini الموثّقة فقط — وليس Master Admin أو أدوات مختبري بيتا أو ملاحظات منتجات FLOQR الأخرى. المساعدة تكرر أمر Ver / Vers / Version. تبديل العلامات أو توسيع التفاصيل يبقي المسودة غير المُرسلة والتمرير. البطاقة تستخدم Site Chrome لديك — لا يوجد مظهر ثانٍ."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"في دردشة BOT DEE قل Open Room SMARTview أو Start a group chat أو خطط لرحلة Cancun بكلام بسيط. بعد ذلك: انضم الآن أو تعيين جدول. انضم الآن يفتح جلسة أصدقاء Mingl فوراً ولا يضع بطاقة على Search. تعيين جدول هو وقت بدء room BOT DEE — وليس Shared Itinerary — ويفعّل SMARTnotification في Search لك ولأصدقاء Mingl المدعوين. ادعُ أصدقاء Mingl فقط — مضيف زائد 7 ضيوف. يمكن للضيوف الدعوة أيضاً. الانضمام ليس دفعاً ولا يفتح فاتورة مشتركة. BOT DEE لا يأخذ أرقام بطاقات أبداً. رسائل BOT DEE الخاصة تبقى خاصة. يتبع Site Chrome مظهر Appearance. تبقى الـ room المباشرة مفتوحة حتى End Room، أو نحو أربع ساعات بعد فتحها، أو إذا غاب الجميع نحو 15 دقيقة. إيقاف دردشة BOT DEE الخاصة أمر منفصل."},"help-botdee-room-smartview-invite":{"title":"دعوة أصدقاء Mingl","body":"بعد Confirm يعرض Invite أصدقاء Mingl فقط. كل دعوة مربوطة بذلك الصديق وتصل Inbox كـ Review BOT DEE invite. ليست رابط انضمام عاماً. الحد المضيف مع 7. يمكن للضيوف دعوة مزيد من أصدقاء Mingl ما لم يوقف المضيف ذلك. الانضمام ليس دفعاً. إذا كانت الشريحة أنت أو شخصاً موجوداً في الجلسة تُعلَّم هذا أنت أو موجود في هذه الجلسة ولا تُرسل دعوة ثانية."},"help-botdee-room-smartview-join":{"title":"الانضمام إلى جلسة BOT DEE","body":"افتح دعوة Inbox وأنت مسجّل كصديق Mingl المُرسَل إليه. الحساب الخطأ أو المنتهية أو الملغاة تُرفض. الانضمام إلى room ليس انضماماً إلى حساب مشترك ولا موافقة على دفع. BOT DEE لا يأخذ أرقام البطاقات أبداً."},"help-botdee-room-smartview-end":{"title":"إنهاء Room SMARTview","body":"المضيف وحده يمكنه إنهاء room. الإنهاء لا يحصّل أحداً ولا يمسح دردشات الآخرين الخاصة. يجب دفع الفاتورة المشتركة غير المدفوعة أو إلغاؤها أولاً. تبقى الـ room المباشرة مفتوحة حتى End Room، أو نحو أربع ساعات بعد فتحها، أو إذا غاب الجميع نحو 15 دقيقة. إيقاف دردشة BOT DEE الخاصة ليس خروجاً من الـ room. مغادرة ضيف لا تنهي الـ room ما دام المضيف موجوداً."},"help-botdee-room-smartview-tab":{"title":"الحساب المشترك Room SMARTview","body":"أولاً الموافقة. ثم أضف بنداً. أغلق بدافع واحد أو مقسّم. يُخصم فقط من الحسابات المؤكِّدة عبر FloqR Stripe. الانضمام إلى room ليس انضماماً إلى الحساب. BOT DEE لا يأخذ أرقام البطاقات أبداً. Club POS لاحقاً."},"help-botdee-room-smartview-who-pays":{"title":"من يدفع","body":"اسأل Who’s paying في Room SMARTview لرؤية حالة الموافقة. لا يُخصم أحد لأن شخصاً قال buy. آخر أربعة أرقام تبقى على إيصال الدافع."},"help-botdee-room-smartview-kick":{"title":"إزالة شخص من Room SMARTview","body":"المضيف فقط يخرج ضيفاً. الصديق المُزال لا يقرأ رسائل الـ room بعدها. رد النموذج لا يطرد أحداً."},"help-botdee-room-smartview-share":{"title":"المشاركة في Room SMARTview","body":"Share this conversation لا ينسخ محادثتك الخاصة في BOT DEE أبداً. يعرض BOT DEE معاينة حقائق قابلة للمشاركة من هذه الرسالة، معلَّمة مؤقتة. يمكنك تعديل الحقائق أو حذفها. الملفات الشخصية وSMARTsummary تبقى خارج الـ room."},"help-botdee-room-smartview-schedule":{"title":"انضم الآن أو عيّن جدولاً","body":"بعد إعداد Room SMARTview اختر انضم الآن أو تعيين جدول. انضم الآن يفتح جلسة BOT DEE فوراً ولا يضع بطاقة على Search. تعيين جدول هو وقت بدء room BOT DEE — وليس Shared Itinerary. وقت مستقبلي يفعّل SMARTnotification في Search لك ولأصدقاء Mingl المدعوين فقط. الضيوف يؤكدون RSVP حتى تصبح الـ room مباشرة؛ ثم Join Now يفتح BOT DEE (وليس Mingl chat)."},"help-botdee-room-collab":{"title":"مشاركة حجز headless في Room SMARTview","body":"في Room SMARTview تظهر اختيارات المضيف لـ VIP reserV أو ShoutOut للجميع. يصوّت الأعضاء بنعم أو لا. يبقى Hold it والدفع لدى المضيف — الانضمام والتصويت ليسا دفعًا. BOT DEE لا يأخذ أرقام بطاقات أبدًا. يفتح Stripe في نافذة منبثقة."},"help-botdee-room-elect-host":{"title":"انتخاب مضيف Room SMARTview","body":"أي شخص في الجلسة يمكن أن يكون مضيفًا. رشّح نفسك أو عضوًا آخر. يصبح المرشح مضيفًا عند 60٪ من الأعضاء الحاليين (تقريب لأعلى). إذا غادر المضيف، ينتخب الباقون مضيفًا جديدًا — تبقى الغرفة مفتوحة. يبقى Kick و End لدى المضيف المنتخب."},"help-botdee-smartview-review":{"title":"مراجعة وتصحيح SMARTsummary","body":"يصوغ Gemini من حقول FLOQR العامة فقط — ليس عند كل عرض. إن كان واقعًا خاطئًا أخفِ الحقل أو عدّل الملخص. لا يُستبدل نصك. تعارض الملف يطلب مراجعة. بلّغ عن بطاقة خاطئة من الطبقة."},"help-botdee-smartview-chrome":{"title":"SMARTview وSite Chrome","body":"يستخدم People SMARTview Site Chrome الحالي للمشاهد (Nightlife وTraditional وBlack Tiffany وWhite/Black وPurple & White وBlack & Dark Green). لا إعداد سمة ثانٍ. تغيير الكروم يحدّث البطاقة دون فقدان مسودة الدردشة."},"help-botdee-smartview-categories":{"title":"فئات SMARTview","body":"أربع علامات: اجتماعي، مواعدة، طعام، رحلات قادمة. الاجتماعي يفتح على الموسيقى ثم Nightlife والرياضة والفعاليات. الوسوم فقط ما شاركته — بلا عناوين مكررة أو رحلات أو تقييمات مخترعة. الرحلات القادمة للوجهات العامة فقط."},"help-botdee-smartview-media":{"title":"صور وفيديو SMARTview","body":"تستخدم البطاقة نفس الصورة الرئيسية لصفحة FLOQR العامة — أول عنصر في وسائط الملف (8 صور + فيديوهان). اضغط للصور والفيديو من تلك الخانات العامة. اسحب أو الأسهم، ثم X (أو Escape) للعودة لنفس الدردشة والمسودة."},"help-botdee-smartview-privacy":{"title":"خصوصية SMARTview","body":"يعرض SMARTview فقط الحقول التي جعلتها عامة داخل FLOQR. ليس بحثًا على الويب. المواعدة تظهر بموافقة صريحة فقط. إخفاء حقل في ملفي يزيله. المحظورون لا يرون البطاقة. بلّغ عن ملخص خاطئ من الطبقة."},"help-botdee-smartview-translation":{"title":"ترجمة SMARTview","body":"يُحفظ SMARTsummary بلغة الملف الافتراضية — تلك هي المصدر حتى إن لم تكن الإنجليزية. بعد الحفظ يضع FLOQR ترجمة لكل لغة أخرى في الانتظار، بما فيها الإنجليزية. يرى المشاهد الإنجليزي SMARTsummary بالإنجليزية عند اكتمال المهمة. أثناء الانتظار أو الفشل تُعرض لغة المصدر بوسم واضح — لا ترجمة قديمة كأنها الحالية."},"help-botdee-smartview-edit":{"title":"تعديل SMARTsummary","body":"أنت وحدك تعدّل SMARTsummary بلغة الملف الافتراضية. الحفظ فوري. تُترجم اللغات الأخرى في الخلفية. لا يستبدل Gemini نصك. إذا تغيّر الملف العام، يطلب FLOQR المراجعة بدل الاستبدال."},"help-botdee-privacy-assistant":{"title":"مساعد خصوصية BOT DEE","body":"غيّر في ملفي ما يراه مستخدمو FLOQR الآخرون — لا يضيف BOT DEE مفتاحًا عامًا ثانيًا. إذا ربط البحث شخصًا خطأ، يمكنك الاعتراض دون تغيير ملفك. لا يعد BOT DEE بحذف الصفحة الأصلية لدى طرف ثالث."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"يمكن لكل توصية إظهار الأدلة وتاريخ الفحص وما إذا كان التخصيص قيد التشغيل وما إذا كان الموضع مدعومًا. يمكنك أن تطلب من BOT DEE عدم تخصيص هذا البحث."},"help-botdee-research-library":{"title":"مكتبة بحث BOT DEE","body":"احفظ الأماكن والبطاقات التي سألت BOT DEE عنها. معرّف Google Place ليس نسخة من صور أو مراجعات Google. يمكنك التحديث أو الحذف. تبقى ذاكرة التخزين المرخّصة متوقفة حتى اعتماد المزود."},"help-botdee-smartview":{"title":"عرض SMARTview الخاص بي","body":"عرض SMARTview يظهر بطاقة الشخص من الحقول العامة في FLOQR، مع نفس وسائط الملف العام — وليست نماذج نوادٍ أو مطاعم. تعديل SMART Summary يغيّر الملخص بلغة الملف. نماذج النوادي/المطاعم في Master Admin → Features → BOT DEE → SMARTviews. لا Places أو Yelp مباشر."},"help-botdee-memory":{"title":"محادثات BOT DEE المحفوظة","body":"افتح الميزات والطلبات → BOT DEE الخاص بي لحفظ المحادثات بعد التوقف أو التصدير أو الحذف. توقف الخمس دقائق ينهي الجلسة المباشرة. إذا وافقت، يحتفظ BOT DEE بالمحادثة. لا يُحفظ الضيوف. يبقى Mingl في Mingl."},"help-botdee-knows-of-me":{"title":"ما يعرفه BOT DEE عني","body":"الحقائق المحفوظة بموافقتك في الميزات والطلبات → BOT DEE الخاص بي. القائمة فارغة إذا كانت الذاكرة مغلقة أو لا توجد بيانات. صدّر أو احذف هنا. لا يخزّن BOT DEE عنوان IP. لا يُنسخ Mingl."},"help-search-settings-appearance":{"title":"Settings في Search","body":"في شاشة Search، اضغط Settings لفتح Profile & Settings على تبويب Appearance — حيث يوجد Site chrome (Nightlife وTraditional وBlack Tiffany وWhite/Black وPurple & White وBlack & Dark Green). تستخدم بلاطة Settings نفس حزمة أيقونات الكروم لعلامات Search الأخرى."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"يحفظ FloqR Inbox رسائل System Messages ورسائل الدعم الداخلية. تُحمَّل القائمة أولاً لتظهر رسائلك بسرعة. اضغط زر New Message العائم للكتابة — اكتب اسمًا أو @username للعثور على مستلم مسموح (Club Admin أو CSR أو طاقم معتمد). محادثة patron-إلى-patron تبقى في Mingl بعد Mingl متبادل. فتح دعوة وردية لا يؤكدها — راجع ثم Approve selected في Work Calendar."},"help-become-dj":{"title":"أصبح DJ","body":"اختر DJ كدور الخدمة الخاص بك وارتبط بالأندية."},"help-become-promoter":{"title":"أصبح Promoter","body":"اطلب الوصول إلى Promoter لقوائم الضيوف والحملات."},"help-template-tags":{"title":"وسوم القوالب","body":"أضف كلمات قد يكتبها الزبائن عند البحث عن قالب في مكانك، مثل ليلة المباراة أو عيد الميلاد. يمكن لمديري القوالب إضافة الوسوم. ويمكن لمسؤولي القوالب وClub Admin إزالتها أيضًا. يعيّن Club Admin هذه الأدوار من قسم Role Activity & Permission."},"help-vip-door-pass":{"title":"تصريح باب VIP reserV","body":"بعد تأكيد العربون، ملفي → الحجوزات → عرض التصريح لرمز QR لمرة واحدة. أحضر هوية 21+. يستخدم طاقم الباب VIP reserV Door."},"help-vip-door-ops":{"title":"تسجيل الدخول عند الباب VIP reserV","body":"يفتح VIP Managers صفحة VIP reserV Door لهذه الليلة. امسح أو الصق الرمز، أكّد هوية 21+، ثم check-in. No-show فقط بعد المهلة. رابط notify لا يغيّر الحالة."}}};
  if (global.FLOQRHelpRepository && global.FLOQRHelpRepository.registerMany) {
    global.FLOQRHelpRepository.registerMany(entries);
  }
  if (global.FLOQRI18nHelp && global.FLOQRI18nHelp.mergePacks) {
    global.FLOQRI18nHelp.mergePacks(packs);
  }
  try { global.FLOQRI18nHelp && global.FLOQRI18nHelp.applyHelpDom && global.FLOQRI18nHelp.applyHelpDom(global.document); } catch (error) {}
})(typeof window !== "undefined" ? window : globalThis);
